-- Vorrats-Aufgaben (rollend-4) in bestehende Flüge einfügen: 307 Aufgaben, 22 Einheiten, mit form und zaehlt (FT-S). Ein Aufruf, eine Transaktion.
select set_config('lock_timeout', '3s', true), set_config('statement_timeout', '60s', true);
do $einspielen$
declare e record; n int; vorher int; gesamt int := 0; fehler text[] := '{}';
begin
  if (select count(*) from pg_attribute where attrelid = 'schule.aufgabe'::regclass and attname in ('form', 'zaehlt') and not attisdropped) <> 2
     or position('x->>''form''' in pg_get_functiondef('schule.aufgaben_einfuegen(bigint, jsonb)'::regprocedure)) = 0 then
    raise exception 'Vorrats-Aufgaben: erst FT-S einspielen (Spalten form/zaehlt, aufgaben_einfuegen)'; end if;
  for e in select * from (values
    (4, 'zahlen.teilbarkeit', 658, 15, $auf$[{"l": "vielfache", "t": "vielfache", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Die ersten Vielfachen von 6 sind 6, 12 und 18. Das vierte Vielfache ist 4 · 6 = ①. Drei Vielfache weiter ist es ① + 3 · 6 = ②. Weitere drei Vielfache weiter ist es ② + 3 · 6 = ③.", "schablone": "① = □; ② = □; ③ = □", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ)."}, "o": {"werte": [24, 42, 60]}, "h": "Das n-te Vielfache von 6 ist n · 6.", "w": "4 · 6 = 24. 24 + 18 = 42 (das siebte). 42 + 18 = 60 (das zehnte).", "form": "lueckenweg", "zaehlt": "nein", "r": 678}, {"l": "primzahl", "t": "primzahl", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Prüfe, ob 39 eine Primzahl ist. 39 : 3 = ①. Zu den Teilern 1, 3 und 39 kommt noch ① hinzu. Das sind genau ② Teiler. Eine Primzahl hat nur die Teiler 1 und sich selbst. Also hat 39 ③ Teiler mehr als eine Primzahl, und 39 ist keine Primzahl.", "schablone": "① = □; ② = □; ③ = □", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ)."}, "o": {"werte": [13, 4, 2]}, "h": "Zähle alle Teiler von 39 mit ihren Partnern.", "w": "39 : 3 = 13. Teiler: 1, 3, 13, 39. Das sind vier, also keine Primzahl. Eine Primzahl hat genau zwei Teiler.", "form": "lueckenweg", "zaehlt": "nein", "r": 681}, {"l": "teiler", "t": "teiler", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "auswahl", "f": {"text": "Wie findest du alle Teiler von 28 sicher?"}, "a": ["Teilerpaare suchen: 1 · 28, 2 · 14, 4 · 7. Teiler: 1, 2, 4, 7, 14, 28", "Nur bis 7 probieren. Teiler: 1, 2, 4, 7", "28 immer durch 2 teilen: 14, 7. Teiler: 14, 7", "Die Siebenerreihe aufschreiben: 7, 14, 21, 28. Teiler: 7, 14, 21, 28"], "o": {"index": 0}, "h": "Zu jedem Teiler gehört ein Partner mit dem Produkt 28.", "w": "Paare mit dem Produkt 28: 1 · 28, 2 · 14, 4 · 7. Das gibt sechs Teiler.", "form": "verfahren_waehlen", "zaehlt": "ja", "r": 682}, {"l": "vielfache", "t": "vielfache", "p": "uebung", "s": 2, "g": "einkleidung", "y": "auswahl", "f": {"text": "Bus A fährt alle 12 Minuten, Bus B alle 18 Minuten. Um 8:00 Uhr fahren beide gleichzeitig ab. Wie findest du, nach wie vielen Minuten sie zum ersten Mal wieder gleichzeitig abfahren?"}, "a": ["12 + 18 = 30 rechnen", "12 · 18 = 216 rechnen", "Beide Reihen aufschreiben (12, 24, 36 und 18, 36): die erste gemeinsame Zahl ist 36", "18 − 12 = 6 rechnen"], "o": {"index": 2}, "h": "Suche eine Zahl, die in der Zwölferreihe und in der Achtzehnerreihe steht – die kleinste.", "w": "Zwölferreihe: 12, 24, 36. Achtzehnerreihe: 18, 36. Zuerst gemeinsam: 36. Nach 36 Minuten fahren beide wieder zusammen ab.", "form": "verfahren_waehlen", "zaehlt": "ja", "r": 683}, {"l": "quersumme", "t": "quersumme", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "auswahl", "f": {"text": "Du willst wissen, ob 7 428 durch 3 teilbar ist. Welcher Weg führt sicher zum Ziel?"}, "a": ["Die Endziffer 8 ansehen. 8 ist nicht durch 3 teilbar, also auch 7 428 nicht", "Die Ziffern zählen: Es sind 4. 4 ist nicht durch 3 teilbar, also auch 7 428 nicht", "Quersumme 7 + 4 + 2 + 8 = 21 bilden. 21 ist durch 3 teilbar, also auch 7 428", "Die erste Ziffer 7 ansehen. 7 ist nicht durch 3 teilbar, also auch 7 428 nicht"], "o": {"index": 2}, "h": "Zähle alle Ziffern zusammen, nicht nur eine.", "w": "Die Quersumme 21 ist durch 3 teilbar, also ist 7 428 durch 3 teilbar: 7 428 : 3 = 2 476. Die anderen Wege schließen auf „nicht teilbar“ – das ist falsch.", "form": "verfahren_waehlen", "zaehlt": "ja", "r": 684}, {"l": "neunerregel", "t": "neunerregel", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "auswahl", "f": {"text": "Wie entscheidest du, ob 7 235 durch 9 teilbar ist?"}, "a": ["Quersumme 7 + 2 + 3 + 5 = 17 bilden. 17 ist nicht durch 9 teilbar, also ist 7 235 nicht durch 9 teilbar", "Quersumme 7 + 2 + 3 + 5 = 17 bilden. 17 ist durch 3 teilbar, also ist 7 235 durch 9 teilbar", "Die letzten zwei Ziffern 35 ansehen. 35 ist durch 9 teilbar, also ist 7 235 durch 9 teilbar", "Die erste Ziffer 7 ansehen. 7 ist nicht durch 9 teilbar, also ist 7 235 durch 9 teilbar"], "o": {"index": 0}, "h": "Bei der Neunerregel zählt die Quersumme, nicht eine einzelne Ziffer.", "w": "Quersumme: 7 + 2 + 3 + 5 = 17. 17 ist nicht durch 9 teilbar, also ist auch 7 235 nicht durch 9 teilbar.", "form": "verfahren_waehlen", "zaehlt": "ja", "r": 685}, {"l": "primfaktoren", "t": "primfaktoren", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "auswahl", "f": {"text": "Welche Zerlegung ist die Primfaktorzerlegung von 90?"}, "a": ["90 = 9 · 10", "90 = 2 · 5 · 9", "90 = 2 · 3 · 3 · 3", "90 = 2 · 3 · 3 · 5"], "o": {"index": 3}, "h": "Zerlege so lange, bis nur noch Primzahlen dastehen.", "w": "90 = 2 · 45 = 2 · 3 · 15 = 2 · 3 · 3 · 5. Alle Faktoren sind Primzahlen, und 2 · 3 · 3 · 5 = 90.", "form": "verfahren_waehlen", "zaehlt": "ja", "r": 686}, {"l": "teiler", "t": "teiler", "p": "uebung", "s": 3, "g": "fehler", "y": "auswahl", "f": {"text": "Kim prüft, ob 7 ein Teiler von 52 ist. Zeile 1: Ich rechne 52 : 7. Zeile 2: Es ist 7 · 7 = 49 und 7 · 8 = 56. Zeile 3: Es bleibt kein Rest, also ist 7 ein Teiler von 52. In welcher Zeile steckt der Fehler?"}, "a": ["In Zeile 1", "In Zeile 2", "In Zeile 3"], "o": {"index": 2}, "h": "Liegt 52 genau auf einem Ergebnis der Siebenerreihe?", "w": "52 liegt zwischen 49 und 56, ist also kein Vielfaches von 7. Es bleibt der Rest 3. 7 ist kein Teiler von 52.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 687}, {"l": "vielfache", "t": "vielfache", "p": "uebung", "s": 3, "g": "fehler", "y": "auswahl", "f": {"text": "Kim sucht die kleinste positive Zahl, die in der Viererreihe und in der Sechserreihe vorkommt. Zeile 1: Viererreihe: 4, 8, 12, 16, 20, 24. Zeile 2: Sechserreihe: 6, 12, 18, 24. Zeile 3: Die erste Zahl, die in beiden Reihen steht, ist 24. In welcher Zeile steckt der Fehler?"}, "a": ["In Zeile 1", "In Zeile 2", "In Zeile 3"], "o": {"index": 2}, "h": "Schau von links: Welche Zahl kommt zuerst in beiden Reihen vor?", "w": "In beiden Reihen steht schon die 12: 4 · 3 = 12 und 6 · 2 = 12. Die gesuchte Zahl ist 12.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 688}, {"l": "endziffer", "t": "endziffer", "p": "uebung", "s": 3, "g": "fehler", "y": "auswahl", "f": {"text": "Kim prüft die Zahl 2 450. Zeile 1: Die Endziffer ist 0. Zeile 2: Die Endziffer 0 heißt: Die Zahl ist durch 10 teilbar. Zeile 3: 2 450 ist durch 10 teilbar, aber nicht durch 5. In welcher Zeile steckt der Fehler?"}, "a": ["In Zeile 1", "In Zeile 2", "In Zeile 3"], "o": {"index": 2}, "h": "Jede Zahl, die durch 10 teilbar ist, ist auch durch 5 teilbar. Warum?", "w": "10 = 2 · 5. Was durch 10 geht, geht auch durch 5. 2 450 ist durch 10 und durch 5 teilbar.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 689}, {"l": "quersumme", "t": "quersumme", "p": "uebung", "s": 3, "g": "fehler", "y": "auswahl", "f": {"text": "Kim prüft, ob 4 281 durch 3 teilbar ist. Zeile 1: Quersumme: 4 + 2 + 8 + 1 = 15. Zeile 2: 15 : 3 = 5, es bleibt kein Rest. Zeile 3: Also ist 4 281 nicht durch 3 teilbar. In welcher Zeile steckt der Fehler?"}, "a": ["In Zeile 1", "In Zeile 2", "In Zeile 3"], "o": {"index": 2}, "h": "Was folgt, wenn die Quersumme durch 3 teilbar ist?", "w": "Die Quersumme 15 ist durch 3 teilbar. Dann ist auch 4 281 durch 3 teilbar: 4 281 : 3 = 1 427.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 690}, {"l": "primzahl", "t": "primzahl", "p": "uebung", "s": 3, "g": "fehler", "y": "auswahl", "f": {"text": "Kim prüft, ob 51 eine Primzahl ist. Zeile 1: 51 ist ungerade, also nicht durch 2 teilbar. Zeile 2: 51 endet nicht auf 0 oder 5, also nicht durch 5 teilbar. Zeile 3: Mehr Teiler muss ich nicht suchen: 51 ist eine Primzahl. In welcher Zeile steckt der Fehler?"}, "a": ["In Zeile 1", "In Zeile 2", "In Zeile 3"], "o": {"index": 2}, "h": "Prüfe auch die Quersumme: Ist 5 + 1 durch 3 teilbar?", "w": "Die Quersumme 5 + 1 = 6 ist durch 3 teilbar. Also ist 51 = 3 · 17 und keine Primzahl.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 691}, {"l": "primzahl", "t": "primzahl", "p": "uebung", "s": 2, "g": "darstellung", "y": "auswahl", "f": {"text": "Eine dieser vier Zahlen lässt sich nicht als Produkt zweier natürlicher Zahlen schreiben, die beide größer als 1 und kleiner als die Zahl selbst sind. Welche?"}, "a": ["27", "39", "41", "51"], "o": {"index": 2}, "h": "Suche bei jeder Zahl nach einem Teiler außer 1 und der Zahl selbst. Die Quersumme hilft bei 3.", "w": "27 = 3 · 9, 39 = 3 · 13 und 51 = 3 · 17 haben jeweils den Teiler 3 (die Quersumme ist durch 3 teilbar). 41 hat keinen Teiler außer 1 und 41, sie ist eine Primzahl.", "form": "bruecke", "zaehlt": "ja", "r": 692}, {"l": "teiler", "t": "teiler", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Wie viele Teiler hat die Zahl 18? Weg A: alle Teilerpaare von 18 finden und die Teiler zählen. Weg B: 18 = 2 · 3 · 3 zerlegen und (1 + 1) · (2 + 1) rechnen."}, "o": {"wert": 6}, "h": "Beide Wege müssen dieselbe Anzahl geben. Zähle bei Weg A alle Zahlen der Paare, nicht die Paare.", "w": "Weg A: Die Paare sind 1 · 18, 2 · 9 und 3 · 6, das sind die sechs Zahlen 1, 2, 3, 6, 9, 18. Weg B: (1 + 1) · (2 + 1) = 2 · 3 = 6. Die Zahl 18 hat 6 Teiler.", "form": "zwei_wege", "zaehlt": "ja", "r": 693}, {"l": "vielfache", "t": "vielfache", "p": "uebung", "s": 2, "g": "umkehr", "y": "zahl", "f": {"text": "Das 12-fache einer Zahl ist 84. Welche Zahl ist das?"}, "o": {"wert": 7}, "h": "Das 12-fache bedeutet mal 12. Wie macht man das rückgängig?", "w": "Gesucht ist die Zahl, die mal 12 genau 84 ergibt. Rückwärts geteilt: 84 : 12 = 7. Probe: 7 · 12 = 84.", "form": "umkehren", "zaehlt": "ja", "r": 694}]$auf$::jsonb),
    (6, 'gleichungen.einfach', 599, 5, $auf$[{"l": "probe", "t": "verstehen", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Kim meint, dass x = 4 die Gleichung 4 · x − 5 = 19 löst. Probe: 4 · 4 = ①. Dann ① − 5 = ②. Das ist nicht 19, also hat Kim sich geirrt: Der Wert ist 19 − ② = ③ zu klein. Pro Schritt von x wächst der Wert um 4, also fehlt bei x ein Stück von ③ : 4 = ④. Richtig ist x = 4 + ④ = ⑤.", "schablone": "① = □; ② = □; ③ = □; ④ = □; ⑤ = □", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ)."}, "o": {"werte": [16, 11, 8, 2, 6]}, "h": "Setze erst x ein, rechne dann Mal vor Minus.", "w": "4 · 4 = 16, 16 − 5 = 11. 19 − 11 = 8. 8 : 4 = 2. x = 4 + 2 = 6. Probe: 4 · 6 − 5 = 19.", "form": "lueckenweg", "zaehlt": "nein", "r": 620}, {"l": "aufstellen", "t": "anwenden", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Ich denke mir eine Zahl x. Das Dreifache von x, vermindert um 4, ergibt 17. Gleichung: 3 · x − 4 = 17. Rückwärts: 17 + 4 = ①. Dann ① : 3 = ②. Die gedachte Zahl ist ②.", "schablone": "① = □; ② = □", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ)."}, "o": {"werte": [21, 7]}, "h": "Kehre die Schritte in umgekehrter Reihenfolge um.", "w": "17 + 4 = 21. 21 : 3 = 7. Probe: 3 · 7 − 4 = 17.", "form": "lueckenweg", "zaehlt": "nein", "r": 621}, {"l": "ohne_loesung", "t": "loesbarkeit", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Hat 5 · x = 22 eine Lösung in den natürlichen Zahlen? Die Fünferreihe: 5 · 4 = ①. 5 · 5 = ②. Die Zahl 22 liegt zwischen ① und ② und ist also kein Vielfaches von 5. Der Rest von 22 : 5 ist 22 − ① = ③. Weil ein Rest bleibt, geht die Teilung nicht auf.", "schablone": "① = □; ② = □; ③ = □", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ)."}, "o": {"werte": [20, 25, 2]}, "h": "Wie oft passt die 5 ganz in die 22?", "w": "5 · 4 = 20 und 5 · 5 = 25. 22 − 20 = 2. Es bleibt ein Rest, also gibt es keine Lösung in den natürlichen Zahlen.", "form": "lueckenweg", "zaehlt": "nein", "r": 622}, {"l": "zwei_schritte", "t": "umkehren", "p": "uebung", "s": 3, "g": "fehler", "y": "auswahl", "f": {"text": "Kim löst 2 · x − 5 = 17. Zeile 1: Erst 5 abziehen: 2 · x = 12. Zeile 2: Dann durch 2 teilen: x = 6. Zeile 3: Die Lösung ist x = 6. In welcher Zeile passiert der erste Fehler?"}, "a": ["In Zeile 1", "In Zeile 2", "In Zeile 3"], "o": {"index": 0}, "h": "Der letzte Schritt war „minus 5“. Wie machst du ihn rückgängig?", "w": "Minus 5 macht man mit plus 5 rückgängig: 2 · x = 22, also x = 11. Probe: 2 · 11 − 5 = 17.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 623}, {"l": "aufstellen", "t": "anwenden", "p": "uebung", "s": 3, "g": "fehler", "y": "auswahl", "f": {"text": "Das Vierfache einer Zahl, um 6 vermehrt, ergibt 30. Kim sucht die Zahl. Zeile 1: Als Gleichung: 4 · x − 6 = 30. Zeile 2: Rückwärts: 30 + 6 = 36. Zeile 3: 36 : 4 = 9. Die Zahl ist 9. In welcher Zeile passiert der erste Fehler?"}, "a": ["In Zeile 1", "In Zeile 2", "In Zeile 3"], "o": {"index": 0}, "h": "Was bedeutet „vermehrt“: Wird die Zahl größer oder kleiner?", "w": "„Um 6 vermehrt“ heißt plus 6: 4 · x + 6 = 30. Rückwärts: 30 − 6 = 24 und 24 : 4 = 6. Die Zeilen 2 und 3 passen zur falschen Gleichung aus Zeile 1.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 624}]$auf$::jsonb),
    (13, 'daten.darstellen', 582, 9, $auf$[{"l": "tabelle_auswerten", "t": "tabelle_auswerten", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "In einer Tabelle stehen die Anzahlen Rot 6, Blau 9 und Grün 5. Summe: 6 + 9 + 5 = ①. Der Anteil von Blau ist 9 von ①. In Prozent sind das ② %.", "schablone": "① = □; ② = □", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ)."}, "o": {"werte": [20, 45]}, "h": "Zähle zuerst alle Anzahlen zusammen. Dann erweiterst du den Bruch auf Hundertstel.", "w": "9/20 = 45/100 = 45 %.", "form": "lueckenweg", "zaehlt": "nein", "r": 602}, {"l": "saeulendiagramm", "t": "saeulendiagramm", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "In einem Säulendiagramm steht 1 cm Höhe für 3 Kinder. Eine Säule ist 6 cm hoch. Sie gehört zu 6 · 3 = ① Kindern. Eine zweite Säule gehört zu 33 Kindern. Sie ist 33 : 3 = ② cm hoch. Die zweite Säule ist ② − 6 cm höher, das sind (② − 6) · 3 = ③ Kinder mehr.", "schablone": "① = □; ② = □; ③ = □", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ)."}, "o": {"werte": [18, 11, 15]}, "h": "Höhe mal Maßstab gibt die Anzahl.", "w": "6 · 3 = 18 Kinder. 33 : 3 = 11 cm. 11 − 6 = 5 cm Unterschied, 5 · 3 = 15 Kinder mehr (33 − 18 = 15).", "form": "lueckenweg", "zaehlt": "nein", "r": 603}, {"l": "kreisdiagramm", "t": "kreisdiagramm", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Ein Kreis hat 360°. 10 % davon sind 360° : 10 = ①°. 30 % sind dreimal so viel: ②°.", "schablone": "① = □; ② = □", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ)."}, "o": {"werte": [36, 108]}, "h": "30 % sind dreimal 10 %.", "w": "10 % sind 36°. 30 % sind 3 · 36° = 108°.", "form": "lueckenweg", "zaehlt": "nein", "r": 604}, {"l": "irrefuehrend", "t": "irrefuehrend", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Die Achse eines Säulendiagramms beginnt bei 40 statt bei 0. Säule A reicht bis 50, Säule B bis 100. Die gezeichnete Höhe von B ist (100 − 40) : (50 − 40) = ①-mal so groß wie die von A. Die dargestellten Werte sind aber 50 und 100: Der Wert von B ist 100 : 50 = ②-mal so groß wie der von A. Das Bild übertreibt also um den Faktor ① : ② = ③.", "schablone": "① = □; ② = □; ③ = □", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ)."}, "o": {"werte": [6, 2, 3]}, "h": "Zieh bei der gekürzten Achse erst 40 ab.", "w": "Gezeichnet sind 60 und 10, also 6-mal so hoch. Dargestellt sind die Werte 100 und 50: 2-mal. Das Bild übertreibt um 6 : 2 = 3.", "form": "lueckenweg", "zaehlt": "nein", "r": 605}, {"l": "absolute_haeufigkeit", "t": "absolute_haeufigkeit", "p": "uebung", "s": 2, "g": "einkleidung", "y": "auswahl", "f": {"text": "25 Kinder werden nach ihrem Lieblingstier gefragt. Jedes Kind nennt höchstens eines: 9 nennen den Hund, 7 die Katze, 4 den Fisch. Die übrigen nennen kein Tier. Wie findest du die Zahl der Kinder, die kein Tier nennen?"}, "a": ["9 + 7 + 4 = 20", "25 − (9 + 7 + 4) = 5", "25 − 9 = 16", "25 + 20 = 45"], "o": {"index": 1}, "h": "Alle Gruppen zusammen sind die Gesamtzahl.", "w": "Jedes Kind wird nur einmal gezählt. Mit Lieblingstier: 9 + 7 + 4 = 20. Ohne: 25 − 20 = 5.", "form": "verfahren_waehlen", "zaehlt": "ja", "r": 606}, {"l": "absolute_haeufigkeit", "t": "absolute_haeufigkeit", "p": "uebung", "s": 3, "g": "fehler", "y": "auswahl", "f": {"text": "Kim hat 20-mal gewürfelt. Seine Strichliste: Augenzahl 1 dreimal, 2 fünfmal, 3 viermal, 4 zweimal, 5 viermal, 6 dreimal. Zeile 1: Alle Häufigkeiten zusammen müssen 20 ergeben. Zeile 2: 3 + 5 + 4 + 2 + 4 + 3 = 20. Zeile 3: Die Strichliste passt also zu 20 Würfen. In welcher Zeile passiert der erste Fehler?"}, "a": ["In Zeile 1", "In Zeile 2", "In Zeile 3"], "o": {"index": 1}, "h": "Rechne die Summe der sechs Anzahlen selbst nach.", "w": "3 + 5 + 4 + 2 + 4 + 3 = 21. Die Liste hat einen Strich zu viel.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 607}, {"l": "relative_haeufigkeit", "t": "relative_haeufigkeit", "p": "uebung", "s": 3, "g": "fehler", "y": "auswahl", "f": {"text": "Bei 40 Würfen fällt 12-mal die Sechs. Kim berechnet die relative Häufigkeit. Zeile 1: Relative Häufigkeit = Anzahl : Gesamtzahl. Zeile 2: 12 : 40 = 0,03. Zeile 3: 0,03 sind 3 %. In welcher Zeile passiert der erste Fehler?"}, "a": ["In Zeile 1", "In Zeile 2", "In Zeile 3"], "o": {"index": 1}, "h": "12 : 40 ist dasselbe wie 30 : 100. Wie schreibt man das als Dezimalzahl?", "w": "12 : 40 = 0,3. 0,3 sind 30 %. Zeile 3 folgt richtig aus der falschen Zeile 2.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 608}, {"l": "tabelle_auswerten", "t": "tabelle_auswerten", "p": "uebung", "s": 3, "g": "fehler", "y": "auswahl", "f": {"text": "Eine Tabelle zeigt, wie 30 Kinder zur Schule kommen: Bus 12, Rad 8, zu Fuß 10. Zeile 1: Summe: 12 + 8 + 10 = 30. Zeile 2: Der Anteil Bus ist 12 von 30, also 12 : 30 = 0,4 = 40 %. Zeile 3: Der Anteil zu Fuß ist 10 von 12. In welcher Zeile steckt der Fehler?"}, "a": ["In Zeile 1", "In Zeile 2", "In Zeile 3"], "o": {"index": 2}, "h": "Durch welche Zahl teilt man, um einen Anteil zu bekommen?", "w": "Man teilt immer durch die Summe aller Anzahlen: 10 von 30 sind etwa 33 %.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 609}, {"l": "saeulendiagramm", "t": "saeulendiagramm", "p": "uebung", "s": 3, "g": "fehler", "y": "auswahl", "f": {"text": "Im Säulendiagramm steht 1 cm Höhe für 4 Kinder. Eine Säule ist 7 cm hoch. Kim liest sie ab. Zeile 1: Jeder Zentimeter steht für 4 Kinder. Zeile 2: Die Säule gehört also zu 7 : 4 Kindern, das sind weniger als 2 Kinder. Zeile 3: Eine Säule für 12 Kinder wäre 12 : 4 = 3 cm hoch. In welcher Zeile passiert der erste Fehler?"}, "a": ["In Zeile 1", "In Zeile 2", "In Zeile 3"], "o": {"index": 1}, "h": "Aus der Höhe in cm bekommst du die Anzahl mit mal oder mit geteilt?", "w": "Höhe mal Maßstab: 7 · 4 = 28 Kinder.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 610}]$auf$::jsonb),
    (16, 'funktionen.grundbegriffe', 742, 20, $auf$[{"l": "eindeutig", "t": "eindeutig", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Die Zuordnung x ↦ x² ordnet zwei verschiedenen Zahlen den Wert 25 zu. Die positive ist ①: ① · ① = 25. Die negative ist ②: ② · ② = 25. Zusammengezählt ergeben beide ① + ② = ③. Der Wert 25 gehört also zu zwei Eingaben. Das ist erlaubt: Es ist eine Funktion, weil jede Eingabe genau einen Wert hat.", "schablone": "① = □; ② = □; ③ = □", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ)."}, "o": {"werte": [5, -5, 0]}, "h": "Quadrieren heißt: mit sich selbst malnehmen.", "w": "5 · 5 = 25 und (−5) · (−5) = 25. Die Summe ist 0. Zwei Eingaben mit demselben Wert sind erlaubt; verboten wäre eine Eingabe mit zwei Werten.", "form": "lueckenweg", "zaehlt": "nein", "r": 763}, {"l": "mengen", "t": "mengen", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Die Funktion f(x) = 12 : (x − 5) ist nicht für jede Zahl erlaubt. Für x = 7 ist der Nenner 7 − 5 = ①. Also ist f(7) = 12 : ① = ②. Für x = 5 wäre der Nenner 0. Dann darf man nicht teilen.", "schablone": "① = □; ② = □", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ)."}, "o": {"werte": [2, 6]}, "h": "Rechne erst die Klammer aus.", "w": "7 − 5 = 2. 12 : 2 = 6.", "form": "lueckenweg", "zaehlt": "nein", "r": 764}, {"l": "wertetabelle", "t": "wertetabelle", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Zur Funktion f(x) = 2x + 3 gibt es eine Wertetabelle. Oben steht x, darunter f(x). Für x = 4 ist f(4) = ①. Für x = 10 ist f(10) = ②. Von x = 4 bis x = 10 wächst f(x) um ② − ① = ③.", "schablone": "① = □; ② = □; ③ = □", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ)."}, "o": {"werte": [11, 23, 12]}, "h": "Erst mal, dann plus.", "w": "f(4) = 2 · 4 + 3 = 11. f(10) = 2 · 10 + 3 = 23. 23 − 11 = 12.", "form": "lueckenweg", "zaehlt": "nein", "r": 765}, {"l": "graph_lesen", "t": "graph_lesen", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Der Graph von f ist eine Gerade. Du liest ab: Bei x = 2 liegt der Graph bei y = 4, bei x = 5 bei y = 13. Von x = 2 bis x = 5 sind es 5 − 2 = ① Schritte nach rechts. Der Graph steigt um 13 − 4 = ②. Pro Schritt steigt er um ② : ① = ③.", "schablone": "① = □; ② = □; ③ = □", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ)."}, "o": {"werte": [3, 9, 3]}, "h": "Steigung: Anstieg geteilt durch Schritte.", "w": "5 − 2 = 3. 13 − 4 = 9. 9 : 3 = 3.", "form": "lueckenweg", "zaehlt": "nein", "r": 766}, {"l": "nullstellen", "t": "nullstellen", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Die Nullstelle von f(x) = 2x + 10 ist die Stelle, an der f(x) = 0 gilt. Aus 2x + 10 = 0 folgt x = ①. Der Graph schneidet die x-Achse im Punkt (① | 0). Drei Schritte weiter rechts, bei x = ① + 3, ist f(① + 3) = ②.", "schablone": "① = □; ② = □", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ)."}, "o": {"werte": [-5, 6]}, "h": "Bring erst die Zahl ohne x auf die andere Seite. Achte auf das Vorzeichen.", "w": "2x = −10, also x = −5. Bei x = −2 ist f(−2) = 2 · (−2) + 10 = 6.", "form": "lueckenweg", "zaehlt": "nein", "r": 767}, {"l": "punkt_graph", "t": "punkt_graph", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Liegt P(4 | 12) auf dem Graphen von f(x) = 2x + 1? Setze x = 4 ein: f(4) = 2 · 4 + 1 = ①. Der y-Wert von P ist 12. Der Unterschied ist 12 − ① = ②. Weil ② nicht 0 ist, liegt P nicht auf dem Graphen.", "schablone": "① = □; ② = □", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ)."}, "o": {"werte": [9, 3]}, "h": "Setze die erste Zahl des Punktes in den Term ein.", "w": "f(4) = 9, nicht 12. Der Unterschied ist 3. P liegt nicht auf dem Graphen.", "form": "lueckenweg", "zaehlt": "nein", "r": 768}, {"l": "sachzusammenhang", "t": "sachzusammenhang", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Ein Handytarif kostet 5 € Grundgebühr und 2 € je Gigabyte (GB). Für 4 GB zahlt man 5 + 2 · 4 = ① €. Für 10 GB zahlt man 5 + 2 · 10 = ② €. Für 10 GB zahlt man also ② − ① = ③ € mehr als für 4 GB.", "schablone": "① = □; ② = □; ③ = □", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ)."}, "o": {"werte": [13, 25, 12]}, "h": "Erst malnehmen, dann die Grundgebühr dazu.", "w": "5 + 8 = 13 €. 5 + 20 = 25 €. 25 − 13 = 12 €: Nur die 6 zusätzlichen GB kosten extra (6 · 2 = 12), die Grundgebühr fällt nur einmal an.", "form": "lueckenweg", "zaehlt": "nein", "r": 769}, {"l": "mengen", "t": "mengen", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "auswahl", "f": {"text": "Welche Zahl darf man in g(x) = 10 : (2x − 6) nicht einsetzen?"}, "a": ["x = 6", "x = 3, denn dann ist der Nenner 2 · 3 − 6 = 0", "x = −3", "x = 5"], "o": {"index": 1}, "h": "Der Nenner darf nicht 0 sein. Wann ist 2x − 6 gleich 0?", "w": "2x − 6 = 0 ergibt 2x = 6 und x = 3. Nur dort ist der Nenner 0.", "form": "verfahren_waehlen", "zaehlt": "ja", "r": 770}, {"l": "funktionswert", "t": "funktionswert", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "auswahl", "f": {"text": "Für f(x) = 2x² + 1 soll f(−3) berechnet werden. Welche Rechnung ist richtig?"}, "a": ["2 · (−3)² + 1 = 2 · (−9) + 1 = −17", "(2 · (−3))² + 1 = (−6)² + 1 = 37", "2 · 3 + 1 = 7", "2 · (−3)² + 1 = 2 · 9 + 1 = 19"], "o": {"index": 3}, "h": "Quadrieren kommt vor dem Malnehmen mit 2.", "w": "(−3)² = 9. Dann 2 · 9 = 18 und 18 + 1 = 19.", "form": "verfahren_waehlen", "zaehlt": "ja", "r": 771}, {"l": "punkt_graph", "t": "punkt_graph", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "auswahl", "f": {"text": "Wie prüfst du, ob Q(−2 | 9) auf dem Graphen von f(x) = x² + 5 liegt?"}, "a": ["x = −2 einsetzen: (−2)² + 5 = 9. Das ist der y-Wert, also liegt Q auf dem Graphen", "y = 9 einsetzen: 9² + 5 = 86. Das ist nicht −2, also liegt Q nicht auf dem Graphen", "x = −2 einsetzen: −2² + 5 = 1. Das ist nicht 9, also liegt Q nicht auf dem Graphen", "Nur x² = 4 ansehen: 4 ist nicht 9, also liegt Q nicht auf dem Graphen"], "o": {"index": 0}, "h": "Setze x aus dem Punkt in den Term ein und vergleiche mit y.", "w": "(−2)² + 5 = 4 + 5 = 9. Der Punkt Q(−2 | 9) liegt auf dem Graphen.", "form": "verfahren_waehlen", "zaehlt": "ja", "r": 772}, {"l": "mengen", "t": "mengen", "p": "uebung", "s": 3, "g": "fehler", "y": "auswahl", "f": {"text": "Kim bestimmt die Definitionsmenge von f(x) = 6 : (x + 2). Zeile 1: Man darf nicht durch 0 teilen. Zeile 2: x + 2 = 0 gilt für x = 2. Zeile 3: Also ist D = ℝ ohne {2}. In welcher Zeile passiert der erste Fehler?"}, "a": ["In Zeile 1", "In Zeile 2", "In Zeile 3"], "o": {"index": 1}, "h": "Setze x = 2 in den Nenner ein: Kommt 0 heraus?", "w": "x + 2 = 0 gilt für x = −2. Richtig: D = ℝ ohne {−2}.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 773}, {"l": "funktionswert", "t": "funktionswert", "p": "uebung", "s": 3, "g": "fehler", "y": "auswahl", "f": {"text": "Kim berechnet f(−2) für f(x) = x² − 3x. Zeile 1: Einsetzen: (−2)² − 3 · (−2). Zeile 2: (−2)² = −4 und −3 · (−2) = 6. Zeile 3: Zusammen: −4 + 6 = 2. In welcher Zeile passiert der erste Fehler?"}, "a": ["In Zeile 1", "In Zeile 2", "In Zeile 3"], "o": {"index": 1}, "h": "Eine Zahl mal sich selbst: Kann das Ergebnis negativ sein, wenn die Zahl negativ ist?", "w": "(−2)² = (−2) · (−2) = 4. Dann 4 + 6 = 10.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 774}, {"l": "stelle", "t": "stelle", "p": "uebung", "s": 3, "g": "fehler", "y": "auswahl", "f": {"text": "Für f(x) = 3x − 4 wird die Zahl x gesucht, bei der f(x) = 11 gilt. Kim rechnet. Zeile 1: Gesucht ist x mit f(x) = 11. Zeile 2: Ich setze 11 für x ein: f(11) = 3 · 11 − 4 = 29. Zeile 3: Also ist x = 29. In welcher Zeile passiert der erste Fehler?"}, "a": ["In Zeile 1", "In Zeile 2", "In Zeile 3"], "o": {"index": 1}, "h": "11 ist das Ergebnis, nicht die Eingabe. Was löst du stattdessen?", "w": "Du löst 3x − 4 = 11: 3x = 15, also x = 5. Probe: 3 · 5 − 4 = 11.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 775}, {"l": "wertetabelle", "t": "wertetabelle", "p": "uebung", "s": 3, "g": "fehler", "y": "auswahl", "f": {"text": "Die Wertetabelle einer linearen Funktion zeigt x = 1, 2, 3, 4 und f(x) = 5, 7, 9, 11. Kim sucht den Term. Zeile 1: Von x = 1 bis x = 4 wächst f(x) von 5 auf 11, also um 6. Pro Schritt wächst f(x) um 6. Zeile 2: Also hat der Term die Form f(x) = 6x + c. Zeile 3: Für x = 1 muss 5 herauskommen: 6 · 1 + c = 5, also c = −1. Der Term ist f(x) = 6x − 1. In welcher Zeile passiert der erste Fehler?"}, "a": ["In Zeile 1", "In Zeile 2", "In Zeile 3"], "o": {"index": 0}, "h": "Von x = 1 bis x = 4: Wie viele Schritte nach rechts sind das?", "w": "Von x = 1 bis x = 4 sind es 3 Schritte. 6 : 3 = 2 je Schritt. Mit 2 · 1 + c = 5 ist c = 3, also f(x) = 2x + 3. Probe: f(2) = 7. Die Zeilen 2 und 3 folgen richtig aus der falschen Zeile 1.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 776}, {"l": "graph_lesen", "t": "graph_lesen", "p": "uebung", "s": 3, "g": "fehler", "y": "auswahl", "f": {"text": "Der Graph von f steigt gleichmäßig. Er geht durch die Punkte (1 | 3), (2 | 5) und (4 | 9). Kim liest f(3) ab. Zeile 1: Von (1 | 3) nach (4 | 9) steigt der Graph um 9 − 3 = 6. Das ist der Anstieg pro Schritt nach rechts. Zeile 2: Von (2 | 5) nach x = 3 ist es ein Schritt, also f(3) = 5 + 6 = 11. Zeile 3: Kim liest f(3) = 11 ab. In welcher Zeile passiert der erste Fehler?"}, "a": ["In Zeile 1", "In Zeile 2", "In Zeile 3"], "o": {"index": 0}, "h": "Von x = 1 bis x = 4: Wie viele Schritte nach rechts sind das?", "w": "Von x = 1 bis x = 4 sind es 3 Schritte, also 6 : 3 = 2 je Schritt. f(3) = 5 + 2 = 7. Probe: Von (3 | 7) nach (4 | 9) sind es wieder 2.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 777}, {"l": "nullstellen", "t": "nullstellen", "p": "uebung", "s": 3, "g": "fehler", "y": "auswahl", "f": {"text": "Kim berechnet die Nullstelle von f(x) = x − 6. Zeile 1: Ich rechne f(0) = 0 − 6 = −6. Zeile 2: Also ist die Nullstelle bei x = −6. Zeile 3: Der Graph schneidet die x-Achse bei (−6 | 0). In welcher Zeile passiert der erste Fehler?"}, "a": ["In Zeile 1", "In Zeile 2", "In Zeile 3"], "o": {"index": 1}, "h": "Die Nullstelle ist die Stelle x, bei der der Funktionswert 0 ist, nicht umgekehrt.", "w": "Du löst f(x) = 0: x − 6 = 0, also x = 6. f(0) = −6 ist die y-Koordinate: Der Schnittpunkt mit der y-Achse ist (0 | −6).", "form": "fehler_detektiv", "zaehlt": "ja", "r": 778}, {"l": "sachzusammenhang", "t": "sachzusammenhang", "p": "uebung", "s": 3, "g": "fehler", "y": "auswahl", "f": {"text": "Eine Kerze ist 30 cm lang und brennt in jeder Stunde 2 cm ab. Kim stellt den Term für die Länge L(t) nach t Stunden auf. Zeile 1: Feste Größe am Anfang: 30 cm. Zeile 2: Änderung pro Stunde: −2 cm. Zeile 3: Term: L(t) = 2 − 30 · t. In welcher Zeile steckt der Fehler?"}, "a": ["In Zeile 1", "In Zeile 2", "In Zeile 3"], "o": {"index": 2}, "h": "Die feste Größe steht allein, die Änderung steht beim t.", "w": "Die Länge am Anfang ist 30, pro Stunde kommt −2 dazu: L(t) = 30 − 2 · t.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 779}, {"l": "eindeutig", "t": "eindeutig", "p": "uebung", "s": 1, "g": "erkennen", "y": "auswahl", "f": {"text": "Eine Wertetabelle enthält diese Zuordnungen: x = 1 → y = 5, x = 2 → y = 7, x = 3 → y = 9, x = 2 → y = 8. Was zeigt die Tabelle?"}, "a": ["Die Zuordnung ist nicht eindeutig, denn zu x = 2 gehören zwei verschiedene y-Werte.", "Die Zuordnung ist eindeutig, denn jedem y-Wert gehört nur ein x-Wert.", "Die Zuordnung ist eindeutig, denn jedes x kommt vor.", "Die Zuordnung ist nicht eindeutig, denn y wird immer größer."], "o": {"index": 0}, "h": "Schau, ob ein x-Wert mehrmals mit verschiedenen y-Werten vorkommt.", "w": "Bei einer eindeutigen Zuordnung gehört zu jedem x genau ein y. Hier kommt x = 2 zweimal vor, einmal mit y = 7 und einmal mit y = 8. Deshalb ist die Zuordnung nicht eindeutig und keine Funktion.", "form": "bruecke", "zaehlt": "ja", "r": 780}, {"l": "funktionswert", "t": "funktionswert", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Gegeben ist f(x) = 2x + 5. Gesucht ist f(6). Weg A: 6 für x einsetzen und rechnen. Weg B: bei f(0) beginnen und für jeden Schritt in x den Wert um die Steigung erhöhen. Wie groß ist f(6)?"}, "o": {"wert": 17}, "h": "Beide Wege müssen denselben Wert geben.", "w": "Weg A: 2 · 6 + 5 = 12 + 5 = 17. Weg B: f(0) = 5, bei jedem Schritt kommt 2 dazu, nach 6 Schritten sind es 5 + 6 · 2 = 17. Also ist f(6) = 17.", "form": "zwei_wege", "zaehlt": "ja", "r": 781}, {"l": "stelle", "t": "stelle", "p": "uebung", "s": 3, "g": "rueckwaerts", "y": "zahl", "f": {"text": "Bei der Funktion f(x) = 3x − 8 ist der Funktionswert 19. An welcher Stelle x gehört er zu f?"}, "o": {"wert": 9}, "h": "Mache beide Rechenschritte von f rückgängig, in umgekehrter Reihenfolge.", "w": "f macht aus x erst 3x, dann 3x − 8. Rückwärts: 19 + 8 = 27, dann 27 : 3 = 9. Probe: 3 · 9 − 8 = 19.", "form": "umkehren", "zaehlt": "ja", "r": 782}]$auf$::jsonb),
    (17, 'funktionen.linear', 777, 22, $auf$[{"l": "graph_ablesen", "t": "graph_ablesen", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Die Gerade y = 3x − 5 geht durch die Punkte (2 | ①) und (4 | ②). Zwischen den beiden Punkten steigt sie um ② − ① = ③.", "schablone": "① = □; ② = □; ③ = □", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ)."}, "o": {"werte": [1, 7, 6]}, "h": "Setze erst x ein, rechne dann mal, dann minus.", "w": "y(2) = 6 − 5 = 1. y(4) = 12 − 5 = 7. 7 − 1 = 6, also 2 Schritte mal Steigung 3.", "form": "lueckenweg", "zaehlt": "nein", "r": 802}, {"l": "proportional", "t": "proportional", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Bei einer proportionalen Zuordnung y = k · x gehört zu x = 4 der Wert y = 20. Dann ist k = 20 : 4 = ①. Zu x = 7 gehört dann y = ① · 7 = ②.", "schablone": "① = □; ② = □", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ)."}, "o": {"werte": [5, 35]}, "h": "k ist der Wert für x = 1.", "w": "k = 5. y = 5 · 7 = 35.", "form": "lueckenweg", "zaehlt": "nein", "r": 803}, {"l": "aufstellen", "t": "aufstellen", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Eine Gerade hat die Steigung 2 und geht durch P(3 | 11). Ansatz: y = 2x + t. Einsetzen: 11 = 2 · 3 + t, also t = 11 − ① = ②.", "schablone": "① = □; ② = □", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ)."}, "o": {"werte": [6, 5]}, "h": "Setze die Koordinaten von P in y = 2x + t ein.", "w": "2 · 3 = 6. t = 11 − 6 = 5. Die Gerade ist y = 2x + 5.", "form": "lueckenweg", "zaehlt": "nein", "r": 804}, {"l": "lage", "t": "lage", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Die Gerade g hat die Gleichung y = −x + 3. Ihre Steigung ist ①. Eine Gerade h senkrecht zu g hat als Steigung den negativen Kehrwert der Steigung von g, also ②. Die Summe beider Steigungen ist ① + ② = ③.", "schablone": "① = □; ② = □; ③ = □", "hinweis": "Je Lücke eine ganze Zahl, wenn nötig mit Minus."}, "o": {"werte": [-1, 1, 0]}, "h": "Die Steigung ist die Zahl vor dem x. Wie lautet sie bei −x?", "w": "g hat die Steigung −1. Der Kehrwert von −1 ist −1, der negative Kehrwert ist 1. Die Summe ist −1 + 1 = 0.", "form": "lueckenweg", "zaehlt": "nein", "r": 805}, {"l": "einsetzen", "t": "einsetzen", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Die Geradenschar y = k · x + 2 enthält für k = 5 die Gerade y = 5x + 2. Für k = 5 und x = 3 ist y = ①. Für k = −4 und x = 3 ist y = ②. Der Unterschied der beiden y-Werte ist ① − ② = ③.", "schablone": "① = □; ② = □; ③ = □", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ)."}, "o": {"werte": [17, -10, 27]}, "h": "Ersetze nur k, alles andere bleibt.", "w": "5 · 3 + 2 = 17. −4 · 3 + 2 = −10. 17 − (−10) = 27.", "form": "lueckenweg", "zaehlt": "nein", "r": 806}, {"l": "wirkung", "t": "wirkung", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "In y = a · x + b verschiebt b die Gerade nach oben oder unten. Wird b von 2 auf 8 erhöht, wandert die Gerade um 8 − 2 = ① nach oben. Wird a von 1 auf 5 erhöht, liegt die Gerade bei x = 3 um (5 − 1) · 3 = ② höher. Ändert man beides, liegt die Gerade bei x = 3 um ① + ② = ③ höher.", "schablone": "① = □; ② = □; ③ = □", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ)."}, "o": {"werte": [6, 12, 18]}, "h": "a wirkt bei jedem x. b wirkt immer gleich.", "w": "b: 8 − 2 = 6. a: (5 − 1) · 3 = 12. Zusammen 6 + 12 = 18.", "form": "lueckenweg", "zaehlt": "nein", "r": 807}, {"l": "bueschel", "t": "bueschel", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Alle Geraden y = k · (x − 3) + 7 gehen durch einen Punkt Z. Für x = 3 ist die Klammer 0, also ist y = 7 für jedes k. Für k = 4 und x = 5 ist die Klammer 5 − 3 = ①. Dann ist k · ① = ②. Also ist y = ② + 7 = ③.", "schablone": "① = □; ② = □; ③ = □", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ)."}, "o": {"werte": [2, 8, 15]}, "h": "Rechne erst die Klammer aus, dann malnehmen, dann plus 7.", "w": "5 − 3 = 2. 4 · 2 = 8. 8 + 7 = 15.", "form": "lueckenweg", "zaehlt": "nein", "r": 808}, {"l": "deuten", "t": "deuten", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Ein Behälter enthält am Anfang 45 l Wasser. Jede Minute fließen 3 l ab. Nach 5 Minuten sind es noch 45 − 3 · 5 = ① l. In dieser Zeit sind 45 − ① = ② l abgeflossen. Leer ist der Behälter, wenn 3 · t = 45 gilt, also nach ③ Minuten. Es dauert dann noch ③ − 5 = ④ Minuten.", "schablone": "① = □; ② = □; ③ = □; ④ = □", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ)."}, "o": {"werte": [30, 15, 15, 10]}, "h": "Die Rate ist negativ: Es wird weniger.", "w": "45 − 15 = 30 l sind noch drin. 15 l sind abgeflossen. 3 · t = 45 ergibt t = 15 Minuten, das sind 15 − 5 = 10 Minuten mehr.", "form": "lueckenweg", "zaehlt": "nein", "r": 809}, {"l": "zwei_punkte", "t": "zwei_punkte", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "auswahl", "f": {"text": "Eine Gerade geht durch A(2 | 1) und B(5 | 13). Welche Rechnung gibt die Steigung?"}, "a": ["(13 − 1) : (5 − 2) = 4", "(5 − 2) : (13 − 1) = 1/4", "(13 + 1) : (5 + 2) = 2", "13 − 1 = 12"], "o": {"index": 0}, "h": "Steigung = nach oben geteilt durch nach rechts.", "w": "Nach oben: 13 − 1 = 12. Nach rechts: 5 − 2 = 3. Steigung 12 : 3 = 4.", "form": "verfahren_waehlen", "zaehlt": "ja", "r": 810}, {"l": "proportional", "t": "proportional", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "auswahl", "f": {"text": "Welche Wertetabelle gehört zu einer proportionalen Zuordnung?"}, "a": ["x: 1, 2, 5 und y: 3, 5, 8", "x: 1, 2, 4 und y: 8, 4, 2", "x: 1, 2, 3 und y: 4, 6, 8", "x: 1, 2, 5 und y: 3, 6, 15"], "o": {"index": 3}, "h": "Bei Proportionalität ist y : x überall gleich.", "w": "3 : 1 = 6 : 2 = 15 : 5 = 3. In den anderen Tabellen ändert sich y : x.", "form": "verfahren_waehlen", "zaehlt": "ja", "r": 811}, {"l": "bueschel", "t": "bueschel", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "auswahl", "f": {"text": "Alle Geraden y = k · x + 3 gehen durch denselben Punkt. Welcher ist es?"}, "a": ["(3 | 0)", "(0 | 3), denn für x = 0 fällt k weg", "(1 | 3)", "(0 | 0)"], "o": {"index": 1}, "h": "Wo hat k keinen Einfluss auf y?", "w": "Bei x = 0 ist k · 0 = 0, also y = 3 für jedes k. Der Punkt ist (0 | 3).", "form": "verfahren_waehlen", "zaehlt": "ja", "r": 812}, {"l": "ablesen", "t": "ablesen", "p": "uebung", "s": 3, "g": "fehler", "y": "auswahl", "f": {"text": "Kim liest bei y = 4 − 3x Steigung und Achsenabschnitt ab. Zeile 1: Die Steigung m ist die erste Zahl: m = 4. Zeile 2: Der Achsenabschnitt t ist die Zahl ohne x: t = 4. Zeile 3: Die Gerade geht also durch den Punkt (0 | 4). In welcher Zeile passiert der erste Fehler?"}, "a": ["In Zeile 1", "In Zeile 2", "In Zeile 3"], "o": {"index": 0}, "h": "m steht vor dem x, nicht am Anfang der Gleichung.", "w": "m = −3, denn −3 steht vor dem x. Zeile 2 und 3 stimmen: t = 4 und die Gerade geht durch (0 | 4).", "form": "fehler_detektiv", "zaehlt": "ja", "r": 813}, {"l": "proportional", "t": "proportional", "p": "uebung", "s": 3, "g": "fehler", "y": "auswahl", "f": {"text": "Eine Tabelle zeigt x = 2, 4, 6 und y = 6, 12, 20. Kim prüft, ob die Zuordnung proportional ist. Zeile 1: Für x = 2: y : x = 6 : 2 = 3. Zeile 2: Für x = 4: y : x = 12 : 4 = 3. Zeile 3: Für x = 6: y : x = 20 : 6 ist ungefähr 3. Also ist die Zuordnung proportional. In welcher Zeile steckt der Fehler?"}, "a": ["In Zeile 1", "In Zeile 2", "In Zeile 3"], "o": {"index": 2}, "h": "Für proportional muss in jeder Spalte genau dieselbe Zahl herauskommen.", "w": "20 : 6 ist nicht 3, sondern ungefähr 3,33. Die Zuordnung ist nicht proportional.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 814}, {"l": "aufstellen", "t": "aufstellen", "p": "uebung", "s": 3, "g": "fehler", "y": "auswahl", "f": {"text": "Eine Gerade geht durch A(1 | 4) und B(3 | 10). Kim stellt die Gleichung auf. Zeile 1: Steigung: m = (10 − 4) : (3 − 1) = 3. Zeile 2: A einsetzen in y = 3x + t: 4 = 3 · 1 + t, also t = 4 + 3 = 7. Zeile 3: Die Gerade ist y = 3x + 7. In welcher Zeile passiert der erste Fehler?"}, "a": ["In Zeile 1", "In Zeile 2", "In Zeile 3"], "o": {"index": 1}, "h": "Aus 4 = 3 + t folgt t, wenn du auf beiden Seiten 3 abziehst.", "w": "t = 4 − 3 = 1. Die Gerade ist y = 3x + 1. Probe mit B: 3 · 3 + 1 = 10.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 815}, {"l": "schnittpunkte", "t": "schnittpunkte", "p": "uebung", "s": 3, "g": "fehler", "y": "auswahl", "f": {"text": "Die Geraden y = 2x + 1 und y = −x + 7 schneiden sich. Kim bestimmt den Schnittpunkt. Zeile 1: Gleichsetzen: 2x + 1 = −x + 7. Zeile 2: x auf die linke Seite bringen: x + 1 = 7, also x = 6. Zeile 3: Dann ist y = 2 · 6 + 1 = 13. In welcher Zeile passiert der erste Fehler?"}, "a": ["In Zeile 1", "In Zeile 2", "In Zeile 3"], "o": {"index": 1}, "h": "Wenn du −x auf die linke Seite bringst, wird daraus +x. Wie viele x stehen dann links?", "w": "2x + x = 3x. Also 3x + 1 = 7, x = 2 und y = 5. Der Schnittpunkt ist (2 | 5).", "form": "fehler_detektiv", "zaehlt": "ja", "r": 816}, {"l": "lage", "t": "lage", "p": "uebung", "s": 3, "g": "fehler", "y": "auswahl", "f": {"text": "Die Geraden y = 2x + 5 und y = −2x + 5 sollen untersucht werden. Kim prüft ihre Lage. Zeile 1: Die Steigungen sind 2 und −2. Zeile 2: Das Produkt der Steigungen ist 2 · (−2) = −4. Zeile 3: Das Produkt ist −4, also stehen die Geraden senkrecht aufeinander. In welcher Zeile steckt der Fehler?"}, "a": ["In Zeile 1", "In Zeile 2", "In Zeile 3"], "o": {"index": 2}, "h": "Senkrecht heißt: Das Produkt der Steigungen ist genau minus eins.", "w": "Das Produkt −4 ist nicht −1, und die Steigungen sind verschieden. Die Geraden sind weder parallel noch senkrecht.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 817}, {"l": "einsetzen", "t": "einsetzen", "p": "uebung", "s": 3, "g": "fehler", "y": "auswahl", "f": {"text": "Die Schar y = (k − 2) · x + 3 hat für k = 5 eine bestimmte Gerade. Kim setzt k = 5 ein. Zeile 1: Die Klammer wird zu 5 + 2 = 7. Zeile 2: Die Gerade ist also y = 7x + 3. Zeile 3: Für x = 2 ist y = 7 · 2 + 3 = 17. In welcher Zeile passiert der erste Fehler?"}, "a": ["In Zeile 1", "In Zeile 2", "In Zeile 3"], "o": {"index": 0}, "h": "In der Klammer steht k − 2. Was ist 5 − 2?", "w": "5 − 2 = 3. Die Gerade ist y = 3x + 3. Für x = 2 ist y = 9.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 818}, {"l": "wirkung", "t": "wirkung", "p": "uebung", "s": 3, "g": "fehler", "y": "auswahl", "f": {"text": "Kim untersucht die Geraden y = a · x + 3 für verschiedene a. Zeile 1: a steht vor x, es ändert also die Steigung. Zeile 2: Bei jedem a geht die Gerade durch den Punkt (0 | 3). Zeile 3: Wird a größer, verschiebt sich die Gerade nach oben, ohne dass sich die Steigung ändert. In welcher Zeile steckt der Fehler?"}, "a": ["In Zeile 1", "In Zeile 2", "In Zeile 3"], "o": {"index": 2}, "h": "Der Parameter a steht vor x. Was bewirkt das?", "w": "Wird a größer, nimmt die Steigung zu: Die Gerade dreht sich um den Punkt (0 | 3). Sie verschiebt sich nicht nach oben. (Wie steil sie ist, hängt von |a| ab.)", "form": "fehler_detektiv", "zaehlt": "ja", "r": 819}, {"l": "bueschel", "t": "bueschel", "p": "uebung", "s": 3, "g": "fehler", "y": "auswahl", "f": {"text": "Alle Geraden y = k · (x + 2) + 4 gehen durch einen Punkt Z. Kim bestimmt Z. Zeile 1: Z liegt dort, wo k keinen Einfluss hat. Zeile 2: Das ist bei x + 2 = 0, also bei x = 2. Zeile 3: Dort ist y = 4. Also ist Z(2 | 4). In welcher Zeile passiert der erste Fehler?"}, "a": ["In Zeile 1", "In Zeile 2", "In Zeile 3"], "o": {"index": 1}, "h": "Welche Zahl macht x + 2 gleich 0?", "w": "x + 2 = 0 gilt für x = −2. Der Punkt ist Z(−2 | 4).", "form": "fehler_detektiv", "zaehlt": "ja", "r": 820}, {"l": "deuten", "t": "deuten", "p": "uebung", "s": 3, "g": "fehler", "y": "auswahl", "f": {"text": "Ein Taxi kostet 3 € Grundpreis und 2 € je Kilometer: K(x) = 2x + 3. Kim deutet die Zahlen. Zeile 1: Der Grundpreis ist die Zahl vor dem x: 2 €. Zeile 2: Der Preis je Kilometer ist das Glied ohne x: 3 €. Zeile 3: Bei 0 km kostet die Fahrt also 2 €. In welcher Zeile passiert der erste Fehler?"}, "a": ["In Zeile 1", "In Zeile 2", "In Zeile 3"], "o": {"index": 0}, "h": "Setze x = 0 in den Term ein.", "w": "K(0) = 2 · 0 + 3 = 3. Der Grundpreis ist das Glied ohne x (3 €), die Zahl vor dem x ist der Preis je Kilometer (2 €).", "form": "fehler_detektiv", "zaehlt": "ja", "r": 821}, {"l": "wirkung", "t": "wirkung", "p": "uebung", "s": 2, "g": "darstellung", "y": "auswahl", "f": {"text": "Die Gerade y = 2x + 1 wird ersetzt durch y = 2x + 4. Wie hat sich der Graph verändert?"}, "a": ["Er ist um 3 nach oben verschoben und verläuft parallel zum alten.", "Er ist steiler geworden.", "Er ist um 3 nach rechts verschoben.", "Seine Steigung ist von 2 auf 4 gewachsen."], "o": {"index": 0}, "h": "Vergleiche, welche Zahl sich ändert: die vor dem x oder die am Ende.", "w": "Die Zahl vor dem x ist gleich geblieben, die Steigung bleibt 2. Die Zahl am Ende wächst von 1 auf 4, der Graph schneidet die y-Achse 3 Einheiten höher. Er ist also um 3 nach oben verschoben, parallel zum alten.", "form": "bruecke", "zaehlt": "ja", "r": 822}, {"l": "zwei_punkte", "t": "zwei_punkte", "p": "uebung", "s": 2, "g": "umkehr", "y": "zahl", "f": {"text": "Eine Gerade y = m · x + 1 geht durch den Punkt (4|13). Wie groß ist die Steigung m?"}, "o": {"wert": 3}, "h": "Setze die Koordinaten des Punktes in die Gleichung ein und löse nach m auf.", "w": "Einsetzen: 13 = m · 4 + 1. Dann 13 − 1 = 12 = 4m, also m = 12 : 4 = 3. Probe: 3 · 4 + 1 = 13.", "form": "umkehren", "zaehlt": "ja", "r": 823}]$auf$::jsonb),
    (22, 'gleichungen.lgs2', 737, 19, $auf$[{"l": "pruefen", "t": "pruefen", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Prüfe, ob (6 | 1) das System I: x + y = 9 und II: x − y = 1 löst. Einsetzen in I: 6 + 1 = ①. Es fehlen 9 − ① = ② bis zur rechten Seite. Einsetzen in II: 6 − 1 = ③. Das ist nicht 1. Es sind ③ − 1 = ④ zu viel. Also ist (6 | 1) keine Lösung.", "schablone": "① = □; ② = □; ③ = □; ④ = □", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ)."}, "o": {"werte": [7, 2, 5, 4]}, "h": "Setze x = 6 und y = 1 in die linke Seite ein.", "w": "In I: 6 + 1 = 7, es fehlen 2 bis 9. In II: 6 − 1 = 5, das sind 5 − 1 = 4 zu viel.", "form": "lueckenweg", "zaehlt": "nein", "r": 759}, {"l": "grafisch", "t": "grafisch", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Die Geraden y = x + 1 und y = −x + 5 sollen sich schneiden. Für x = 2 ist x + 1 = ① und −x + 5 = ②. Der Unterschied der beiden Werte ist ① − ② = ③. Verschwindet der Unterschied, schneiden sich die Geraden bei x = 2. Dann ist der Schnittpunkt S(2 | ①).", "schablone": "① = □; ② = □; ③ = □", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ)."}, "o": {"werte": [3, 3, 0]}, "h": "Setze für x die Zahl 2 ein.", "w": "2 + 1 = 3 und −2 + 5 = 3. Der Unterschied verschwindet, beide Geraden gehen durch (2 | 3).", "form": "lueckenweg", "zaehlt": "nein", "r": 760}, {"l": "gleichsetzen", "t": "gleichsetzen", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Bei I: y = 2x + 1 und II: y = 6x − 11 steht zweimal y = …. Gleichsetzen: 2x + 1 = 6x − 11. Auf beiden Seiten 2x abziehen: 1 = 4x − 11. 11 addieren: ① = 4x. Also ist x = ②. Dann ist y = 2 · ② + 1 = ③.", "schablone": "① = □; ② = □; ③ = □", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ)."}, "o": {"werte": [12, 3, 7]}, "h": "Die Zahl 11 steht mit Minus auf der rechten Seite.", "w": "1 + 11 = 12, also 4x = 12 und x = 3. y = 2 · 3 + 1 = 7. Probe in II: 6 · 3 − 11 = 7.", "form": "lueckenweg", "zaehlt": "nein", "r": 761}, {"l": "addition", "t": "addition", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "I: x + y = 12 und II: 3x − y = 8. Addiert man I und II, fällt y weg: 4x = ①. Also ist x = ②. Einsetzen in I: ② + y = 12, also y = ③.", "schablone": "① = □; ② = □; ③ = □", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ)."}, "o": {"werte": [20, 5, 7]}, "h": "Beim Addieren fällt y weg. Rechne links und rechts.", "w": "4x = 20, x = 5. y = 12 − 5 = 7. Probe in II: 15 − 7 = 8.", "form": "lueckenweg", "zaehlt": "nein", "r": 762}, {"l": "verfahren", "t": "verfahren", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Bei I: y = 4x + 1 und II: y = 2x + 11 steht zweimal y = …. Das Gleichsetzen ist hier geschickt: 4x + 1 = 2x + 11. Dann ist 2x = ①. Also ist x = ②. Dann ist y = 4 · ② + 1 = ③.", "schablone": "① = □; ② = □; ③ = □", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ)."}, "o": {"werte": [10, 5, 21]}, "h": "Auf beiden Seiten 2x abziehen, dann 1 abziehen.", "w": "2x = 11 − 1 = 10, also x = 5. y = 4 · 5 + 1 = 21. Probe in II: 2 · 5 + 11 = 21.", "form": "lueckenweg", "zaehlt": "nein", "r": 763}, {"l": "loesbarkeit", "t": "loesbarkeit", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "I: y = 2x + 1 und II: y = 2x + 5. Beide Geraden haben dieselbe Steigung. Bei jedem x liegt II um 5 − 1 = ① höher als I, gemessen in y-Richtung. Dieser Unterschied bleibt bei jedem x gleich. Zwei Geraden haben nur dort einen gemeinsamen Punkt, wo der Unterschied ① verschwindet. Das System hat daher ② Lösungen.", "schablone": "① = □; ② = □", "hinweis": "Je Lücke eine ganze Zahl."}, "o": {"werte": [4, 0]}, "h": "Ein Schnittpunkt braucht eine Stelle, an der beide y-Werte übereinstimmen. Bleibt der Unterschied überall gleich?", "w": "Gleiche Steigung, andere Achsenabschnitte: Der Unterschied in y-Richtung ist überall 4 und wird nie null. Die Geraden sind parallel, sie schneiden sich nie, es gibt 0 Lösungen.", "form": "lueckenweg", "zaehlt": "nein", "r": 764}, {"l": "loesung_parameter", "t": "loesung_parameter", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "I: x + y = 6 und II: x − y = k. Addiert man I und II, so ist 2x = 6 + k. Für x = 5 muss also 2 · 5 = ① gelten, nämlich 6 + k = ①. Daraus folgt k = ②.", "schablone": "① = □; ② = □", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ)."}, "o": {"werte": [10, 4]}, "h": "Setze x = 5 in 2x = 6 + k ein.", "w": "2 · 5 = 10 = 6 + k, also k = 4.", "form": "lueckenweg", "zaehlt": "nein", "r": 765}, {"l": "sachaufgabe", "t": "sachaufgabe", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Zwei Zahlen haben die Summe 20 und die Differenz 6. Addiert man x + y = 20 und x − y = 6, so ist 2x = ①. Die größere Zahl ist x = ① : 2 = ②. Die kleinere Zahl ist y = 20 − ② = ③.", "schablone": "① = □; ② = □; ③ = □", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ)."}, "o": {"werte": [26, 13, 7]}, "h": "Das y fällt beim Addieren weg.", "w": "2x = 26, x = 13, y = 20 − 13 = 7. Probe: 13 − 7 = 6.", "form": "lueckenweg", "zaehlt": "nein", "r": 766}, {"l": "einsetzen", "t": "einsetzen", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "auswahl", "f": {"text": "Im System I: y = 2x − 1 und II: 4x − y = 7 soll y aus I in II eingesetzt werden. Welche Rechnung ist richtig?"}, "a": ["4x − 2x − 1 = 7, also 2x = 8 und x = 4", "4x − (2x − 1) = 7, also 2x + 1 = 7 und x = 3", "4x − (2x − 1) = 7, also 2x − 1 = 7 und x = 4", "4x − (2x − 1) = 7, also 2x + 1 = 7 und x = 8"], "o": {"index": 1}, "h": "Setze für y den ganzen Term in Klammern ein.", "w": "4x − (2x − 1) = 4x − 2x + 1 = 2x + 1. 2x + 1 = 7 ergibt x = 3. Dann y = 2 · 3 − 1 = 5.", "form": "verfahren_waehlen", "zaehlt": "ja", "r": 767}, {"l": "loesung_parameter", "t": "loesung_parameter", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "auswahl", "f": {"text": "System: I: y = k · x und II: y = 3x + 4. Für welches k hat das System keine Lösung?"}, "a": ["k = 4", "k = 0", "k = −3", "k = 3: gleiche Steigung, aber verschiedene Achsenabschnitte"], "o": {"index": 3}, "h": "Gleichsetzen: (k − 3) · x = 4. Wann kann man nicht nach x auflösen?", "w": "Für k = 3 ist 0 · x = 4. Das geht nie. Für jedes andere k gilt x = 4 : (k − 3).", "form": "verfahren_waehlen", "zaehlt": "ja", "r": 768}, {"l": "pruefen", "t": "pruefen", "p": "uebung", "s": 3, "g": "fehler", "y": "auswahl", "f": {"text": "Prüfe das Paar (5 | 1) im System I: 2x + y = 11 und II: x − y = 1. Kim prüft. Zeile 1: In I setze ich x = 1 und y = 5 ein: 2 · 1 + 5 = 7. Das ist nicht 11. Zeile 2: Eine Gleichung stimmt nicht, also ist (5 | 1) keine Lösung des Systems. Zeile 3: In II: 1 − 5 = −4. Das ist nicht 1. In welcher Zeile passiert der erste Fehler?"}, "a": ["In Zeile 1", "In Zeile 2", "In Zeile 3"], "o": {"index": 0}, "h": "Welche Zahl des Paares gehört zu x, welche zu y?", "w": "Im Paar (5 | 1) ist x = 5 und y = 1. In I: 2 · 5 + 1 = 11 stimmt. In II: 5 − 1 = 4 stimmt nicht. Also ist (5 | 1) keine Lösung des Systems.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 769}, {"l": "gleichsetzen", "t": "gleichsetzen", "p": "uebung", "s": 3, "g": "fehler", "y": "auswahl", "f": {"text": "Das System I: y = 3x − 2 und II: y = x + 6 wird durch Gleichsetzen gelöst. Kim rechnet. Zeile 1: Gleichsetzen: 3x − 2 = x − 6. Zeile 2: x abziehen: 2x − 2 = −6. Zeile 3: 2 addieren: 2x = −4, also x = −2. In welcher Zeile passiert der erste Fehler?"}, "a": ["In Zeile 1", "In Zeile 2", "In Zeile 3"], "o": {"index": 0}, "h": "Schreibe die rechte Seite von II noch einmal ab. Was steht dort?", "w": "Gleichsetzen: 3x − 2 = x + 6, nicht x − 6. Dann 2x − 2 = 6, 2x = 8, x = 4 und y = 10. Die Zeilen 2 und 3 folgen richtig aus der falschen Zeile 1.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 770}, {"l": "addition", "t": "addition", "p": "uebung", "s": 3, "g": "fehler", "y": "auswahl", "f": {"text": "System: I: 3x + 2y = 17 und II: 5x − 2y = 7. Kim löst es mit dem Additionsverfahren. Zeile 1: Die y-Terme +2y und −2y sind Gegenzahlen. Zeile 2: Addieren: 8x = 24, also x = 3. Zeile 3: x in I einsetzen: 3 · 3 + 2y = 17, also 2y = 17 + 9 = 26 und y = 13. In welcher Zeile steckt der Fehler?"}, "a": ["In Zeile 1", "In Zeile 2", "In Zeile 3"], "o": {"index": 2}, "h": "Aus 9 + 2y = 17 folgt 2y, wenn du auf beiden Seiten 9 abziehst.", "w": "2y = 17 − 9 = 8, also y = 4. Probe in II: 5 · 3 − 2 · 4 = 7.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 771}, {"l": "verfahren", "t": "verfahren", "p": "uebung", "s": 3, "g": "fehler", "y": "auswahl", "f": {"text": "System: I: x + y = 10 und II: x − y = 4. Kim wählt das Additionsverfahren. Zeile 1: In I und II stehen +y und −y. Das sind Gegenzahlen. Zeile 2: Man addiert nur die linken Seiten: x + y + x − y = 2x. Die rechte Seite bleibt 10. Zeile 3: Also ist 2x = 10 und x = 5. In welcher Zeile passiert der erste Fehler?"}, "a": ["In Zeile 1", "In Zeile 2", "In Zeile 3"], "o": {"index": 1}, "h": "Beim Addieren der Gleichungen wird jede Seite mit der anderen Seite addiert. Was steht dann rechts?", "w": "Rechts wird auch addiert: 10 + 4 = 14. Also 2x = 14, x = 7 und y = 3. Zeile 3 folgt richtig aus der falschen Zeile 2.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 772}, {"l": "loesbarkeit", "t": "loesbarkeit", "p": "uebung", "s": 3, "g": "fehler", "y": "auswahl", "f": {"text": "System: I: y = 3x − 2 und II: 2y = 6x − 4. Kim untersucht, wie viele Lösungen es gibt. Zeile 1: Teile II durch 2: y = 3x − 2. Zeile 2: Beide Gleichungen sind gleich. Zeile 3: Also hat das System keine Lösung. In welcher Zeile steckt der Fehler?"}, "a": ["In Zeile 1", "In Zeile 2", "In Zeile 3"], "o": {"index": 2}, "h": "Wenn beide Gleichungen dieselbe Gerade beschreiben, wie viele Punkte haben sie gemeinsam?", "w": "Beide Gleichungen beschreiben dieselbe Gerade. Jeder ihrer Punkte ist eine Lösung: unendlich viele.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 773}, {"l": "loesung_parameter", "t": "loesung_parameter", "p": "uebung", "s": 3, "g": "fehler", "y": "auswahl", "f": {"text": "System: I: y = a · x und II: y = 2x + 6. Kim untersucht, für welches a es keine Lösung gibt. Zeile 1: Gleichsetzen: a · x = 2x + 6. Zeile 2: Umstellen: (a − 2) · x = 6. Zeile 3: Für a = 2 ist 0 · x = 6. Das System hat dann unendlich viele Lösungen. In welcher Zeile steckt der Fehler?"}, "a": ["In Zeile 1", "In Zeile 2", "In Zeile 3"], "o": {"index": 2}, "h": "Gibt es ein x, für das 0 · x = 6 gilt?", "w": "0 · x ist immer 0, nie 6. Für a = 2 gibt es keine Lösung.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 774}, {"l": "sachaufgabe", "t": "sachaufgabe", "p": "uebung", "s": 3, "g": "fehler", "y": "auswahl", "f": {"text": "Ein Kino verkauft 100 Karten. Erwachsene zahlen 8 €, Kinder 5 €. Die Einnahmen sind 620 €. Kim stellt die Gleichungen auf. x ist die Zahl der Erwachsenen, y die der Kinder. Zeile 1: Karten: x + y = 100. Zeile 2: Einnahmen: 8y + 5x = 620. Zeile 3: Aus der ersten Gleichung folgt y = 100 − x. In welcher Zeile passiert der erste Fehler?"}, "a": ["In Zeile 1", "In Zeile 2", "In Zeile 3"], "o": {"index": 1}, "h": "Wer zahlt 8 €? Zu welcher Unbekannten gehört die 8?", "w": "Erwachsene (x) zahlen 8 €, Kinder (y) zahlen 5 €: 8x + 5y = 620.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 775}, {"l": "einsetzen", "t": "einsetzen", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Für x und y gilt: y = 2x und x + y = 12. Weg A: 2x für y einsetzen und x + 2x = 12 lösen. Weg B: y ist doppelt so groß wie x, also teilen sich 12 in drei gleiche Teile. Wie groß ist x?"}, "o": {"wert": 4}, "h": "Beide Wege zerlegen die 12 in x und das Doppelte von x.", "w": "Weg A: x + 2x = 3x = 12, also x = 4. Weg B: x ist ein Teil, y sind zwei Teile, zusammen 3 Teile = 12, ein Teil ist 12 : 3 = 4. Dann ist y = 8 und die Probe 4 + 8 = 12 stimmt.", "form": "zwei_wege", "zaehlt": "ja", "r": 776}, {"l": "verfahren", "t": "verfahren", "p": "uebung", "s": 2, "g": "umkehr", "y": "zahl", "f": {"text": "Die Summe zweier Zahlen ist 16, ihre Differenz ist 4. Wie groß ist die größere Zahl?"}, "o": {"wert": 10}, "h": "Addiere beide Angaben. Was bleibt von der kleineren Zahl übrig?", "w": "Größere Zahl g und kleinere k: g + k = 16 und g − k = 4. Beide Gleichungen addiert geben 2g = 20, also g = 10. Dann ist k = 6, die Probe 10 + 6 = 16 und 10 − 6 = 4 stimmt.", "form": "umkehren", "zaehlt": "ja", "r": 777}]$auf$::jsonb),
    (27, 'gleichungen.ungleichungen', 645, 23, $auf$[{"l": "intervall", "t": "intervall", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Löse 2x + 6 ≥ 14. Auf beiden Seiten 6 abziehen: 2x ≥ ①. Durch 2 teilen: x ≥ ②. Die Lösungsmenge ist das Intervall [②; ∞[.", "schablone": "① = □; ② = □", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ)."}, "o": {"werte": [8, 4]}, "h": "Die Grenze gehört dazu, weil „≥“ dasteht.", "w": "2x ≥ 8, also x ≥ 4. L = [4; ∞[.", "form": "lueckenweg", "zaehlt": "nein", "r": 660}, {"l": "pruefen", "t": "pruefen", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Prüfe, ob x = 5 die Ungleichung 2x + 3 ≤ 12 löst. Einsetzen: 2 · 5 + 3 = ①. Das liegt um ① − 12 = ② über 12, also ist 5 keine Lösung. Prüfe die Zahl, die um ② kleiner ist als 5: 2 · (5 − ②) + 3 = ③. Das ist kleiner als 12, also ist diese Zahl eine Lösung.", "schablone": "① = □; ② = □; ③ = □", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ)."}, "o": {"werte": [13, 1, 11]}, "h": "Setze die Zahl in die linke Seite ein. Mal geht vor Plus.", "w": "2 · 5 + 3 = 13, das ist um 1 größer als 12. Die Zahl 5 − 1 = 4 ergibt 2 · 4 + 3 = 11 ≤ 12.", "form": "lueckenweg", "zaehlt": "nein", "r": 661}, {"l": "grafisch", "t": "grafisch", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Die Geraden f(x) = 3x + 1 und g(x) = x + 9 schneiden sich dort, wo 3x + 1 = x + 9 gilt. Auf beiden Seiten x und 1 abziehen: 2x = ①. Also ist x = ②. Der Schnittpunkt hat den y-Wert f(②) = ③.", "schablone": "① = □; ② = □; ③ = □", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ)."}, "o": {"werte": [8, 4, 13]}, "h": "Beim Schnittpunkt sind beide Funktionswerte gleich.", "w": "2x = 8, also x = 4. f(4) = 3 · 4 + 1 = 13, und g(4) = 4 + 9 = 13.", "form": "lueckenweg", "zaehlt": "nein", "r": 662}, {"l": "sachaufgabe", "t": "sachaufgabe", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Ein Lastenaufzug darf höchstens 500 kg tragen. Ein Rollwagen wiegt 30 kg. Jede Kiste darauf wiegt 40 kg. Für k Kisten muss gelten: 30 + 40 · k ≤ 500. Also ist 40 · k ≤ ①. Die größte ganze Zahl k, die passt, ist ②.", "schablone": "① = □; ② = □", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ)."}, "o": {"werte": [470, 11]}, "h": "Teile durch 40 und lass die Nachkommastellen weg: Man kann keine halbe Kiste laden.", "w": "40 · k ≤ 470, also k ≤ 11,75. Ganze Kisten: höchstens 11.", "form": "lueckenweg", "zaehlt": "nein", "r": 663}, {"l": "umformen", "t": "umformen", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "auswahl", "f": {"text": "Wie löst du 4x − 9 ≥ 15 richtig?"}, "a": ["Auf beiden Seiten 9 abziehen: 4x ≥ 6. Durch 4 teilen: x ≥ 1,5", "Auf beiden Seiten 9 addieren: 4x ≥ 24. Durch 4 teilen: x ≥ 6", "Nur 4x durch 4 teilen: x − 9 ≥ 15. Dann 9 addieren: x ≥ 24", "Beide Seiten durch 4 teilen: x − 9 ≥ 3. Dann 9 addieren: x ≥ 12"], "o": {"index": 1}, "h": "Erst die Zahl ohne x auf die andere Seite bringen. Dann teilen.", "w": "4x − 9 ≥ 15, also 4x ≥ 24 und x ≥ 6. Probe: x = 6: 4 · 6 − 9 = 15.", "form": "verfahren_waehlen", "zaehlt": "ja", "r": 664}, {"l": "umdrehen", "t": "umdrehen", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "auswahl", "f": {"text": "Löse −3x + 4 > 19. Welcher Weg ist richtig?"}, "a": ["4 abziehen: −3x > 15. Durch −3 teilen, aber das Zeichen lassen: x > −5", "4 abziehen: −3x > 15. Durch −3 teilen und das Zeichen umdrehen: x < −5", "4 abziehen: −3x > 15. Durch 3 teilen: x > 5", "4 abziehen: −3x > 15. Durch −3 teilen und das Zeichen umdrehen: x < 5"], "o": {"index": 1}, "h": "Beim Teilen durch eine negative Zahl dreht sich das Zeichen um.", "w": "−3x > 15. Durch −3 teilen: x < −5. Probe: x = −6: −3 · (−6) + 4 = 22 > 19.", "form": "verfahren_waehlen", "zaehlt": "ja", "r": 665}, {"l": "klammern", "t": "klammern", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "auswahl", "f": {"text": "Löse 3(x + 2) ≥ 5x − 4. Welche Lösung stimmt?"}, "a": ["Klammer auflösen: 3x + 6 ≥ 5x − 4. Daraus folgt x ≥ 5", "Klammer auflösen: 3x + 2 ≥ 5x − 4. Daraus folgt x ≤ 3", "Klammer auflösen: 3x + 6 ≥ 5x − 4. Daraus folgt x ≥ −5", "Klammer auflösen: 3x + 6 ≥ 5x − 4. Daraus folgt x ≤ 5"], "o": {"index": 3}, "h": "Ordne: x-Terme auf eine Seite, Zahlen auf die andere. Beachte das Vorzeichen von x am Ende.", "w": "3x + 6 ≥ 5x − 4 → 10 ≥ 2x → x ≤ 5. Probe: x = 5: 3 · 7 = 21 ≥ 21.", "form": "verfahren_waehlen", "zaehlt": "ja", "r": 666}, {"l": "intervall", "t": "intervall", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "auswahl", "f": {"text": "Löse 5 − x < 2 und gib die Lösungsmenge als Intervall an. Welche Antwort stimmt?"}, "a": ["−x < −3, durch −1 teilen und das Zeichen umdrehen: x > 3, also L = ]3; ∞[", "−x < −3, daraus folgt x < 3, also L = ]−∞; 3[", "−x < −3, durch −1 teilen und das Zeichen umdrehen: x > 3, also L = [3; ∞[", "−x < −3, daraus folgt x > −3, also L = ]−3; ∞["], "o": {"index": 0}, "h": "Auch bei −x dreht sich das Zeichen um, denn du teilst durch −1.", "w": "5 − x < 2 → −x < −3 → x > 3. Die 3 gehört nicht dazu: L = ]3; ∞[.", "form": "verfahren_waehlen", "zaehlt": "ja", "r": 667}, {"l": "grafisch", "t": "grafisch", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "auswahl", "f": {"text": "Die Geraden f(x) = −x + 6 und g(x) = 2x schneiden sich bei x = 2. Für welche x gilt f(x) ≥ g(x)?"}, "a": ["für x ≥ 2, denn rechts vom Schnittpunkt liegt f über g", "für x ≤ 6, denn bei x = 6 ist f(x) = 0", "für x ≤ 2, denn links vom Schnittpunkt liegt f über g", "für x ≥ 6, denn dort ist g größer"], "o": {"index": 2}, "h": "Setze eine Zahl links vom Schnittpunkt ein, zum Beispiel x = 0.", "w": "f(0) = 6 und g(0) = 0: links liegt f über g. Also f(x) ≥ g(x) für x ≤ 2.", "form": "verfahren_waehlen", "zaehlt": "ja", "r": 668}, {"l": "sachaufgabe", "t": "sachaufgabe", "p": "uebung", "s": 2, "g": "einkleidung", "y": "auswahl", "f": {"text": "Ein Taxi kostet 3 € Grundpreis und 2 € je Kilometer. Du hast 25 €. Wie viele Kilometer kannst du höchstens fahren? Welcher Ansatz passt?"}, "a": ["3 + 2x ≥ 25, also x ≥ 11: mindestens 11 km", "2 + 3x ≤ 25, also x ≤ 7: höchstens 7 km", "3 + 2x ≤ 25, also x ≤ 11: höchstens 11 km", "2x ≤ 25, also x ≤ 12: höchstens 12 km"], "o": {"index": 2}, "h": "Gesamtkosten = Grundpreis + Preis je km mal Kilometer. Sie dürfen 25 € nicht übersteigen.", "w": "3 + 2x ≤ 25 → 2x ≤ 22 → x ≤ 11. Bei 11 km zahlst du genau 25 €.", "form": "verfahren_waehlen", "zaehlt": "ja", "r": 669}, {"l": "umformen", "t": "umformen", "p": "uebung", "s": 3, "g": "fehler", "y": "auswahl", "f": {"text": "Kim löst 4x + 6 > 30. Zeile 1: Auf beiden Seiten 6 addieren: 4x > 36. Zeile 2: Durch 4 teilen: x > 9. Zeile 3: Die Lösung sind alle Zahlen größer als 9. In welcher Zeile passiert der erste Fehler?"}, "a": ["In Zeile 1", "In Zeile 2", "In Zeile 3"], "o": {"index": 0}, "h": "Wie macht man „plus 6“ rückgängig?", "w": "Plus 6 macht man mit minus 6 rückgängig: 4x > 24, also x > 6. Die Zeilen 2 und 3 folgen richtig aus der falschen Zeile 1.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 670}, {"l": "klammern", "t": "klammern", "p": "uebung", "s": 3, "g": "fehler", "y": "auswahl", "f": {"text": "Kim löst 2(x − 3) < x + 5. Zeile 1: Klammer auflösen: 2x − 3 < x + 5. Zeile 2: Auf beiden Seiten x abziehen: x − 3 < 5. Zeile 3: Auf beiden Seiten 3 addieren: x < 8. In welcher Zeile passiert der erste Fehler?"}, "a": ["In Zeile 1", "In Zeile 2", "In Zeile 3"], "o": {"index": 0}, "h": "Beim Auflösen der Klammer wird jede Zahl in der Klammer mit 2 multipliziert.", "w": "2(x − 3) = 2x − 6, nicht 2x − 3. Richtig: 2x − 6 < x + 5, also x < 11.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 671}, {"l": "intervall", "t": "intervall", "p": "uebung", "s": 3, "g": "fehler", "y": "auswahl", "f": {"text": "Kim löst −2x ≤ 10 und schreibt die Lösung als Intervall. Zeile 1: Durch −2 teilen, das Zeichen bleibt: x ≤ −5. Zeile 2: Die Grenze −5 gehört dazu, die Klammer zeigt zur Zahl hin: −5]. Zeile 3: Es geht unbegrenzt nach links: L = ]−∞; −5]. In welcher Zeile passiert der erste Fehler?"}, "a": ["In Zeile 1", "In Zeile 2", "In Zeile 3"], "o": {"index": 0}, "h": "Was passiert mit dem Zeichen, wenn du durch eine negative Zahl teilst?", "w": "Beim Teilen durch −2 dreht sich das Zeichen um: x ≥ −5, also L = [−5; ∞[. Die Zeilen 2 und 3 passen zur falschen Zeile 1.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 672}, {"l": "pruefen", "t": "pruefen", "p": "uebung", "s": 3, "g": "fehler", "y": "auswahl", "f": {"text": "Kim löst −2x + 1 > 7 und prüft das Ergebnis. Zeile 1: 1 abziehen: −2x > 6. Zeile 2: Durch −2 teilen: x > −3. Zeile 3: Probe mit x = 0: −2 · 0 + 1 = 1, und 1 > 7 stimmt nicht. In welcher Zeile passiert der erste Fehler?"}, "a": ["In Zeile 1", "In Zeile 2", "In Zeile 3"], "o": {"index": 1}, "h": "Die Probe zeigt: 0 ist größer als −3 und trotzdem keine Lösung.", "w": "Durch −2 teilen dreht das Zeichen um: x < −3. Die Probe mit x = 0 deckt den Fehler auf.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 673}, {"l": "grafisch", "t": "grafisch", "p": "uebung", "s": 3, "g": "fehler", "y": "auswahl", "f": {"text": "Die Geraden f(x) = x + 2 und g(x) = 3x − 4 schneiden sich bei x = 3. Kim löst f(x) < g(x) mit den Graphen. Zeile 1: f(x) < g(x) heißt: Der Graph von f liegt über dem von g. Zeile 2: Links von x = 3 liegt g unter f, rechts von x = 3 liegt g über f. Zeile 3: f(x) < g(x) gilt also für alle x < 3. In welcher Zeile passiert der erste Fehler?"}, "a": ["In Zeile 1", "In Zeile 2", "In Zeile 3"], "o": {"index": 0}, "h": "Bei f(x) < g(x): Welcher der beiden Graphen liegt unten?", "w": "f(x) < g(x) heißt: f liegt unter g. Das ist rechts vom Schnittpunkt der Fall: x > 3.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 674}, {"l": "sachaufgabe", "t": "sachaufgabe", "p": "uebung", "s": 3, "g": "fehler", "y": "auswahl", "f": {"text": "Ein Verein verlangt 8 € Grundgebühr und 3 € für jeden Besuch. Kim hat höchstens 50 € zur Verfügung und will wissen, wie oft er kommen kann. Zeile 1: Ansatz: 8 + 3x ≥ 50. Zeile 2: 8 abziehen: 3x ≥ 42. Zeile 3: Durch 3 teilen: x ≥ 14. In welcher Zeile passiert der erste Fehler?"}, "a": ["In Zeile 1", "In Zeile 2", "In Zeile 3"], "o": {"index": 0}, "h": "Welches Zeichen gehört zu „höchstens“?", "w": "„Höchstens 50 €“ heißt: Die Kosten sind kleiner oder gleich 50. Richtig: 8 + 3x ≤ 50, also x ≤ 14.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 675}, {"l": "grafisch", "t": "grafisch", "p": "uebung", "s": 2, "g": "darstellung", "y": "auswahl", "f": {"text": "Die Ungleichung x < −1 soll auf der Zahlengeraden dargestellt werden. Welche Darstellung ist richtig?"}, "a": ["offener Kreis bei −1, Pfeil nach links", "ausgefüllter Punkt bei −1, Pfeil nach links", "offener Kreis bei −1, Pfeil nach rechts", "offener Kreis bei 1, Pfeil nach links"], "o": {"index": 0}, "h": "Ein ausgefüllter Punkt gehört zur Lösung, ein offener Kreis nicht.", "w": "Die Zahl −1 selbst erfüllt x < −1 nicht, deshalb steht bei −1 ein offener Kreis. Gesucht sind Zahlen kleiner als −1, der Pfeil zeigt nach links.", "form": "bruecke", "zaehlt": "ja", "r": 676}, {"l": "intervall", "t": "intervall", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Wie viele ganze Zahlen liegen im Intervall [−2; 5], beide Grenzen gehören dazu? Weg A: alle aufzählen. Weg B: 5 − (−2) + 1 rechnen."}, "o": {"wert": 8}, "h": "Bei Grenzen, die dazugehören, zählt man beide Enden mit.", "w": "Weg A: −2, −1, 0, 1, 2, 3, 4, 5 sind 8 Zahlen. Weg B: 5 − (−2) = 7 Schritte, dazu die 1 für das erste Ende, also 8.", "form": "zwei_wege", "zaehlt": "ja", "r": 677}, {"l": "klammern", "t": "klammern", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Gelöst werden soll 3 · (x + 2) > 21. Weg A: die Klammer ausmultiplizieren, 3x + 6 > 21. Weg B: erst beide Seiten durch 3 teilen, x + 2 > 7. Wie lautet die kleinste ganze Zahl, die die Ungleichung erfüllt?"}, "o": {"wert": 6}, "h": "Beide Wege geben x > 5. Wird die 5 selbst erfüllt?", "w": "Weg A: 3x > 15, also x > 5. Weg B: x > 5. Die Zahl 5 erfüllt „größer als 5“ nicht, die kleinste ganze Lösung ist 6. Probe: 3 · (6 + 2) = 24 > 21.", "form": "zwei_wege", "zaehlt": "ja", "r": 678}, {"l": "pruefen", "t": "pruefen", "p": "uebung", "s": 2, "g": "darstellung", "y": "auswahl", "f": {"text": "Auf einem Zahlenstrahl ist die Zahl 4 grün markiert (sie erfüllt eine Ungleichung) und die Zahl 6 rot (sie erfüllt sie nicht). Welche Ungleichung passt zu dieser Markierung?"}, "a": ["2x − 3 < 7", "2x − 3 > 7", "2x − 3 < 3", "2x + 3 < 7"], "o": {"index": 0}, "h": "Setze 4 und 6 in jede Ungleichung ein. Die richtige gilt für 4 und gilt nicht für 6.", "w": "x = 4: 2 · 4 − 3 = 5, und 5 < 7 stimmt. x = 6: 2 · 6 − 3 = 9, und 9 < 7 stimmt nicht. Die Markierung passt zu 2x − 3 < 7. Bei 2x − 3 > 7 wäre es umgekehrt, bei den anderen beiden gilt sie schon für 4 nicht.", "form": "bruecke", "zaehlt": "ja", "r": 679}, {"l": "sachaufgabe", "t": "sachaufgabe", "p": "uebung", "s": 2, "g": "umkehr", "y": "zahl", "f": {"text": "Eine Taxifahrt kostet 4 € Grundpreis plus 2 € für jeden gefahrenen Kilometer. Du willst höchstens 30 € bezahlen. Wie viele ganze Kilometer darfst du höchstens fahren?"}, "o": {"wert": 13, "einheit": "km"}, "h": "Ziehe zuerst den Grundpreis ab. Was bleibt für die Kilometer?", "w": "Für die Kilometer bleiben 30 − 4 = 26 €. Jeder Kilometer kostet 2 €, also 26 : 2 = 13 Kilometer. Probe: 4 + 13 · 2 = 30 €.", "form": "umkehren", "zaehlt": "ja", "r": 680}, {"l": "umdrehen", "t": "umdrehen", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Gelöst werden soll −2x > 6. Weg A: durch −2 teilen und das Zeichen umdrehen. Weg B: zu beiden Seiten 2x addieren, dann 6 abziehen, dann durch 2 teilen. Welche ganze Zahl ist die größte Lösung?"}, "o": {"wert": -4}, "h": "Beide Wege geben x < −3. Die −3 selbst gehört nicht dazu.", "w": "Weg A: durch −2 teilen, das Zeichen dreht sich um: x < −3. Weg B: 0 > 6 + 2x, dann −6 > 2x, dann −3 > x. Die größte ganze Zahl kleiner als −3 ist −4. Probe: −2 · (−4) = 8 > 6.", "form": "zwei_wege", "zaehlt": "ja", "r": 681}, {"l": "umformen", "t": "umformen", "p": "uebung", "s": 2, "g": "umkehr", "y": "zahl", "f": {"text": "Du verdoppelst eine ganze Zahl und addierst 5. Das Ergebnis ist größer als 21. Wie lautet die kleinste ganze Zahl, auf die das zutrifft?"}, "o": {"wert": 9}, "h": "Stelle die Ungleichung auf: 2x + 5 > 21, und forme um.", "w": "2x + 5 > 21 gibt 2x > 16 und x > 8. Die Zahl 8 selbst erfüllt es nicht (2 · 8 + 5 = 21), die kleinste ganze Zahl ist 9.", "form": "umkehren", "zaehlt": "ja", "r": 682}]$auf$::jsonb),
    (40, 'zahlen.intervalle', 501, 13, $auf$[{"l": "lesen", "t": "lesen", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Das Intervall ]−3; 5[ enthält alle Zahlen zwischen −3 und 5, ohne die Grenzen. Die kleinste ganze Zahl darin ist ①. Die größte ganze Zahl darin ist ②. Von ① bis ② liegen ② − (①) + 1 = ③ ganze Zahlen.", "schablone": "① = □; ② = □; ③ = □", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ)."}, "o": {"werte": [-2, 4, 7]}, "h": "Die Grenzen selbst gehören nicht dazu.", "w": "Die kleinste ganze Zahl ist −2, die größte 4. Von −2 bis 4 sind es 4 − (−2) + 1 = 7 Zahlen.", "form": "lueckenweg", "zaehlt": "nein", "r": 507}, {"l": "schreiben", "t": "schreiben", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "x + 3 ≥ 9 ergibt x ≥ ①. x − 2 < 5 ergibt x < ②. Beides zusammen: ① ≤ x < ②. Als Intervall schreibst du das so: L = [①; ②[. Die Länge dieses Intervalls ist ② − ① = ③.", "schablone": "① = □; ② = □; ③ = □", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ)."}, "o": {"werte": [6, 7, 1]}, "h": "Erst beide Ungleichungen einzeln lösen.", "w": "x ≥ 6 und x < 7. Das Intervall ist [6; 7[ und hat die Länge 7 − 6 = 1.", "form": "lueckenweg", "zaehlt": "nein", "r": 508}, {"l": "enthalten", "t": "enthalten", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Das Intervall [−1; 4[ enthält die untere Grenze, aber nicht die obere. Die größte ganze Zahl darin ist 4 − 1 = ①. Die kleinste ist −1. Von −1 bis ① zählt man ① − (−1) + 1 = ② ganze Zahlen.", "schablone": "① = □; ② = □", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ)."}, "o": {"werte": [3, 5]}, "h": "Zähle von der unteren Grenze bis kurz vor der oberen.", "w": "Die größte ganze Zahl ist 3. Von −1 bis 3 sind es 3 + 1 + 1 = 5 Zahlen: −1, 0, 1, 2, 3.", "form": "lueckenweg", "zaehlt": "nein", "r": 509}, {"l": "beurteilen", "t": "beurteilen", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Kim sagt: „]1; 6[ und [2; 5] enthalten dieselben ganzen Zahlen.“ Schreibe beide Mengen auf und vergleiche die Elemente. In ]1; 6[ liegen ① ganze Zahlen, in [2; 5] liegen ② ganze Zahlen. Jede Zahl aus [2; 5] liegt auch in ]1; 6[. In [2; 5] fehlen also ① − ② = ③ der ganzen Zahlen aus ]1; 6[. Daran erkennt man, ob Kims Aussage stimmt.", "schablone": "① = □; ② = □; ③ = □", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ)."}, "o": {"werte": [4, 4, 0]}, "h": "Schreibe die ganzen Zahlen beider Intervalle auf.", "w": "In ]1; 6[ liegen 2, 3, 4, 5. In [2; 5] liegen 2, 3, 4, 5. Es fehlt nichts, die Mengen sind gleich. Gleich viele Zahlen allein würde als Beweis nicht reichen; man vergleicht die Elemente.", "form": "lueckenweg", "zaehlt": "nein", "r": 510}, {"l": "schreiben", "t": "schreiben", "p": "uebung", "s": 2, "g": "einkleidung", "y": "auswahl", "f": {"text": "Ein Paket darf mindestens 2 kg und höchstens 9 kg wiegen. Wie schreibst du die erlaubten Gewichte als Intervall?"}, "a": ["[2; 9], denn beide Grenzen gehören dazu", "]2; 9[", "[2; 9[", "]2; 9]"], "o": {"index": 0}, "h": "„Mindestens“ und „höchstens“ lassen die Grenze zu.", "w": "Mindestens 2 heißt: 2 gehört dazu. Höchstens 9 heißt: 9 gehört dazu. L = [2; 9].", "form": "verfahren_waehlen", "zaehlt": "ja", "r": 511}, {"l": "enthalten", "t": "enthalten", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "auswahl", "f": {"text": "Wie viele ganze Zahlen liegen im Intervall [−3; 4]? Welche Rechnung ist richtig?"}, "a": ["4 − (−3) = 7", "4 − (−3) − 1 = 6", "4 − 3 + 1 = 2", "4 − (−3) + 1 = 8, denn beide Grenzen gehören dazu"], "o": {"index": 3}, "h": "Nimm als Beispiel [1; 3]: Wie viele ganze Zahlen sind das?", "w": "Beide Grenzen zählen mit: −3, −2, −1, 0, 1, 2, 3, 4 sind 8 Zahlen. Rechnung: 4 + 3 + 1 = 8.", "form": "verfahren_waehlen", "zaehlt": "ja", "r": 512}, {"l": "beurteilen", "t": "beurteilen", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "auswahl", "f": {"text": "Kim sagt: „Jede Zahl im Intervall [0; 5] liegt auch im Intervall ]0; 6[.“ Wie prüfst du das?"}, "a": ["Es stimmt, denn 5 ist kleiner als 6", "Es stimmt nicht: 0 liegt in [0; 5], aber nicht in ]0; 6[", "Es stimmt, denn beide Intervalle beginnen bei 0", "Es stimmt nicht: 5 liegt in [0; 5], aber nicht in ]0; 6["], "o": {"index": 1}, "h": "Prüfe die Grenzen einzeln, besonders die Klammern.", "w": "0 gehört zu [0; 5], aber nicht zu ]0; 6[. Ein Gegenbeispiel genügt: Die Aussage ist falsch.", "form": "verfahren_waehlen", "zaehlt": "ja", "r": 513}, {"l": "lesen", "t": "lesen", "p": "uebung", "s": 2, "g": "darstellung", "y": "auswahl", "f": {"text": "Die Zahlen x mit −1 ≤ x < 6 sollen als Intervall geschrieben werden. Welche Schreibweise passt?"}, "a": ["]−1; 6[", "[−1; 6[", "[−1; 6]", "]−1; 6]"], "o": {"index": 1}, "h": "Gehört die Grenze dazu, zeigt die Klammer zur Zahl hin.", "w": "−1 gehört dazu (≤): die Klammer zeigt zur −1. 6 gehört nicht dazu (<): die Klammer zeigt von der 6 weg. Also [−1; 6[.", "form": "bruecke", "zaehlt": "ja", "r": 514}, {"l": "schreiben", "t": "schreiben", "p": "uebung", "s": 3, "g": "fehler", "y": "auswahl", "f": {"text": "Kim schreibt „alle Zahlen größer als −1 und höchstens 4“ als Intervall. Zeile 1: Die untere Grenze −1: „größer als“, also gehört −1 dazu. Die Klammer zeigt zur Zahl: [−1. Zeile 2: Die obere Grenze 4: „höchstens“, also gehört 4 dazu. Die Klammer zeigt zur Zahl: 4]. Zeile 3: Zusammen: L = [−1; 4]. In welcher Zeile passiert der erste Fehler?"}, "a": ["In Zeile 1", "In Zeile 2", "In Zeile 3"], "o": {"index": 0}, "h": "Gehört −1 dazu, wenn „größer als“ dasteht?", "w": "„Größer als −1“ schließt −1 aus: Die Klammer zeigt weg, ]−1. Richtig ist L = ]−1; 4]. Zeile 3 folgt richtig aus Zeile 1 und 2.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 515}, {"l": "enthalten", "t": "enthalten", "p": "uebung", "s": 3, "g": "fehler", "y": "auswahl", "f": {"text": "Kim prüft, welche der Zahlen −2, 0, 3 und 7 zum Intervall ]−2; 7] gehören. Zeile 1: −2 ist die Grenze. Die Klammer zeigt zur Zahl hin, also gehört −2 dazu. Zeile 2: 0 und 3 liegen zwischen −2 und 7, also gehören sie dazu. Zeile 3: 7 ist die Grenze. Die Klammer zeigt zur Zahl hin, also gehört 7 dazu. In welcher Zeile passiert der erste Fehler?"}, "a": ["In Zeile 1", "In Zeile 2", "In Zeile 3"], "o": {"index": 0}, "h": "Welche Klammer steht bei −2: eine, die zur Zahl zeigt, oder eine, die wegzeigt?", "w": "Bei −2 steht „]“: Die Klammer zeigt weg von der Zahl, −2 gehört nicht dazu. Die Zahlen 0, 3 und 7 gehören dazu.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 516}, {"l": "beurteilen", "t": "beurteilen", "p": "uebung", "s": 2, "g": "darstellung", "y": "auswahl", "f": {"text": "Welche Aussage über das Intervall [2; 7) stimmt?"}, "a": ["2 liegt im Intervall, 7 nicht.", "7 liegt im Intervall, 2 nicht.", "Beide Zahlen liegen im Intervall.", "Keine der beiden Zahlen liegt im Intervall."], "o": {"index": 0}, "h": "Eine eckige Klammer schließt die Grenze ein, eine runde schließt sie aus.", "w": "Bei [2 gehört die 2 dazu, bei 7) gehört die 7 nicht dazu. Die Zahl 2 liegt im Intervall, die 7 nicht.", "form": "bruecke", "zaehlt": "ja", "r": 517}, {"l": "enthalten", "t": "enthalten", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Wie viele ganze Zahlen liegen im Intervall (1; 6], die 1 gehört nicht dazu, die 6 gehört dazu? Weg A: aufzählen. Weg B: 6 − 1 rechnen."}, "o": {"wert": 5}, "h": "Bei einer Grenze, die nicht dazugehört, wird sie nicht mitgezählt.", "w": "Weg A: 2, 3, 4, 5, 6 sind 5 Zahlen. Weg B: 6 − 1 = 5, weil nur ein Ende mitzählt.", "form": "zwei_wege", "zaehlt": "ja", "r": 518}, {"l": "schreiben", "t": "schreiben", "p": "uebung", "s": 2, "g": "umkehr", "y": "zahl", "f": {"text": "Ein Intervall beginnt bei 4 (die 4 gehört dazu) und ist 7 lang. Wie lautet die obere Grenze?"}, "o": {"wert": 11}, "h": "Von der unteren Grenze aus geht es die Länge des Intervalls nach rechts.", "w": "Obere Grenze = untere Grenze + Länge = 4 + 7 = 11. Das Intervall reicht von 4 bis 11. Probe: 11 − 4 = 7. Ob die 11 dazugehört, wird hier nicht gefragt.", "form": "umkehren", "zaehlt": "ja", "r": 519}]$auf$::jsonb),
    (47, 'geometrie.grundbegriffe', 622, 18, $auf$[{"l": "lagebeziehungen", "t": "lagebeziehungen", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Die senkrechte Linie g geht durch (4 | 0). Der Punkt P(9 | 2) hat von g den Abstand 9 − 4 = ① Einheiten. Die senkrechte Linie h geht durch (−1 | 0). Von P bis h sind es 9 − (−1) = ② Einheiten. Der Abstand der beiden Linien g und h ist ② − ① = ③ Einheiten.", "schablone": "① = □; ② = □; ③ = □", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ)."}, "o": {"werte": [5, 10, 5]}, "h": "Rechne die x-Koordinaten gegeneinander. Minus minus bedeutet plus.", "w": "9 − 4 = 5. 9 − (−1) = 10. 10 − 5 = 5: Von x = −1 bis x = 4 sind es 5 Einheiten.", "form": "lueckenweg", "zaehlt": "nein", "r": 637}, {"l": "kreis_lage", "t": "kreis_lage", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Ein Kreis hat den Radius 6 cm. Die Gerade g hat vom Mittelpunkt den Abstand 4 cm. Der Abstand ist ① cm kleiner als der Radius. Also schneidet g den Kreis in ② Punkten. Rückt g um ① cm + 3 cm weiter weg, hat sie den Abstand 4 + ① + 3 = ③ cm. Dann hat g mit dem Kreis ④ gemeinsame Punkte.", "schablone": "① = □; ② = □; ③ = □; ④ = □", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ)."}, "o": {"werte": [2, 2, 9, 0]}, "h": "Vergleiche den Abstand der Geraden vom Mittelpunkt mit dem Radius: kleiner, gleich oder größer?", "w": "6 − 4 = 2 cm. Abstand kleiner als der Radius: 2 gemeinsame Punkte (Sekante). Nach dem Rücken ist der Abstand 4 + 2 + 3 = 9 cm, das ist größer als der Radius: 0 gemeinsame Punkte (Passante). Bei nur 2 cm Rücken wäre der Abstand genau der Radius gewesen, dann gäbe es eine Tangente mit einem Punkt.", "form": "lueckenweg", "zaehlt": "nein", "r": 638}, {"l": "winkelarten", "t": "winkelarten", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Ein Winkel hat 250°. Ein gestreckter Winkel hat ①°. Der Winkel ist 250° − ①° = ②° größer als ein gestreckter Winkel, aber kleiner als ein voller Winkel. Deshalb heißt er überstumpf. Bis zum vollen Winkel fehlen noch 360° − 250° = ③°. Zwischen gestrecktem und vollem Winkel liegen ②° + ③° = ④°.", "schablone": "① = □; ② = □; ③ = □; ④ = □", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ)."}, "o": {"werte": [180, 70, 110, 180]}, "h": "Ein gestreckter Winkel ist eine gerade Linie.", "w": "Gestreckt: 180°. 250° − 180° = 70°. Bis 360° fehlen 110°. Zusammen 70° + 110° = 180°. Überstumpf heißt: größer als 180° und kleiner als 360°.", "form": "lueckenweg", "zaehlt": "nein", "r": 639}, {"l": "vierecke", "t": "vierecke", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Ein Parallelogramm hat zwei Paare gleich langer Gegenseiten: 9 cm und 5 cm. Die beiden Längen zusammen: 9 + 5 = ① cm. Jede Länge kommt zweimal vor, der Umfang ist also 2 · ① = ② cm. Ein Quadrat mit demselben Umfang hat die Seitenlänge ② : 4 = ③ cm.", "schablone": "① = □; ② = □; ③ = □", "hinweis": "Je Lücke eine ganze Zahl."}, "o": {"werte": [14, 28, 7]}, "h": "Jede Länge kommt zweimal vor. Ein Quadrat hat vier gleich lange Seiten.", "w": "9 + 5 = 14. 2 · 14 = 28 cm Umfang. Ein Quadrat hat vier gleich lange Seiten: 28 : 4 = 7 cm.", "form": "lueckenweg", "zaehlt": "nein", "r": 640}, {"l": "koordinaten", "t": "koordinaten", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "auswahl", "f": {"text": "Der Punkt A hat die Koordinaten (2 | 1). Der Punkt R liegt 3 Einheiten rechts von A und 4 Einheiten unter A. Welche Rechnung gibt die Koordinaten von R?"}, "a": ["x: 2 − 3 = −1 und y: 1 + 4 = 5, also R(−1 | 5)", "x: 3 + 4 = 7 und y: 2 + 1 = 3, also R(7 | 3)", "x: 2 + 3 = 5 und y: 1 − 4 = −3, also R(5 | −3)", "x: 1 − 4 = −3 und y: 2 + 3 = 5, also R(−3 | 5)"], "o": {"index": 2}, "h": "Rechts verändert die erste Zahl, oben und unten die zweite.", "w": "Rechts: x wird größer, 2 + 3 = 5. Unten: y wird kleiner, 1 − 4 = −3. R(5 | −3).", "form": "verfahren_waehlen", "zaehlt": "ja", "r": 641}, {"l": "lagebeziehungen", "t": "lagebeziehungen", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "auswahl", "f": {"text": "Der Punkt P(−3 | 4) und die senkrechte Linie g durch (5 | 0) sind gegeben. Welche Rechnung gibt den Abstand von P zu g?"}, "a": ["5 − (−3) = 8", "5 − 3 = 2", "5 + 4 = 9", "4 − 0 = 4"], "o": {"index": 0}, "h": "g ist senkrecht. In welche Richtung misst du dann den Abstand?", "w": "Das Lot auf eine senkrechte Linie verläuft waagrecht. Es zählen die x-Werte: 5 − (−3) = 8.", "form": "verfahren_waehlen", "zaehlt": "ja", "r": 642}, {"l": "verstehen", "t": "verstehen", "p": "uebung", "s": 2, "g": "umkehr", "y": "auswahl", "f": {"text": "Die Aussage „Jedes Quadrat ist ein Rechteck“ stimmt. Jetzt drehst du sie um: „Jedes Rechteck ist ein Quadrat.“ Stimmt die umgedrehte Aussage?"}, "a": ["Ja, beide haben vier rechte Winkel.", "Nein, ein Rechteck mit 6 cm und 3 cm ist kein Quadrat.", "Ja, alle Rechtecke haben vier gleich lange Seiten."], "o": {"index": 1}, "h": "Suche ein Rechteck mit zwei verschiedenen Seitenlängen.", "w": "Ein Rechteck mit 6 cm und 3 cm hat vier rechte Winkel, aber nicht gleich lange Seiten. Das ist ein Gegenbeispiel. Die umgedrehte Aussage stimmt nicht.", "form": "umkehren", "zaehlt": "ja", "r": 643}, {"l": "verstehen", "t": "verstehen", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Aussage: „Jedes Rechteck mit dem Umfang 24 cm ist ein Quadrat.“ Du suchst ein Gegenbeispiel mit einer Seite von 8 cm. Weg A: 24 − 8 − 8 = 8 und dann geteilt durch 2. Weg B: der halbe Umfang 24 : 2 = 12, davon 8 abziehen. Wie lang ist die andere Seite?"}, "o": {"wert": 4, "einheit": "cm"}, "h": "Beide Wege müssen dieselbe Länge ergeben.", "w": "Weg A: 24 − 8 − 8 = 8, geteilt durch 2 sind 4. Weg B: 12 − 8 = 4. Das Rechteck hat 8 cm und 4 cm, ist also kein Quadrat. Die Aussage stimmt nicht.", "form": "zwei_wege", "zaehlt": "ja", "r": 644}, {"l": "koordinaten", "t": "koordinaten", "p": "uebung", "s": 3, "g": "fehler", "y": "auswahl", "f": {"text": "Kim soll den Punkt P(−3 | 5) im Koordinatensystem finden. Zeile 1: Sie startet im Ursprung (0 | 0). Zeile 2: Die erste Zahl ist −3. Sie geht 3 Einheiten nach rechts. Zeile 3: Die zweite Zahl ist 5. Sie geht 5 Einheiten nach oben. In welcher Zeile passiert der erste Fehler?"}, "a": ["In Zeile 1", "In Zeile 2", "In Zeile 3"], "o": {"index": 1}, "h": "Eine negative erste Zahl heißt: in welche Richtung?", "w": "Die erste Zahl ist −3, also negativ. Negativ heißt links. Richtig: 3 Einheiten nach links.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 645}, {"l": "lagebeziehungen", "t": "lagebeziehungen", "p": "uebung", "s": 3, "g": "fehler", "y": "auswahl", "f": {"text": "Kim soll den Abstand des Punktes P(2 | 7) von der waagrechten Linie g durch (0 | 3) bestimmen. Zeile 1: Der Abstand ist die Länge des Lots von P auf g. Zeile 2: Das Lot steht senkrecht auf g. Es verläuft also in y-Richtung. Zeile 3: Kim rechnet 2 − 3 = −1. Ein Abstand ist nie negativ, also ist er 1. In welcher Zeile steckt der Fehler?"}, "a": ["In Zeile 1", "In Zeile 2", "In Zeile 3"], "o": {"index": 2}, "h": "Welche Koordinate von P gehört zur Höhe?", "w": "Das Lot verläuft in y-Richtung, also zählen die y-Werte: 7 und 3. Abstand: 7 − 3 = 4.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 647}, {"l": "kreis_lage", "t": "kreis_lage", "p": "uebung", "s": 3, "g": "fehler", "y": "auswahl", "f": {"text": "Ein Kreis hat den Radius 4 cm. Die Gerade g ist 7 cm vom Mittelpunkt entfernt. Kim sagt, was g für den Kreis ist. Zeile 1: Eine Gerade ist eine Sekante, wenn ihr Abstand vom Mittelpunkt größer als der Radius ist. Zeile 2: Hier ist der Abstand 7 cm und der Radius 4 cm. 7 ist größer als 4. Zeile 3: Also ist g eine Sekante und hat 2 Punkte mit dem Kreis gemeinsam. In welcher Zeile passiert der erste Fehler?"}, "a": ["In Zeile 1", "In Zeile 2", "In Zeile 3"], "o": {"index": 0}, "h": "Wie nahe muss die Gerade am Mittelpunkt sein, damit sie den Kreis schneidet?", "w": "Eine Sekante hat einen Abstand kleiner als der Radius. Hier ist der Abstand größer: g erreicht den Kreis nicht. g ist eine Passante und hat 0 gemeinsame Punkte.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 648}, {"l": "winkelarten", "t": "winkelarten", "p": "uebung", "s": 3, "g": "fehler", "y": "auswahl", "f": {"text": "Kim ordnet Winkel nach ihrer Art. Zeile 1: Stumpf ist jeder Winkel, der größer als 90° ist. Zeile 2: 135° ist stumpf, denn er ist größer als 90°. Zeile 3: 300° ist stumpf, denn er ist größer als 90°. In welcher Zeile passiert der erste Fehler?"}, "a": ["In Zeile 1", "In Zeile 2", "In Zeile 3"], "o": {"index": 0}, "h": "Wo hört „stumpf“ auf?", "w": "Stumpf sind Winkel zwischen 90° und 180°. 300° ist größer als 180°, also überstumpf.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 649}, {"l": "vierecke", "t": "vierecke", "p": "uebung", "s": 3, "g": "fehler", "y": "auswahl", "f": {"text": "Kim sortiert Vierecke. Zeile 1: Ein Quadrat hat vier gleich lange Seiten und vier rechte Winkel. Zeile 2: Jedes Quadrat hat vier rechte Winkel, also ist jedes Quadrat auch ein Rechteck. Zeile 3: Jedes Rechteck hat vier rechte Winkel, also ist jedes Rechteck auch ein Quadrat. Zeile 4: Eine Raute hat vier gleich lange Seiten. In welcher Zeile passiert der erste Fehler?"}, "a": ["In Zeile 1", "In Zeile 2", "In Zeile 3", "In Zeile 4"], "o": {"index": 2}, "h": "Denk an ein Rechteck, das 8 cm lang und 3 cm breit ist.", "w": "Ein Rechteck von 8 cm mal 3 cm hat vier rechte Winkel, aber keine vier gleich langen Seiten. Es ist kein Quadrat.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 650}, {"l": "verstehen", "t": "verstehen", "p": "uebung", "s": 3, "g": "fehler", "y": "auswahl", "f": {"text": "Kim prüft die Aussage „Jedes Viereck mit mindestens zwei rechten Winkeln ist ein Rechteck.“ Zeile 1: Ich zeichne ein Viereck mit vier rechten Winkeln und den Seiten 5 cm und 3 cm. Zeile 2: Das ist ein Rechteck. Zeile 3: Also gilt die Aussage für jedes Viereck mit mindestens zwei rechten Winkeln. In welcher Zeile passiert der erste Fehler?"}, "a": ["In Zeile 1", "In Zeile 2", "In Zeile 3"], "o": {"index": 2}, "h": "Reicht ein Beispiel, um eine „immer“-Aussage zu beweisen?", "w": "Ein einzelnes Beispiel kann eine „immer“-Aussage nicht beweisen. Es gibt Vierecke mit nur zwei rechten Winkeln, die kein Rechteck sind, zum Beispiel ein Trapez mit zwei rechten Winkeln.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 651}, {"l": "koordinaten", "t": "koordinaten", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Ein Rechteck hat die gegenüberliegenden Ecken A(1|1) und C(7|5), seine Seiten liegen parallel zu den Achsen. Weg A: Länge plus Breite, mal 2. Weg B: Länge verdoppeln, Breite verdoppeln und beides addieren. Wie groß ist der Umfang?"}, "o": {"wert": 20}, "h": "Länge und Breite lesen sich an den Koordinaten ab.", "w": "Länge: 7 − 1 = 6, Breite: 5 − 1 = 4. Weg A: (6 + 4) · 2 = 20. Weg B: 6 · 2 + 4 · 2 = 12 + 8 = 20. Der Umfang ist 20 Einheiten.", "form": "zwei_wege", "zaehlt": "ja", "r": 652}, {"l": "lagebeziehungen", "t": "lagebeziehungen", "p": "uebung", "s": 2, "g": "darstellung", "y": "auswahl", "f": {"text": "Die Gerade g hat von der Geraden h an jeder Stelle denselben Abstand von 3 cm. Welche Aussage über g und h stimmt?"}, "a": ["g und h sind parallel.", "g und h stehen senkrecht aufeinander.", "g und h schneiden sich in genau einem Punkt.", "g und h sind dieselbe Gerade."], "o": {"index": 0}, "h": "Überlege, ob sich Geraden mit überall gleichem Abstand je treffen.", "w": "Überall gleicher Abstand bedeutet: Die beiden Geraden nähern sich nie und treffen sich nie. Sie sind parallel. Senkrechte Geraden schneiden sich, dort wäre der Abstand 0.", "form": "bruecke", "zaehlt": "ja", "r": 653}, {"l": "vierecke", "t": "vierecke", "p": "uebung", "s": 2, "g": "umkehr", "y": "zahl", "f": {"text": "Eine Raute hat vier gleich lange Seiten und den Umfang 36 cm. Wie lang ist eine Seite?"}, "o": {"wert": 9, "einheit": "cm"}, "h": "Der Umfang ist die Summe aller vier Seiten.", "w": "Alle vier Seiten sind gleich lang, der Umfang ist 4 · Seite. Also ist die Seite 36 : 4 = 9 cm.", "form": "umkehren", "zaehlt": "ja", "r": 654}, {"l": "winkelarten", "t": "winkelarten", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Ein stumpfer Winkel ist 115° groß. Weg A: 180° − 115°. Weg B: erst 180° − 100°, dann noch 15° abziehen. Wie groß ist sein Nebenwinkel?"}, "o": {"wert": 65, "einheit": "°"}, "h": "Winkel und Nebenwinkel ergeben zusammen einen gestreckten Winkel.", "w": "Ein gestreckter Winkel hat 180°. Weg A: 180° − 115° = 65°. Weg B: 180° − 100° = 80°, 80° − 15° = 65°. Der Nebenwinkel ist 65° und damit ein spitzer Winkel.", "form": "zwei_wege", "zaehlt": "ja", "r": 655}]$auf$::jsonb),
    (48, 'geometrie.ortslinien', 574, 21, $auf$[{"l": "kreislinie", "t": "kreislinie", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Ein Kreis hat den Mittelpunkt M(7 | 2) und den Radius 5. Der Punkt P(7 | 10) liegt senkrecht über M. Sein Abstand zu M ist 10 − 2 = ①. Der Punkt Q(7 | 6) liegt auch senkrecht über M. Sein Abstand zu M ist 6 − 2 = ②. P liegt um ① − 5 = ③ außerhalb des Kreises, Q liegt um 5 − ② = ④ innerhalb.", "schablone": "① = □; ② = □; ③ = □; ④ = □", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ)."}, "o": {"werte": [8, 4, 3, 1]}, "h": "Beide Punkte haben dieselbe x-Koordinate wie M. Es zählt nur die Höhe.", "w": "10 − 2 = 8 und 6 − 2 = 4. P ist 8 von M entfernt, der Radius ist 5: P liegt 3 außerhalb. Q liegt 5 − 4 = 1 innerhalb.", "form": "lueckenweg", "zaehlt": "nein", "r": 580}, {"l": "parallelen", "t": "parallelen", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Die waagrechte Linie g geht durch (0 | 4). Alle Punkte mit dem Abstand 3 von g liegen auf zwei Parallelen. Die obere geht durch y = 4 + 3 = ①. Die untere geht durch y = 4 − 3 = ②. Die beiden Parallelen sind ① − ② = ③ Einheiten voneinander entfernt.", "schablone": "① = □; ② = □; ③ = □", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ)."}, "o": {"werte": [7, 1, 6]}, "h": "Eine Parallele liegt über g, eine unter g.", "w": "Obere: 7, untere: 1. 7 − 1 = 6, das ist 2 · 3.", "form": "lueckenweg", "zaehlt": "nein", "r": 581}, {"l": "zwei_kreise", "t": "zwei_kreise", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Ein Kreis um A(1 | 0) hat den Radius 4. Ein Kreis um B(9 | 0) hat den Radius 6. Der Abstand AB ist 9 − 1 = ①. Die beiden Radien zusammen: 4 + 6 = ②. Ihr Unterschied: 6 − 4 = ③. Es gilt ③ < ① < ②. Also schneiden sich die Kreise in ④ Punkten.", "schablone": "① = □; ② = □; ③ = □; ④ = □", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ)."}, "o": {"werte": [8, 10, 2, 2]}, "h": "Vergleiche den Abstand AB mit der Summe und mit dem Unterschied der Radien.", "w": "AB = 8, Radien zusammen 10, Unterschied 2. Der Abstand liegt dazwischen: 2 Schnittpunkte.", "form": "lueckenweg", "zaehlt": "nein", "r": 582}, {"l": "verknuepfen", "t": "verknuepfen", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Ein Kreis hat den Mittelpunkt M(1 | 7) und den Radius 5. Die senkrechte Linie g geht durch x = 4. Ihr Abstand zu M ist 4 − 1 = ①. Weil ① kleiner als der Radius ist, hat g mit dem Kreis ② gemeinsame Punkte. Die senkrechte Linie h geht durch x = 10. Ihr Abstand zu M ist 10 − 1 = ③. Weil ③ größer als der Radius ist, hat h mit dem Kreis ④ gemeinsame Punkte.", "schablone": "① = □; ② = □; ③ = □; ④ = □", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ)."}, "o": {"werte": [3, 2, 9, 0]}, "h": "Vergleiche den Abstand der Linie von M mit dem Radius: kleiner, gleich oder größer?", "w": "4 − 1 = 3 < 5: zwei Punkte. 10 − 1 = 9 > 5: kein Punkt.", "form": "lueckenweg", "zaehlt": "nein", "r": 583}, {"l": "sachsituationen", "t": "sachsituationen", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Ein Hund ist mit einer 4 m langen Leine an einen Pfahl gebunden. Der Pfahl steht 11 m vom Straßenrand entfernt. Der Hund kommt bis auf 11 − 4 = ① m an den Straßenrand heran. Wäre die Leine 13 m lang, ragte der Kreis 13 − 11 = ② m über den Straßenrand hinaus. Die beiden Leinen unterscheiden sich um ① + ② = ③ m.", "schablone": "① = □; ② = □; ③ = □", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ)."}, "o": {"werte": [7, 2, 9]}, "h": "Die Leine ist der Radius des Kreises.", "w": "11 − 4 = 7 m bleiben bis zum Straßenrand. 13 − 11 = 2 m zu viel. 7 + 2 = 9 = 13 − 4.", "form": "lueckenweg", "zaehlt": "nein", "r": 584}, {"l": "kreislinie", "t": "kreislinie", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "auswahl", "f": {"text": "Ein Kreis um M(2 | 2) hat den Radius 5. Wie findest du heraus, ob der Punkt P(7 | 2) auf der Kreislinie liegt?"}, "a": ["7 + 2 = 9 rechnen: 9 ist größer als 5, also außerhalb", "7 − 5 = 2 rechnen: gleich der y-Koordinate, also innerhalb", "2 + 2 = 4 rechnen: 4 ist kleiner als 5, also innerhalb", "Abstand 7 − 2 = 5 berechnen: gleich dem Radius, also auf der Kreislinie"], "o": {"index": 3}, "h": "P und M haben dieselbe Höhe. Wie groß ist ihr Abstand?", "w": "P und M liegen auf einer Höhe. Der Abstand ist 7 − 2 = 5. Das ist gleich dem Radius: P liegt auf der Kreislinie.", "form": "verfahren_waehlen", "zaehlt": "ja", "r": 585}, {"l": "parallelen", "t": "parallelen", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "auswahl", "f": {"text": "Die waagrechte Linie g geht durch (0 | 2). Welche Punkte haben von g höchstens den Abstand 3?"}, "a": ["nur die Punkte mit y = −1 oder y = 5 (zwei Linien)", "alle Punkte mit y von −1 bis 5 (ein Streifen um g)", "alle Punkte mit y von 2 bis 5 (nur über g)", "alle Punkte mit y von −3 bis 3"], "o": {"index": 1}, "h": "„Höchstens 3“ heißt: 3 oder weniger. Auf beiden Seiten von g.", "w": "Von g aus 3 nach oben (2 + 3 = 5) und 3 nach unten (2 − 3 = −1): der Streifen von y = −1 bis y = 5.", "form": "verfahren_waehlen", "zaehlt": "ja", "r": 586}, {"l": "zwei_kreise", "t": "zwei_kreise", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "auswahl", "f": {"text": "Zwei Kreise haben die Radien 3 cm und 4 cm. Wie weit sind die Mittelpunkte voneinander entfernt, wenn sich die Kreise von außen in genau einem Punkt berühren?"}, "a": ["1 cm (4 − 3)", "7 cm (3 + 4)", "12 cm (3 · 4)", "3,5 cm (der Mittelwert)"], "o": {"index": 1}, "h": "Bei einer Berührung von außen liegen die Kreise nebeneinander. Wie lang ist der Weg von Mittelpunkt zu Mittelpunkt?", "w": "Von M₁ bis zum Berührpunkt sind es 3 cm, von dort bis M₂ weitere 4 cm: 3 + 4 = 7 cm.", "form": "verfahren_waehlen", "zaehlt": "ja", "r": 587}, {"l": "verknuepfen", "t": "verknuepfen", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "auswahl", "f": {"text": "Der Kreis um M(0 | 0) hat den Radius 5. Die senkrechte Linie g geht durch (5 | 0). Wie viele Punkte haben Kreis und g gemeinsam?"}, "a": ["zwei: g geht durch den Kreis hindurch", "keinen: g ist größer als der Radius", "unendlich viele: g und der Kreis liegen übereinander", "genau einen: der Abstand von M zu g ist 5, gleich dem Radius"], "o": {"index": 3}, "h": "Wie weit ist g von M entfernt? Vergleiche mit dem Radius.", "w": "Abstand von M zu g: 5. Radius: 5. Gleich: g berührt den Kreis in genau einem Punkt, (5 | 0).", "form": "verfahren_waehlen", "zaehlt": "ja", "r": 588}, {"l": "verstehen", "t": "verstehen", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "auswahl", "f": {"text": "M und N liegen 9 cm auseinander. Gibt es einen Punkt, der von M genau 3 cm und von N genau 5 cm entfernt ist? Mit welchem Vorgehen prüfst du das?"}, "a": ["Eine Parallele zur Strecke [MN] im Abstand 3 cm zeichnen.", "Die Mittelsenkrechte von [MN] zeichnen.", "Zwei Kreise zeichnen (um M mit r = 3 cm, um N mit r = 5 cm) und nach gemeinsamen Punkten suchen."], "o": {"index": 2}, "h": "Alle Punkte mit gleichem Abstand von einem Punkt liegen auf einer Kreislinie.", "w": "Jede Bedingung gibt einen Kreis: um M mit r = 3 cm und um N mit r = 5 cm. Ein Punkt, der beides erfüllt, muss auf beiden Kreisen liegen. Hier gibt es keinen: 3 cm + 5 cm sind weniger als 9 cm, die Kreise berühren sich nicht.", "form": "verfahren_waehlen", "zaehlt": "ja", "r": 589}, {"l": "verstehen", "t": "verstehen", "p": "uebung", "s": 2, "g": "umkehr", "y": "zahl", "f": {"text": "Alle Punkte, die von einer Geraden g höchstens r cm entfernt sind, bilden einen Streifen. Der Streifen ist 18 cm breit. Wie groß ist r?"}, "o": {"wert": 9, "einheit": "cm"}, "h": "Der Streifen geht von g aus nach beiden Seiten.", "w": "Der Streifen reicht r cm nach links und r cm nach rechts. Seine Breite ist 2 · r. Also ist r = 18 : 2 = 9 cm.", "form": "umkehren", "zaehlt": "ja", "r": 590}, {"l": "verstehen", "t": "verstehen", "p": "uebung", "s": 2, "g": "darstellung", "y": "auswahl", "f": {"text": "Ein Sender erreicht alle Orte, die höchstens 6 km von ihm entfernt sind. Wie sieht dieses Gebiet auf der Karte aus?"}, "a": ["eine Kreislinie mit Radius 6 km", "ein Streifen der Breite 12 km", "eine Kreisfläche mit Radius 6 km", "eine Kreisfläche mit Durchmesser 6 km"], "o": {"index": 2}, "h": "Die Orte, die genau 6 km entfernt sind, bilden die Kreislinie. Was gilt für Orte, die näher am Sender liegen?", "w": "Der Abstand wird vom Sender (einem Punkt) gemessen. Genau 6 km entfernt sind die Punkte auf dem Kreis, „höchstens 6 km“ schließt auch alle näheren Orte im Inneren ein. Das ist eine Kreisfläche mit Radius 6 km.", "form": "bruecke", "zaehlt": "ja", "r": 591}, {"l": "kreislinie", "t": "kreislinie", "p": "uebung", "s": 3, "g": "fehler", "y": "auswahl", "f": {"text": "Gesucht sind alle Punkte auf der x-Achse, die von M(2 | 0) den Abstand 5 haben. Kim rechnet. Zeile 1: Es gibt zwei Punkte: einen rechts von M und einen links von M. Zeile 2: Rechts: x = 5 − 2 = 3. Zeile 3: Links: x = 2 − 5 = −3. In welcher Zeile passiert der erste Fehler?"}, "a": ["In Zeile 1", "In Zeile 2", "In Zeile 3"], "o": {"index": 1}, "h": "Rechts von M: Von welcher Zahl gehst du aus, und in welche Richtung?", "w": "Rechts von M wird x größer: x = 2 + 5 = 7. Links: x = 2 − 5 = −3. Die Punkte sind (7 | 0) und (−3 | 0).", "form": "fehler_detektiv", "zaehlt": "ja", "r": 592}, {"l": "parallelen", "t": "parallelen", "p": "uebung", "s": 3, "g": "fehler", "y": "auswahl", "f": {"text": "g ist die senkrechte Linie durch (5 | 0). Gesucht sind alle Punkte mit dem Abstand 2 von g. Kim rechnet. Zeile 1: Die Punkte liegen auf zwei senkrechten Parallelen zu g. Zeile 2: Die rechte Parallele geht durch x = 5 + 2 = 7. Zeile 3: Die linke Parallele geht durch x = 5 + 2 = 3. In welcher Zeile steckt der Fehler?"}, "a": ["In Zeile 1", "In Zeile 2", "In Zeile 3"], "o": {"index": 2}, "h": "Die linke Parallele liegt links von g. Wird x dort größer oder kleiner?", "w": "Links wird x kleiner: x = 5 − 2 = 3. Kim hat plus statt minus gerechnet.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 593}, {"l": "zwei_kreise", "t": "zwei_kreise", "p": "uebung", "s": 3, "g": "fehler", "y": "auswahl", "f": {"text": "Ein Kreis um A(0 | 0) hat den Radius 2. Ein Kreis um B(10 | 0) hat den Radius 3. Kim prüft, ob sie sich schneiden. Zeile 1: Die Kreise schneiden sich, wenn die beiden Radien zusammen kleiner sind als der Abstand AB. Zeile 2: Der Abstand AB ist 10, die Radien zusammen sind 2 + 3 = 5. Zeile 3: 5 ist kleiner als 10, also schneiden sich die Kreise in 2 Punkten. In welcher Zeile passiert der erste Fehler?"}, "a": ["In Zeile 1", "In Zeile 2", "In Zeile 3"], "o": {"index": 0}, "h": "Müssen die Radien zusammen bis zum anderen Mittelpunkt reichen?", "w": "Die Kreise schneiden sich nur, wenn die Radien zusammen mindestens so groß sind wie der Abstand. 5 reicht nicht bis 10: 0 Schnittpunkte.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 594}, {"l": "verknuepfen", "t": "verknuepfen", "p": "uebung", "s": 3, "g": "fehler", "y": "auswahl", "f": {"text": "Der Kreis um M(3 | 0) hat den Radius 2. Gesucht sind die Schnittpunkte mit der x-Achse (y = 0). Kim rechnet. Zeile 1: Die x-Achse geht durch M. Es gibt also zwei Schnittpunkte. Zeile 2: Der eine liegt 2 Einheiten rechts von M: x = 3 + 2 = 5. Zeile 3: Der andere liegt 2 Einheiten links von M: x = 2 − 3 = −1. In welcher Zeile steckt der Fehler?"}, "a": ["In Zeile 1", "In Zeile 2", "In Zeile 3"], "o": {"index": 2}, "h": "Links von M geht es von 3 aus um 2 nach links.", "w": "Links von M: x = 3 − 2 = 1. Kim hat 2 − 3 gerechnet und die Zahlen vertauscht.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 595}, {"l": "kreislinie", "t": "kreislinie", "p": "uebung", "s": 2, "g": "umkehr", "y": "zahl", "f": {"text": "Ein Rasensprenger bewässert alle Punkte, die höchstens r Meter von ihm entfernt sind. Das bewässerte Gebiet ist an seiner breitesten Stelle 26 m breit. Wie groß ist r?"}, "o": {"wert": 13, "einheit": "m"}, "h": "Die breiteste Stelle des Kreises geht durch den Mittelpunkt.", "w": "Die breiteste Stelle ist der Durchmesser, er ist 2 · r lang. Also ist r = 26 : 2 = 13 m.", "form": "umkehren", "zaehlt": "ja", "r": 597}, {"l": "parallelen", "t": "parallelen", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Die parallelen Geraden g und h sind 14 cm voneinander entfernt. Die Mittelparallele liegt genau dazwischen. Weg A: 14 : 2. Weg B: Beide Abstände sind gleich groß, x + x = 14. Wie weit liegt die Mittelparallele von g?"}, "o": {"wert": 7, "einheit": "cm"}, "h": "Die Mittelparallele hat von g und h denselben Abstand.", "w": "Weg A: 14 : 2 = 7. Weg B: x + x = 14, also 2x = 14 und x = 7. Die Mittelparallele liegt 7 cm von g entfernt, und 7 cm von h.", "form": "zwei_wege", "zaehlt": "ja", "r": 598}, {"l": "sachsituationen", "t": "sachsituationen", "p": "uebung", "s": 2, "g": "umkehr", "y": "zahl", "f": {"text": "Ein Radweg liegt überall 6 m von der Mittellinie einer Straße entfernt. Zwischen Radweg und Straßenrand bleiben 2 m Grünstreifen. Wie breit ist die Straße?"}, "o": {"wert": 8, "einheit": "m"}, "h": "Von der Mittellinie bis zum Straßenrand ist es die halbe Straßenbreite.", "w": "Von der Mittellinie bis zum Radweg sind es 6 m, davon sind 2 m Grünstreifen. Von der Mittellinie bis zum Straßenrand sind es also 6 − 2 = 4 m. Das ist die halbe Straße, die Straße ist 4 · 2 = 8 m breit.", "form": "umkehren", "zaehlt": "ja", "r": 599}, {"l": "verknuepfen", "t": "verknuepfen", "p": "uebung", "s": 2, "g": "darstellung", "y": "auswahl", "f": {"text": "Die Punkte A und B sind 6 cm voneinander entfernt. Gesucht sind alle Punkte, die von A und von B gleich weit entfernt sind und zugleich genau 5 cm von A entfernt sind. Wie viele solche Punkte gibt es?"}, "a": ["keinen", "genau einen", "genau zwei", "unendlich viele"], "o": {"index": 2}, "h": "Die Punkte gleich weit von A und B liegen auf der Mittelsenkrechten. Wie weit ist sie von A entfernt?", "w": "Die Mittelsenkrechte schneidet AB in der Mitte, 3 cm von A. Der Kreis um A mit Radius 5 cm reicht über die Mittelsenkrechte hinaus (5 > 3) und schneidet sie deshalb zweimal, einmal auf jeder Seite von AB.", "form": "bruecke", "zaehlt": "ja", "r": 600}, {"l": "zwei_kreise", "t": "zwei_kreise", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Die Punkte A und B sind 10 cm voneinander entfernt. Um A liegt eine Kreislinie mit Radius 4 cm, um B eine Kreislinie mit Radius 6 cm. Weg A: Die Summe der beiden Radien mit dem Abstand AB vergleichen. Weg B: Auf der Strecke AB von A aus 4 cm abtragen und schauen, wie weit es noch bis B ist. Wie viele Punkte haben die beiden Kreislinien gemeinsam?"}, "o": {"wert": 1}, "h": "Wenn die Radien zusammen genau so lang sind wie der Abstand, berühren sich die Kreise.", "w": "Weg A: 4 + 6 = 10, das ist genau der Abstand AB. Weg B: 4 cm von A aus, es bleiben 10 − 4 = 6 cm bis B, das ist genau der Radius um B. Die Kreise berühren sich in einem Punkt.", "form": "zwei_wege", "zaehlt": "ja", "r": 601}]$auf$::jsonb),
    (49, 'geometrie.winkel', 559, 14, $auf$[{"l": "um_punkt", "t": "um_punkt", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Um einen Punkt liegen drei Winkel: 100°, 140° und ein dritter. Alle zusammen ergeben ①°. Die ersten beiden zusammen haben 100° + 140° = ②°. Der dritte Winkel hat ① − ② = ③°.", "schablone": "① = □; ② = □; ③ = □", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ)."}, "o": {"werte": [360, 240, 120]}, "h": "Um einen Punkt herum ist ein voller Winkel.", "w": "360° − 240° = 120°.", "form": "lueckenweg", "zaehlt": "nein", "r": 580}, {"l": "uhr", "t": "uhr", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Der Minutenzeiger dreht sich in 60 Minuten um 360°. In 1 Minute dreht er sich um 360° : 60 = ①°. In 15 Minuten dreht er sich um 15 · ① = ②°.", "schablone": "① = □; ② = □", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ)."}, "o": {"werte": [6, 90]}, "h": "Eine Viertelstunde ist ein Viertel einer ganzen Drehung.", "w": "360° : 60 = 6°. 15 · 6° = 90°.", "form": "lueckenweg", "zaehlt": "nein", "r": 581}, {"l": "drehungen", "t": "drehungen", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Du drehst dich im Uhrzeigersinn um 270°. Eine ganze Drehung hat 360°. Eine Vierteldrehung ist ein Viertel von 360°, das sind ①°. 270° sind 270 : ① = ② Vierteldrehungen. Eine ganze Drehung sind 360 : ① = ③ Vierteldrehungen.", "schablone": "① = □; ② = □; ③ = □", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ)."}, "o": {"werte": [90, 3, 4]}, "h": "Eine ganze Drehung hat 360°.", "w": "360 : 4 = 90. 270 : 90 = 3. 360 : 90 = 4.", "form": "lueckenweg", "zaehlt": "nein", "r": 582}, {"l": "figuren", "t": "figuren", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Die Diagonale eines Rechtecks teilt eine Ecke in zwei Teile. Ein Teil hat 32°. Jede Ecke des Rechtecks hat ①°. Der andere Teil hat ① − 32 = ②°.", "schablone": "① = □; ② = □", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ)."}, "o": {"werte": [90, 58]}, "h": "Jede Ecke eines Rechtecks ist ein rechter Winkel.", "w": "90° − 32° = 58°.", "form": "lueckenweg", "zaehlt": "nein", "r": 583}, {"l": "verstehen", "t": "verstehen", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Kim sagt: „Zwei Winkel, die zusammen 180° ergeben, sind immer gleich groß.“ Gegenbeispiel: Ein Winkel hat 70°. Der andere hat 180° − 70° = ①°. Der Unterschied der beiden Winkel ist ① − 70° = ②°. Weil ② nicht 0 ist, sind sie nicht gleich groß. Also ist die Behauptung falsch.", "schablone": "① = □; ② = □", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ)."}, "o": {"werte": [110, 40]}, "h": "Ein einziges Beispiel genügt, um „immer“ zu widerlegen.", "w": "180 − 70 = 110. 110 − 70 = 40. Die Winkel sind verschieden, die Behauptung ist widerlegt. Ein einziges Gegenbeispiel genügt.", "form": "lueckenweg", "zaehlt": "nein", "r": 584}, {"l": "uhr", "t": "uhr", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "auswahl", "f": {"text": "Der Stundenzeiger läuft 2 Stunden. Um wie viel Grad dreht er sich? Welche Rechnung stimmt?"}, "a": ["In 1 Minute dreht er sich um 6°. Zwei Stunden: 2 · 6° = 12°", "In 1 Stunde dreht er sich um 360°. Zwei Stunden: 2 · 360° = 720°", "In 12 Stunden dreht er sich um 360°, also in 1 Stunde um 30°. Zwei Stunden: 2 · 30° = 60°", "Zwei Stunden sind die Hälfte: 360° : 2 = 180°"], "o": {"index": 2}, "h": "Wie lange braucht der Stundenzeiger für eine ganze Drehung?", "w": "Eine ganze Drehung dauert 12 Stunden. 360° : 12 = 30° je Stunde. 2 · 30° = 60°.", "form": "verfahren_waehlen", "zaehlt": "ja", "r": 585}, {"l": "figuren", "t": "figuren", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "auswahl", "f": {"text": "Eine Ecke eines Rechtecks wird durch zwei Linien in drei Teile geteilt. Zwei Teile haben 25° und 30°. Wie berechnest du den dritten Teil?"}, "a": ["180° − 25° − 30° = 125°", "25° + 30° = 55°", "90° − 25° − 30° = 35°", "90° − 25° = 65°"], "o": {"index": 2}, "h": "Die drei Teile ergeben zusammen eine Ecke des Rechtecks.", "w": "Ecke 90°. 90° − 25° = 65°. 65° − 30° = 35°.", "form": "verfahren_waehlen", "zaehlt": "ja", "r": 586}, {"l": "ergaenzen", "t": "ergaenzen", "p": "uebung", "s": 3, "g": "fehler", "y": "auswahl", "f": {"text": "Neben einem Winkel von 65° liegt an einer Geraden ein zweiter Winkel. Kim berechnet ihn. Zeile 1: Beide zusammen ergeben einen gestreckten Winkel. Zeile 2: Ein gestreckter Winkel hat 90°. Zeile 3: Der zweite Winkel hat 90° − 65° = 25°. In welcher Zeile passiert der erste Fehler?"}, "a": ["In Zeile 1", "In Zeile 2", "In Zeile 3"], "o": {"index": 1}, "h": "Wie viel Grad hat eine gerade Linie als Winkel?", "w": "Ein gestreckter Winkel hat 180°. Der zweite Winkel hat 180° − 65° = 115°.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 587}, {"l": "kreuzung", "t": "kreuzung", "p": "uebung", "s": 3, "g": "fehler", "y": "auswahl", "f": {"text": "Zwei Geraden schneiden sich. Ein Winkel hat 50°. Kim berechnet die anderen. Zeile 1: Der gegenüberliegende Winkel hat 180° − 50° = 130°. Zeile 2: Die beiden Nachbarwinkel dieses Winkels haben je 180° − 130° = 50°. Zeile 3: Alle vier Winkel zusammen: 50° + 130° + 50° + 50° = 280°. In welcher Zeile passiert der erste Fehler?"}, "a": ["In Zeile 1", "In Zeile 2", "In Zeile 3"], "o": {"index": 0}, "h": "Welche Winkel sind bei sich schneidenden Geraden gleich groß: gegenüberliegende oder benachbarte?", "w": "Gegenüberliegende Winkel (Scheitelwinkel) sind gleich groß: Der gegenüberliegende Winkel hat auch 50°. Die Nachbarwinkel haben 180° − 50° = 130°. Die Zeilen 2 und 3 folgen aus dem Fehler in Zeile 1.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 588}, {"l": "um_punkt", "t": "um_punkt", "p": "uebung", "s": 3, "g": "fehler", "y": "auswahl", "f": {"text": "Um einen Punkt liegen vier gleich große Winkel. Kim berechnet einen von ihnen. Zeile 1: Alle Winkel um einen Punkt ergeben 360°. Zeile 2: Jeder der vier Winkel hat 360° : 4 = 80°. Zeile 3: Ein Winkel hat also 80°. In welcher Zeile passiert der erste Fehler?"}, "a": ["In Zeile 1", "In Zeile 2", "In Zeile 3"], "o": {"index": 1}, "h": "Rechne 4 · 80° als Probe.", "w": "360° : 4 = 90°. Probe: 4 · 90° = 360°.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 589}, {"l": "drehungen", "t": "drehungen", "p": "uebung", "s": 3, "g": "fehler", "y": "auswahl", "f": {"text": "Du schaust nach Osten und drehst dich um 90° im Uhrzeigersinn. Kim sagt, wohin du dann schaust. Zeile 1: 90° sind eine Vierteldrehung. Zeile 2: Im Uhrzeigersinn geht es von Osten nach Süden. Zeile 3: Du schaust danach nach Norden. In welcher Zeile steckt der Fehler?"}, "a": ["In Zeile 1", "In Zeile 2", "In Zeile 3"], "o": {"index": 2}, "h": "Zwischen zwei Himmelsrichtungen, die direkt nebeneinander liegen, sind 90°. Welche kommt nach Osten?", "w": "Von Osten aus ist im Uhrzeigersinn Süden die nächste Himmelsrichtung. Du schaust nach Süden.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 590}, {"l": "figuren", "t": "figuren", "p": "uebung", "s": 3, "g": "fehler", "y": "auswahl", "f": {"text": "In einem Quadrat teilen zwei Linien aus einer Ecke den rechten Winkel in drei gleich große Teile. Kim berechnet zwei der Teile zusammen. Zeile 1: Ein Quadrat hat in jeder Ecke 180°. Zeile 2: Jeder der drei Teile hat 180° : 3 = 60°. Zeile 3: Zwei der Teile zusammen haben 60° + 60° = 120°. In welcher Zeile passiert der erste Fehler?"}, "a": ["In Zeile 1", "In Zeile 2", "In Zeile 3"], "o": {"index": 0}, "h": "Wie groß ist ein rechter Winkel?", "w": "Ein Quadrat hat in jeder Ecke 90°. Ein Teil hat 90° : 3 = 30°, zwei Teile haben zusammen 60°.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 591}, {"l": "ergaenzen", "t": "ergaenzen", "p": "uebung", "s": 3, "g": "rueckwaerts", "y": "zahl", "f": {"text": "Zwei Nebenwinkel unterscheiden sich um 40°. Wie groß ist der kleinere der beiden Winkel?"}, "o": {"wert": 70, "einheit": "°"}, "h": "Nebenwinkel ergeben zusammen 180°. Überlege, wie die beiden Winkel um 40° auseinanderliegen.", "w": "Der größere Winkel ist 40° größer als der kleinere. Nimmt man die 40° weg, bleiben 180° − 40° = 140° für zwei gleich große Winkel, jeder ist 70°. Der kleinere Winkel ist 70°, der größere 110°. Probe: 70° + 110° = 180° und 110° − 70° = 40°.", "form": "umkehren", "zaehlt": "ja", "r": 592}, {"l": "verstehen", "t": "verstehen", "p": "uebung", "s": 1, "g": "erkennen", "y": "auswahl", "f": {"text": "Ein überstumpfer Winkel ist größer als ein gestreckter Winkel und kleiner als ein Vollwinkel. Welche Größe kann ein überstumpfer Winkel haben?"}, "a": ["45°", "120°", "180°", "250°"], "o": {"index": 3}, "h": "Ein gestreckter Winkel hat 180°, ein Vollwinkel 360°.", "w": "Überstumpf heißt: mehr als 180° und weniger als 360°. Nur 250° liegt in diesem Bereich. 45° ist spitz, 120° stumpf, 180° gestreckt.", "form": "bruecke", "zaehlt": "ja", "r": 593}]$auf$::jsonb),
    (50, 'groessen.einheiten', 648, 17, $auf$[{"l": "schaetzen", "t": "schaetzen", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Eine Tür ist etwa 2 m hoch. Eine Schokoladentafel wiegt etwa 100 g. 10 Tafeln wiegen ① g. Das sind ② kg.", "schablone": "① = □; ② = □", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ)."}, "o": {"werte": [1000, 1]}, "h": "Erst das Gesamtgewicht in g, dann in kg umrechnen.", "w": "10 · 100 g = 1 000 g = 1 kg.", "form": "lueckenweg", "zaehlt": "nein", "r": 668}, {"l": "masse", "t": "masse", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "2 kg 350 g sind 2 · 1 000 g + 350 g = ① g. Zusammen mit 4 500 g wiegen sie ① g + 4 500 g = ② g. Das sind ③ kg und ④ g.", "schablone": "① = □; ② = □; ③ = □; ④ = □", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ)."}, "o": {"werte": [2350, 6850, 6, 850]}, "h": "1 kg sind 1 000 g.", "w": "2 000 + 350 = 2 350 g. 2 350 + 4 500 = 6 850 g. Das sind 6 kg und 850 g.", "form": "lueckenweg", "zaehlt": "nein", "r": 669}, {"l": "kommaschreibweise", "t": "kommaschreibweise", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Hinter dem Komma bekommt jede kleinere Einheit ihre Stellen. 2,35 m sind 2 m 35 cm. Das sind insgesamt ① cm. 7,04 m sind 7 m und ② cm, also insgesamt ③ cm. Beide Längen zusammen sind ① cm + ③ cm = ④ cm.", "schablone": "① = □; ② = □; ③ = □; ④ = □", "hinweis": "Je Lücke eine ganze Zahl."}, "o": {"werte": [235, 4, 704, 939]}, "h": "Bei m und cm sind es zwei Stellen hinter dem Komma.", "w": "2,35 m = 235 cm. 7,04 m = 7 m 4 cm = 704 cm. Zusammen 235 + 704 = 939 cm.", "form": "lueckenweg", "zaehlt": "nein", "r": 670}, {"l": "rechnen", "t": "rechnen", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Ein Seil ist 3 m 20 cm lang, ein zweites 85 cm. In cm: 3 m 20 cm = ① cm. Zusammen sind die Seile ① cm + 85 cm = ② cm lang.", "schablone": "① = □; ② = □", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ)."}, "o": {"werte": [320, 405]}, "h": "Beide Längen in dieselbe Einheit bringen.", "w": "3 m 20 cm = 320 cm. 320 cm + 85 cm = 405 cm.", "form": "lueckenweg", "zaehlt": "nein", "r": 671}, {"l": "massstab", "t": "massstab", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Eine Karte hat den Maßstab 1 : 50 000. Auf der Karte sind es 4 cm. In Wirklichkeit sind es 4 · 50 000 = ① cm. Das sind ② m und ③ km.", "schablone": "① = □; ② = □; ③ = □", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ)."}, "o": {"werte": [200000, 2000, 2]}, "h": "100 cm sind 1 m. 1 000 m sind 1 km.", "w": "4 · 50 000 = 200 000 cm = 2 000 m = 2 km.", "form": "lueckenweg", "zaehlt": "nein", "r": 672}, {"l": "verstehen", "t": "verstehen", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Ein Schulbus ist etwa 12 m lang. Das sind ① cm. Stehen 5 solche Busse hintereinander, sind sie 5 · ① = ② cm lang. Das sind ③ m.", "schablone": "① = □; ② = □; ③ = □", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ)."}, "o": {"werte": [1200, 6000, 60]}, "h": "1 m sind 100 cm.", "w": "12 m = 1 200 cm. 5 · 1 200 = 6 000 cm = 60 m.", "form": "lueckenweg", "zaehlt": "nein", "r": 673}, {"l": "masse", "t": "masse", "p": "uebung", "s": 2, "g": "einkleidung", "y": "auswahl", "f": {"text": "Ein Paket wiegt 2 kg 400 g. Drei solche Pakete werden verschickt. Wie rechnest du das Gesamtgewicht richtig?"}, "a": ["2 kg · 3 + 400 g = 6 kg 400 g", "2 kg 400 g + 3 = 2 kg 403 g", "2 400 · 3 = 7 200 kg", "Alles in g umrechnen: 2 400 g · 3 = 7 200 g, das sind 7 kg 200 g"], "o": {"index": 3}, "h": "Rechne beide Teile des Pakets mit dem Faktor 3.", "w": "2 400 g · 3 = 7 200 g = 7 kg 200 g.", "form": "verfahren_waehlen", "zaehlt": "ja", "r": 674}, {"l": "zeit", "t": "zeit", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "auswahl", "f": {"text": "Ein Zug fährt um 9:50 Uhr ab und kommt um 12:20 Uhr an. Wie rechnest du die Fahrzeit richtig?"}, "a": ["Bis zur vollen Stunde: 10 min bis 10:00, 2 h bis 12:00, 20 min bis 12:20. Das sind 2 h 30 min", "12 − 9 = 3 h und 50 − 20 = 30 min. Das sind 3 h 30 min", "12,20 − 9,50 = 2,70. Das sind 2 h 70 min", "12:20 − 10:00 = 2 h 20 min"], "o": {"index": 0}, "h": "Gehe erst bis zur vollen Stunde, dann weiter.", "w": "10 min + 2 h + 20 min = 2 h 30 min. Probe: 9:50 + 2 h 30 min = 12:20.", "form": "verfahren_waehlen", "zaehlt": "ja", "r": 675}, {"l": "massstab", "t": "massstab", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "auswahl", "f": {"text": "Auf einer Karte 1 : 25 000 sind zwei Orte 6 cm voneinander entfernt. Wie weit sind sie in Wirklichkeit entfernt?"}, "a": ["6 · 25 000 = 150 000 m, also 150 km", "6 · 25 = 150 m", "6 · 25 000 cm = 150 000 cm = 1 500 m, also 1,5 km", "25 000 : 6 ≈ 4 167 cm"], "o": {"index": 2}, "h": "Wirklichkeit = Kartenlänge mal Maßstabszahl. Die Einheit bleibt zunächst cm.", "w": "6 cm · 25 000 = 150 000 cm. 100 cm = 1 m: 1 500 m. 1 000 m = 1 km: 1,5 km.", "form": "verfahren_waehlen", "zaehlt": "ja", "r": 676}, {"l": "verstehen", "t": "verstehen", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "auswahl", "f": {"text": "Kim sagt: „Ein Buch wiegt 500 kg.“ Wie prüfst du das?"}, "a": ["Eine Schokoladentafel wiegt 100 g. 500 kg sind etwa 5 Tafeln. Das passt zu einem Buch", "500 kg sind 500 000 g. Das ist nur eine große Zahl, also passt es", "Ein Mensch wiegt etwa 50 kg. 500 kg wären zehn Menschen. Das passt nicht zu einem Buch", "Ein Buch hat Seiten und kg ist eine Einheit für Gewicht, also passt es"], "o": {"index": 2}, "h": "Vergleiche mit etwas, dessen Gewicht du kennst.", "w": "500 : 50 = 10: Das wären zehn Menschen. Ein Buch wiegt eher 500 g. Die Einheit war falsch.", "form": "verfahren_waehlen", "zaehlt": "ja", "r": 677}, {"l": "schaetzen", "t": "schaetzen", "p": "uebung", "s": 3, "g": "fehler", "y": "auswahl", "f": {"text": "Kim soll schätzen, wie hoch sein Klassenzimmer ist. Zeile 1: Bezugsgröße: Eine Tür ist etwa 2 m hoch. Zeile 2: Das Zimmer ist etwa so hoch wie zwei Türen übereinander. Zeile 3: Es ist also etwa 2 · 2 = 4 cm hoch. In welcher Zeile steckt der Fehler?"}, "a": ["In Zeile 1", "In Zeile 2", "In Zeile 3"], "o": {"index": 2}, "h": "Eine Tür ist 2 m hoch. In welcher Einheit rechnest du weiter?", "w": "2 · 2 m = 4 m. Bei einer Größe gehört immer die richtige Einheit zur Zahl.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 678}, {"l": "laenge", "t": "laenge", "p": "uebung", "s": 3, "g": "fehler", "y": "auswahl", "f": {"text": "Kim rechnet 3 km 40 m in Meter um. Zeile 1: 1 km = 100 m. Zeile 2: 3 km = 300 m. Zeile 3: 300 m + 40 m = 340 m. In welcher Zeile passiert der erste Fehler?"}, "a": ["In Zeile 1", "In Zeile 2", "In Zeile 3"], "o": {"index": 0}, "h": "Wie viele Meter sind ein Kilometer?", "w": "1 km = 1 000 m, also 3 km = 3 000 m. Dazu 40 m: 3 040 m. Die Zeilen 2 und 3 folgen richtig aus der falschen Zeile 1.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 679}, {"l": "masse", "t": "masse", "p": "uebung", "s": 3, "g": "fehler", "y": "auswahl", "f": {"text": "Kim rechnet 7,5 kg in Gramm um. Zeile 1: 1 kg = 1 000 g. Zeile 2: 7,5 · 1 000 g = 750 g. Zeile 3: 7,5 kg sind also 750 g. In welcher Zeile passiert der erste Fehler?"}, "a": ["In Zeile 1", "In Zeile 2", "In Zeile 3"], "o": {"index": 1}, "h": "Das Komma wandert beim Malnehmen mit 1 000 um drei Stellen. In welche Richtung?", "w": "7,5 · 1 000 = 7 500. 7,5 kg sind 7 500 g. Zeile 3 folgt richtig aus der falschen Zeile 2.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 680}, {"l": "zeit", "t": "zeit", "p": "uebung", "s": 3, "g": "fehler", "y": "auswahl", "f": {"text": "Ein Film beginnt um 17:45 Uhr und dauert 2 h 30 min. Kim berechnet das Ende. Zeile 1: 17:45 Uhr plus 15 min ist 18:00 Uhr. Zeile 2: Dann bleiben noch 2 h 30 min − 15 min = 2 h 25 min. Zeile 3: 18:00 Uhr plus 2 h 25 min ist 20:25 Uhr. In welcher Zeile passiert der erste Fehler?"}, "a": ["In Zeile 1", "In Zeile 2", "In Zeile 3"], "o": {"index": 1}, "h": "Rechne 30 min − 15 min noch einmal nach.", "w": "30 min − 15 min = 15 min. Es bleiben 2 h 15 min, der Film endet um 20:15 Uhr.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 681}, {"l": "verstehen", "t": "verstehen", "p": "uebung", "s": 3, "g": "fehler", "y": "auswahl", "f": {"text": "Kim behauptet: „Ein Bleistift ist 19 m lang.“ Er prüft die Angabe. Zeile 1: Eine Tür ist etwa 2 m hoch. Zeile 2: 19 m sind fast zehn Türen übereinander. Zeile 3: Das passt zu einem Bleistift. In welcher Zeile steckt der Fehler?"}, "a": ["In Zeile 1", "In Zeile 2", "In Zeile 3"], "o": {"index": 2}, "h": "Passt ein Bleistift neben eine Tür, die so hoch ist wie zehn Türen?", "w": "Ein Bleistift ist etwa 19 cm lang, nicht 19 m. Die Einheit war falsch.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 682}, {"l": "schaetzen", "t": "schaetzen", "p": "uebung", "s": 2, "g": "darstellung", "y": "auswahl", "f": {"text": "Ein neuer Bleistift ist etwa 18 lang. Welche Einheit passt?"}, "a": ["18 mm", "18 cm", "18 dm", "18 m"], "o": {"index": 1}, "h": "Vergleiche mit einem Schullineal von 30 cm Länge.", "w": "Ein Bleistift ist kürzer als ein Schullineal (30 cm) und länger als ein Streichholz (etwa 5 cm): 18 cm. 18 mm wären kürzer als ein Streichholz, 18 dm sind 180 cm, so groß wie ein Erwachsener, und 18 m sind etwa vier Autos hintereinander.", "form": "bruecke", "zaehlt": "ja", "r": 683}, {"l": "verstehen", "t": "verstehen", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Wie viele Meter sind 3,4 km? Weg A: 3,4 · 1000. Weg B: 3 km in Meter umrechnen und 0,4 km in Meter umrechnen, dann addieren."}, "o": {"wert": 3400, "einheit": "m"}, "h": "Ein Kilometer hat 1000 Meter.", "w": "Weg A: 3,4 · 1000 = 3400. Weg B: 3 km = 3000 m und 0,4 km = 400 m, zusammen 3400 m. Also sind 3,4 km gleich 3400 m.", "form": "zwei_wege", "zaehlt": "ja", "r": 684}]$auf$::jsonb),
    (51, 'messen.flaechen', 588, 12, $auf$[{"l": "rechteck", "t": "rechteck", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Ein Rechteck ist 9 m lang und 5 m breit. Die Fläche ist 9 · 5 = ① m². Der Umfang ist 2 · 9 + 2 · 5 = ② m. Ein Quadrat mit demselben Umfang hat die Seitenlänge ② : 4 = ③ m.", "schablone": "① = □; ② = □; ③ = □", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ)."}, "o": {"werte": [45, 28, 7]}, "h": "Fläche: Länge mal Breite. Umfang: alle Seiten zusammen.", "w": "9 · 5 = 45 m². 18 + 10 = 28 m. 28 : 4 = 7 m.", "form": "lueckenweg", "zaehlt": "nein", "r": 609}, {"l": "zerlegen", "t": "zerlegen", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Eine L-förmige Fläche wird in zwei Rechtecke zerlegt: eines ist 6 m mal 3 m, das andere 2 m mal 4 m. Die Flächen sind 6 · 3 = ① m² und 2 · 4 = ② m². Zusammen sind es ③ m².", "schablone": "① = □; ② = □; ③ = □", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ)."}, "o": {"werte": [18, 8, 26]}, "h": "Rechne beide Rechtecke einzeln und addiere.", "w": "18 m² + 8 m² = 26 m².", "form": "lueckenweg", "zaehlt": "nein", "r": 610}, {"l": "sachaufgaben", "t": "sachaufgaben", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Ein Zimmer ist 5 m lang und 4 m breit. Der Boden wird mit Fliesen belegt. Das ist eine Fläche: 5 · 4 = ① m². Für die Leiste an der Wand brauchst du den Umfang: 2 · 5 + 2 · 4 = ② m. Die Tür ist 1 m breit, dort kommt keine Leiste hin. Du brauchst also ② − 1 = ③ m Leiste.", "schablone": "① = □; ② = □; ③ = □", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ)."}, "o": {"werte": [20, 18, 17]}, "h": "Boden: Fläche. Wand: Umfang.", "w": "5 · 4 = 20 m². 10 + 8 = 18 m. 18 − 1 = 17 m Leiste.", "form": "lueckenweg", "zaehlt": "nein", "r": 611}, {"l": "verstehen", "t": "verstehen", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Ein Rechteck ist 5 cm lang und 2 cm breit. Seine Fläche ist ① cm². Verdoppelt man Länge und Breite, ist die neue Fläche (2 · 5) · (2 · 2) = ② cm². Die neue Fläche ist ② : ① = ③-mal so groß wie die alte.", "schablone": "① = □; ② = □; ③ = □", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ)."}, "o": {"werte": [10, 40, 4]}, "h": "Verdopple beide Seiten, nicht nur eine.", "w": "Alt: 10 cm². Neu: 10 · 4 = 40 cm². 40 : 10 = 4.", "form": "lueckenweg", "zaehlt": "nein", "r": 612}, {"l": "kommaschreibweise", "t": "kommaschreibweise", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Wie viele dm² sind 4,25 m²? Weg A: 4 m² sind 400 dm², dazu kommen 25 dm². Weg B: 4,25 mal 100 rechnen."}, "o": {"wert": 425, "einheit": "dm²"}, "h": "Beide Wege müssen dieselbe Zahl ergeben.", "w": "Weg A: 400 + 25 = 425. Weg B: 4,25 · 100 = 425. 1 m² sind 100 dm².", "form": "zwei_wege", "zaehlt": "ja", "r": 613}, {"l": "rechteck", "t": "rechteck", "p": "uebung", "s": 2, "g": "einkleidung", "y": "auswahl", "f": {"text": "Ein Garten ist 12 m lang und 8 m breit. Du willst wissen, wie viel Zaun du um den ganzen Garten brauchst. Welche Rechnung passt?"}, "a": ["2 · 12 + 2 · 8 = 40 m (Umfang)", "12 · 8 = 96 m (Fläche)", "12 + 8 = 20 m", "12 + 8 + 12 = 32 m"], "o": {"index": 0}, "h": "Der Zaun läuft einmal um den ganzen Garten herum.", "w": "Der Zaun geht um alle vier Seiten: 12 + 8 + 12 + 8 = 40 m.", "form": "verfahren_waehlen", "zaehlt": "ja", "r": 614}, {"l": "einheitsquadrate", "t": "einheitsquadrate", "p": "uebung", "s": 2, "g": "umkehr", "y": "zahl", "f": {"text": "Ein Rechteck wird mit Quadraten von 1 cm² ausgelegt. In jede Reihe passen 6 Quadrate. Insgesamt sind es 42 Quadrate. Wie viele Reihen sind es?"}, "o": {"wert": 7}, "h": "Reihen mal Quadrate je Reihe gibt alle Quadrate. Was rechnest du rückwärts?", "w": "Reihen · 6 = 42. Also sind es 42 : 6 = 7 Reihen.", "form": "umkehren", "zaehlt": "ja", "r": 615}, {"l": "rechteck", "t": "rechteck", "p": "uebung", "s": 3, "g": "fehler", "y": "auswahl", "f": {"text": "Ein Rechteck hat die Fläche 60 cm² und ist 12 cm lang. Kim berechnet die Breite. Zeile 1: Es gilt A = a · b, also 60 = 12 · b. Zeile 2: Dann ist b = 12 · 60 = 720. Zeile 3: Die Breite ist 720 cm. In welcher Zeile passiert der erste Fehler?"}, "a": ["In Zeile 1", "In Zeile 2", "In Zeile 3"], "o": {"index": 1}, "h": "Aus A = a · b folgt b = A : a. Wann musst du teilen?", "w": "Die Breite ist die Fläche geteilt durch die Länge: b = 60 : 12 = 5 cm.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 616}, {"l": "einheiten", "t": "einheiten", "p": "uebung", "s": 3, "g": "fehler", "y": "auswahl", "f": {"text": "Kim rechnet 4 m² in dm² um. Zeile 1: Bei Flächen ist die Umrechnungszahl 100. Zeile 2: 1 m² = 100 dm². Zeile 3: 4 m² = 4 · 10 = 40 dm². In welcher Zeile steckt der Fehler?"}, "a": ["In Zeile 1", "In Zeile 2", "In Zeile 3"], "o": {"index": 2}, "h": "Welche Zahl hast du in Zeile 1 und 2 für die Umrechnung genannt?", "w": "Die Umrechnungszahl ist 100: 4 · 100 = 400 dm².", "form": "fehler_detektiv", "zaehlt": "ja", "r": 617}, {"l": "sachaufgaben", "t": "sachaufgaben", "p": "uebung", "s": 3, "g": "fehler", "y": "auswahl", "f": {"text": "Ein Beet ist 3 m lang und 2 m breit. Kim will einen Zaun um das ganze Beet kaufen. Zeile 1: Der Zaun läuft am Rand, also brauche ich den Umfang. Zeile 2: Umfang: 3 · 2 = 6. Zeile 3: Ich brauche 6 m Zaun. In welcher Zeile passiert der erste Fehler?"}, "a": ["In Zeile 1", "In Zeile 2", "In Zeile 3"], "o": {"index": 1}, "h": "Der Umfang ist die Summe aller vier Seiten.", "w": "Umfang: 3 + 2 + 3 + 2 = 10 m. 3 · 2 = 6 wäre die Fläche in m².", "form": "fehler_detektiv", "zaehlt": "ja", "r": 618}, {"l": "einheiten", "t": "einheiten", "p": "uebung", "s": 3, "g": "rueckwaerts", "y": "zahl", "f": {"text": "Ein Rechteck ist 2 m lang und hat die Fläche 6 m². Wie breit ist es in Zentimetern?"}, "o": {"wert": 300, "einheit": "cm"}, "h": "Berechne die Breite zuerst in Metern und wechsle dann die Einheit.", "w": "Fläche = Länge · Breite, also Breite = 6 : 2 = 3 m. 3 m sind 300 cm. Probe: 2 m · 3 m = 6 m².", "form": "umkehren", "zaehlt": "ja", "r": 619}, {"l": "sachaufgaben", "t": "sachaufgaben", "p": "uebung", "s": 2, "g": "umkehr", "y": "zahl", "f": {"text": "Für den Anstrich einer Wand stehen 2 Eimer Farbe bereit, jeder Eimer deckt 10 m². Die Wand ist 5 m breit. Wie hoch darf sie höchstens sein, damit die Farbe genau reicht?"}, "o": {"wert": 4, "einheit": "m"}, "h": "Berechne zuerst, wie viele Quadratmeter die Farbe deckt.", "w": "Die Farbe deckt 2 · 10 = 20 m². Fläche = Breite · Höhe, also Höhe = 20 : 5 = 4 m. Probe: 5 m · 4 m = 20 m².", "form": "umkehren", "zaehlt": "ja", "r": 620}]$auf$::jsonb),
    (54, 'abbildungen.kongruenz', 686, 14, $auf$[{"l": "mittelsenkrechte", "t": "mittelsenkrechte", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "A(2 | 3) und B(10 | 3) liegen auf einer waagrechten Linie. Die Mitte von [AB] hat die x-Koordinate (2 + 10) : 2 = ①. Die Mittelsenkrechte ist die senkrechte Linie durch diese Stelle. Sie hat von A den Abstand ① − 2 = ②.", "schablone": "① = □; ② = □", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ)."}, "o": {"werte": [6, 4]}, "h": "Die Mitte liegt genau zwischen den beiden x-Werten.", "w": "(2 + 10) : 2 = 6. Abstand zu A: 6 − 2 = 4.", "form": "lueckenweg", "zaehlt": "nein", "r": 699}, {"l": "winkelhalbierende", "t": "winkelhalbierende", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Ein Winkel hat 70°. Die Winkelhalbierende teilt ihn in zwei Winkel von je 70° : 2 = ①°. Ein Dreieck hat bei A diesen Teilwinkel und bei B den Winkel 90°. Dann hat der dritte Winkel 180° − ①° − 90° = ②°. Die Winkelhalbierende des 90°-Winkels teilt ihn in zwei Winkel von je ③°. Der dritte Winkel ist ② − ③ = ④° größer als eine dieser Hälften.", "schablone": "① = □; ② = □; ③ = □; ④ = □", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ)."}, "o": {"werte": [35, 55, 45, 10]}, "h": "Halbieren heißt durch 2 teilen. Im Dreieck sind es zusammen 180°.", "w": "70 : 2 = 35. 180 − 35 − 90 = 55. 90 : 2 = 45. 55 − 45 = 10.", "form": "lueckenweg", "zaehlt": "nein", "r": 700}, {"l": "symmetrie", "t": "symmetrie", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Ein regelmäßiges Sechseck hat so viele Ecken wie Seiten. Eine Symmetrieachse geht entweder durch zwei gegenüberliegende Ecken oder durch die Mitten zweier gegenüberliegender Seiten. Die Zahl der Eckenpaare, durch die eine Achse geht, ist ①. Die Zahl der Seitenpaare ist ②. Zusammen gibt es ③ Symmetrieachsen.", "schablone": "① = □; ② = □; ③ = □", "hinweis": "Je Lücke eine ganze Zahl."}, "o": {"werte": [3, 3, 6]}, "h": "Ein Paar besteht aus einer Ecke (oder Seite) und der gegenüberliegenden.", "w": "Das Sechseck hat 6 Ecken, das sind 3 gegenüberliegende Eckenpaare, und 6 Seiten, das sind 3 gegenüberliegende Seitenpaare. 3 + 3 = 6 Achsen.", "form": "lueckenweg", "zaehlt": "nein", "r": 701}, {"l": "vierecke_ordnen", "t": "vierecke_ordnen", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Im Haus der Vierecke ist jedes Parallelogramm auch ein Trapez. Zahl der parallelen Seitenpaare beim Trapez: mindestens ①. Zahl der parallelen Seitenpaare beim Parallelogramm: ②. Das Parallelogramm hat also ② − ① = ③ mehr als das Trapez mindestens hat. Alle Seiten des Parallelogramms liegen in parallelen Paaren: Jedes Paar besteht aus einer Seite und ihrer Gegenseite, also sind es ② + ② = ④ Seiten.", "schablone": "① = □; ② = □; ③ = □; ④ = □", "hinweis": "Je Lücke eine ganze Zahl."}, "o": {"werte": [1, 2, 1, 4]}, "h": "Zeichne die Vierecke und markiere gegenüberliegende parallele Seiten.", "w": "Trapez: mindestens 1 paralleles Paar. Parallelogramm: 2 parallele Paare. Unterschied 2 − 1 = 1. Zwei Paare mit je 2 Seiten sind 4 Seiten.", "form": "lueckenweg", "zaehlt": "nein", "r": 702}, {"l": "eigenschaften", "t": "eigenschaften", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Ein Dreieck hat die Seiten 7 cm, 9 cm und 11 cm. Sein Umfang ist 7 + 9 + 11 = ① cm. Das Dreieck wird gespiegelt. Das Bild hat denselben Umfang. Beide Dreiecke zusammen haben als Ränder ① + ① = ② cm. Die drei Winkel des Bildes ergeben zusammen ③°. Die beiden kürzeren Seiten des Bildes sind zusammen ① − 11 = ④ cm lang.", "schablone": "① = □; ② = □; ③ = □; ④ = □", "hinweis": "Je Lücke eine ganze Zahl."}, "o": {"werte": [27, 54, 180, 16]}, "h": "Eine Spiegelung ändert keine Längen und keine Winkel.", "w": "7 + 9 + 11 = 27. Das Bild hat auch 27 cm Umfang, zusammen 54 cm. Die Winkelsumme im Dreieck ist 180°. Die längste Seite bleibt 11 cm, die beiden anderen sind zusammen 27 − 11 = 16 cm lang.", "form": "lueckenweg", "zaehlt": "nein", "r": 703}, {"l": "mittelsenkrechte", "t": "mittelsenkrechte", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "auswahl", "f": {"text": "Die Punkte A(1 | 4) und B(9 | 4) liegen auf einer waagrechten Linie. Welche Linie ist die Mittelsenkrechte von [AB]?"}, "a": ["die senkrechte Linie durch x = 8", "die senkrechte Linie durch x = 5", "die waagrechte Linie durch y = 4", "die senkrechte Linie durch x = 4"], "o": {"index": 1}, "h": "Die Mittelsenkrechte steht senkrecht auf [AB] und geht durch die Mitte.", "w": "Die Mitte hat x = (1 + 9) : 2 = 5. Senkrecht zur waagrechten Strecke: senkrechte Linie durch x = 5.", "form": "verfahren_waehlen", "zaehlt": "ja", "r": 704}, {"l": "winkelhalbierende", "t": "winkelhalbierende", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "auswahl", "f": {"text": "Ein Punkt liegt auf der Winkelhalbierenden eines Winkels. Er ist vom einen Schenkel 3 cm entfernt. Wie weit ist er vom anderen Schenkel entfernt?"}, "a": ["1,5 cm, denn die Winkelhalbierende halbiert", "6 cm, denn der andere Schenkel liegt auf der anderen Seite", "Das lässt sich nicht sagen. Der Abstand kann beliebig sein", "3 cm, denn auf der Winkelhalbierenden ist der Abstand zu beiden Schenkeln gleich"], "o": {"index": 3}, "h": "Welche Eigenschaft haben alle Punkte auf der Winkelhalbierenden?", "w": "Alle Punkte auf der Winkelhalbierenden haben von beiden Schenkeln denselben Abstand: 3 cm.", "form": "verfahren_waehlen", "zaehlt": "ja", "r": 705}, {"l": "vierecke_ordnen", "t": "vierecke_ordnen", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Zwei Wege: Weg A prüft jedes der sechs Vierecke einzeln. Weg B sucht nur die Vierecke, die das nicht haben, und zieht von 6 ab. Wie viele der Vierecke Quadrat, Rechteck, Raute, Parallelogramm, Trapez und Drachenviereck haben immer mindestens ein Paar paralleler Seiten?"}, "o": {"wert": 5}, "h": "Beim Drachenviereck gibt es keine Garantie für parallele Seiten.", "w": "Quadrat, Rechteck, Raute, Parallelogramm und Trapez haben immer ein Paar paralleler Seiten. Das Drachenviereck nicht immer. 6 − 1 = 5.", "form": "zwei_wege", "zaehlt": "ja", "r": 706}, {"l": "symmetrie", "t": "symmetrie", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Wie viele Symmetrieachsen hat ein regelmäßiges Sechseck? Weg A: 3 Achsen gehen durch gegenüberliegende Ecken, 3 weitere durch gegenüberliegende Seitenmitten. Weg B: Ein regelmäßiges Vieleck hat so viele Achsen, wie es Ecken hat."}, "o": {"wert": 6}, "h": "Beide Wege müssen dieselbe Zahl ergeben.", "w": "Weg A: 3 + 3 = 6. Weg B: Ein Sechseck hat 6 Ecken, also 6 Achsen.", "form": "zwei_wege", "zaehlt": "ja", "r": 707}, {"l": "achsenspiegelung", "t": "achsenspiegelung", "p": "uebung", "s": 3, "g": "fehler", "y": "auswahl", "f": {"text": "Kim spiegelt den Punkt P(4 | −3) an der y-Achse. Zeile 1: Bei der Spiegelung an der y-Achse bleibt der x-Wert gleich. Zeile 2: Der y-Wert wechselt das Vorzeichen: Aus −3 wird 3. Zeile 3: Das Bild ist P'(4 | 3). In welcher Zeile passiert der erste Fehler?"}, "a": ["In Zeile 1", "In Zeile 2", "In Zeile 3"], "o": {"index": 0}, "h": "Die y-Achse ist senkrecht. Welcher Wert eines Punktes ändert sich bei der Spiegelung?", "w": "Bei der y-Achse als Spiegelachse wechselt der x-Wert das Vorzeichen, die Höhe bleibt. Richtig: P'(−4 | −3).", "form": "fehler_detektiv", "zaehlt": "ja", "r": 708}, {"l": "winkelhalbierende", "t": "winkelhalbierende", "p": "uebung", "s": 3, "g": "fehler", "y": "auswahl", "f": {"text": "Ein Winkel hat 84°. Kim berechnet, wie groß die beiden Winkel sind, in die ihn die Winkelhalbierende teilt. Zeile 1: Die Winkelhalbierende teilt den Winkel in zwei gleich große Teile. Zeile 2: Jeder Teil hat 84° − 2 = 82°. Zeile 3: Die Winkelhalbierende liegt also 82° vom Schenkel entfernt. In welcher Zeile passiert der erste Fehler?"}, "a": ["In Zeile 1", "In Zeile 2", "In Zeile 3"], "o": {"index": 1}, "h": "Zwei gleich große Teile ergeben zusammen wieder 84°.", "w": "Jeder Teil ist die Hälfte: 84° : 2 = 42°. Zusammen 42° + 42° = 84°.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 709}, {"l": "eigenschaften", "t": "eigenschaften", "p": "uebung", "s": 3, "g": "rueckwaerts", "y": "zahl", "f": {"text": "Ein Dreieck wird an einer Achse gespiegelt. Das Bild hat die Seiten 6 cm und 10 cm und den Umfang 25 cm. Wie lang ist die dritte Seite des ursprünglichen Dreiecks?"}, "o": {"wert": 9, "einheit": "cm"}, "h": "Eine Spiegelung ändert keine Längen.", "w": "Das Original hat denselben Umfang wie das Bild: 25 cm. Die dritte Seite ist 25 − 6 − 10 = 9 cm.", "form": "umkehren", "zaehlt": "ja", "r": 710}, {"l": "mittelsenkrechte", "t": "mittelsenkrechte", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Die Punkte A(2|5) und B(10|5) liegen auf einer waagerechten Linie. Die Mittelsenkrechte von AB ist eine senkrechte Gerade. Weg A: den Mittelwert der beiden x-Werte bilden. Weg B: die halbe Länge der Strecke AB zum x-Wert von A addieren. Welchen x-Wert haben alle Punkte der Mittelsenkrechten?"}, "o": {"wert": 6}, "h": "Beide Wege suchen die Mitte der Strecke.", "w": "Weg A: (2 + 10) : 2 = 6. Weg B: Die Strecke ist 10 − 2 = 8 lang, die Hälfte ist 4, und 2 + 4 = 6. Beide Wege geben 6. Die Mittelsenkrechte ist die Gerade x = 6.", "form": "zwei_wege", "zaehlt": "ja", "r": 711}, {"l": "winkelhalbierende", "t": "winkelhalbierende", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Zwei Wege treffen sich im Winkel von 130°. Ein dritter Weg soll genau in der Mitte zwischen ihnen verlaufen, er liegt auf der Winkelhalbierenden. Weg A: 130° : 2. Weg B: Beide Teilwinkel sind gleich groß, x + x = 130°. Wie groß ist der Winkel zwischen dem neuen Weg und einem der beiden anderen?"}, "o": {"wert": 65, "einheit": "°"}, "h": "Die Winkelhalbierende teilt den Winkel in zwei gleich große Teile.", "w": "Weg A: 130° : 2 = 65°. Weg B: x + x = 130°, also 2x = 130° und x = 65°. Beide Wege geben 65°.", "form": "zwei_wege", "zaehlt": "ja", "r": 712}]$auf$::jsonb),
    (55, 'bruch.prozent_grundwert', 529, 16, $auf$[{"l": "vermehrt", "t": "vermehrt", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Ein Preis von 80 € steigt um 25 %. Der Wachstumsfaktor ist 1,25. 25 % von 80 € sind ① €. Neuer Preis: 80 € + ① € = ② €.", "schablone": "① = □; ② = □", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ)."}, "o": {"werte": [20, 100]}, "h": "25 % sind ein Viertel.", "w": "25 % von 80 € = 20 €. 80 € + 20 € = 100 €. Mit Faktor: 80 · 1,25 = 100.", "form": "lueckenweg", "zaehlt": "nein", "r": 550}, {"l": "vermindert", "t": "vermindert", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Eine Jacke kostet 60 €. Sie wird um 20 % billiger. 20 % von 60 € sind ① €. Neuer Preis: 60 € − ① € = ② €.", "schablone": "① = □; ② = □", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ)."}, "o": {"werte": [12, 48]}, "h": "20 % sind ein Fünftel.", "w": "20 % von 60 € = 12 €. 60 € − 12 € = 48 €. Mit Faktor: 60 · 0,8 = 48.", "form": "lueckenweg", "zaehlt": "nein", "r": 551}, {"l": "prozentsatz", "t": "prozentsatz", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Ein Preis sinkt von 80 € auf 60 €. Die Änderung ist 80 − 60 = ① €. Bezogen auf den alten Preis sind ① von 80 genau ② %.", "schablone": "① = □; ② = □", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ)."}, "o": {"werte": [20, 25]}, "h": "Teile die Änderung durch den alten Preis.", "w": "20 : 80 = 1/4 = 25 %.", "form": "lueckenweg", "zaehlt": "nein", "r": 552}, {"l": "mehrfach", "t": "mehrfach", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Ein Preis von 200 € steigt erst um 10 % und dann noch einmal um 10 %. 10 % von 200 € sind ① €. Nach dem ersten Mal kostet es ② €. 10 % von ② € sind ③ €. Nach dem zweiten Mal kostet es ② € + ③ € = ④ €.", "schablone": "① = □; ② = □; ③ = □; ④ = □", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ)."}, "o": {"werte": [20, 220, 22, 242]}, "h": "Beim zweiten Mal gehören die 10 % zum neuen Preis.", "w": "200 + 20 = 220. 10 % von 220 sind 22. 220 + 22 = 242. Nicht 240!", "form": "lueckenweg", "zaehlt": "nein", "r": 553}, {"l": "formel", "t": "formel", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Ein Wert verdoppelt sich jedes Jahr, also ist q = 2. Am Anfang sind es 300 €. Nach 3 Jahren: K = 300 · 2³. Es ist 2³ = ①. Also ist K = 300 · ① = ② €.", "schablone": "① = □; ② = □", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ)."}, "o": {"werte": [8, 2400]}, "h": "2³ heißt 2 · 2 · 2.", "w": "2³ = 8. 300 · 8 = 2 400 €.", "form": "lueckenweg", "zaehlt": "nein", "r": 554}, {"l": "argumente", "t": "argumente", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Behauptung: „Erst 50 % mehr, dann 50 % weniger ergibt wieder den Anfangswert.“ Prüfe mit 200 €. 50 % von 200 € sind ① €. Nach dem Aufschlag sind es ② €. 50 % von ② € sind ③ €. Nach dem Abschlag sind es ④ €. Das ist nicht 200 €.", "schablone": "① = □; ② = □; ③ = □; ④ = □", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ)."}, "o": {"werte": [100, 300, 150, 150]}, "h": "Der Abschlag bezieht sich auf den neuen, größeren Wert.", "w": "200 + 100 = 300. 50 % von 300 sind 150. 300 − 150 = 150, nicht 200.", "form": "lueckenweg", "zaehlt": "nein", "r": 555}, {"l": "zurueck", "t": "zurueck", "p": "uebung", "s": 2, "g": "umkehr", "y": "auswahl", "f": {"text": "Nach 20 % Rabatt kostet ein Schal 48 €. Wie findest du den alten Preis?"}, "a": ["48 : 0,8 = 60 €, denn der neue Preis ist 80 % vom alten", "48 · 1,2 = 57,60 €", "48 + 20 = 68 €", "48 : 0,2 = 240 €"], "o": {"index": 0}, "h": "Nach 20 % Rabatt sind noch wie viel Prozent vom alten Preis übrig?", "w": "Der neue Preis ist 80 % des alten: 0,8 · alt = 48. Also alt = 48 : 0,8 = 60.", "form": "verfahren_waehlen", "zaehlt": "ja", "r": 556}, {"l": "formel", "t": "formel", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "auswahl", "f": {"text": "500 € werden 3 Jahre lang mit 4 % pro Jahr verzinst. Die Zinsen werden jedes Jahr gutgeschrieben und mitverzinst. Welche Rechnung gibt das Kapital am Ende?"}, "a": ["500 · 1,04 · 3 = 1 560 €", "500 · 1,12 = 560 €", "500 · 0,04³ ≈ 0,03 €", "500 · 1,04³ ≈ 562,43 €"], "o": {"index": 3}, "h": "Der Wachstumsfaktor bei 4 % ist 1,04. Er wird dreimal angewendet.", "w": "K₃ = 500 · 1,04³ = 500 · 1,124864 ≈ 562,43 €.", "form": "verfahren_waehlen", "zaehlt": "ja", "r": 557}, {"l": "argumente", "t": "argumente", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "auswahl", "f": {"text": "Kim sagt: „Wenn ein Preis erst um 10 % steigt und dann um 10 % sinkt, ist er danach wieder wie am Anfang.“ Wie prüfst du das?"}, "a": ["Es stimmt, denn +10 % und −10 % heben sich auf", "Mit 100 € rechnen: 100 · 1,1 = 110, dann 110 · 0,9 = 99. Das sind nicht 100 €: Die Aussage ist falsch", "Es stimmt, denn 1,1 · 0,9 = 1", "Die Aussage ist falsch, denn 1,1 · 0,9 = 1,1"], "o": {"index": 1}, "h": "Wähle eine einfache Startzahl und rechne beide Schritte mit Faktoren.", "w": "100 € · 1,1 = 110 €. 110 € · 0,9 = 99 €. Die 10 % beziehen sich auf verschiedene Grundwerte.", "form": "verfahren_waehlen", "zaehlt": "ja", "r": 558}, {"l": "faktor", "t": "faktor", "p": "uebung", "s": 3, "g": "fehler", "y": "auswahl", "f": {"text": "Kim bestimmt den Wachstumsfaktor für 15 % Rabatt. Zeile 1: Beim Rabatt zahlt man noch 100 % + 15 % = 115 %. Zeile 2: 115 % sind 1,15. Zeile 3: Der Faktor ist also 1,15. In welcher Zeile passiert der erste Fehler?"}, "a": ["In Zeile 1", "In Zeile 2", "In Zeile 3"], "o": {"index": 0}, "h": "Wird bei einem Rabatt etwas dazugerechnet oder abgezogen?", "w": "Beim Rabatt zahlt man noch 100 % − 15 % = 85 %. Der Faktor ist 0,85. 1,15 wäre ein Aufschlag von 15 %.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 559}, {"l": "vermehrt", "t": "vermehrt", "p": "uebung", "s": 3, "g": "fehler", "y": "auswahl", "f": {"text": "Ein Fahrrad kostet 200 €. Der Preis steigt um 10 %. Kim berechnet den neuen Preis. Zeile 1: Der Wachstumsfaktor ist 1,10. Zeile 2: 200 · 1,10 = 22. Zeile 3: Das Fahrrad kostet jetzt 22 €. In welcher Zeile passiert der erste Fehler?"}, "a": ["In Zeile 1", "In Zeile 2", "In Zeile 3"], "o": {"index": 1}, "h": "Ein Preis, der um 10 % steigt, wird nicht kleiner als vorher.", "w": "200 · 1,10 = 220. Das Fahrrad kostet jetzt 220 €.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 560}, {"l": "vermindert", "t": "vermindert", "p": "uebung", "s": 3, "g": "fehler", "y": "auswahl", "f": {"text": "Ein Spiel kostet 50 €. Es gibt 30 % Rabatt. Kim berechnet den neuen Preis. Zeile 1: Man zahlt noch 100 % − 30 % = 70 %. Zeile 2: Der Faktor ist 0,07. Zeile 3: 50 · 0,07 = 3,5, also kostet das Spiel 3,50 €. In welcher Zeile passiert der erste Fehler?"}, "a": ["In Zeile 1", "In Zeile 2", "In Zeile 3"], "o": {"index": 1}, "h": "70 % heißt 70 von 100. Wie schreibt man das als Dezimalzahl?", "w": "70 % = 0,7. 50 · 0,7 = 35. Das Spiel kostet 35 €. Zeile 3 folgt richtig aus der falschen Zeile 2.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 561}, {"l": "formel", "t": "formel", "p": "uebung", "s": 3, "g": "fehler", "y": "auswahl", "f": {"text": "Kim berechnet, wie viel 2 000 € bei 5 % Zinsen pro Jahr nach 2 Jahren wert sind. Die Zinsen werden jedes Jahr gutgeschrieben und mitverzinst. Zeile 1: Der Faktor ist q = 1,05. Zeile 2: K₂ = 2 000 · 1,05 · 2 = 4 200. Zeile 3: Das Kapital beträgt nach 2 Jahren also 4 200 €. In welcher Zeile passiert der erste Fehler?"}, "a": ["In Zeile 1", "In Zeile 2", "In Zeile 3"], "o": {"index": 1}, "h": "Die Hochzahl n gehört an den Faktor q.", "w": "K₂ = 2 000 · 1,05² = 2 205. Kim hat den Faktor mit 2 multipliziert statt ihn zu quadrieren.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 562}, {"l": "argumente", "t": "argumente", "p": "uebung", "s": 2, "g": "darstellung", "y": "auswahl", "f": {"text": "Ein Preis wird erst um 20 % gesenkt und danach um 20 % erhöht. Welche Aussage über den Endpreis stimmt und hat die richtige Begründung?"}, "a": ["Er ist kleiner als der Anfangspreis, weil die zweiten 20 % von einem kleineren Preis genommen werden.", "Er ist so groß wie der Anfangspreis, weil +20 % und −20 % sich aufheben.", "Er ist größer als der Anfangspreis, weil man am Ende erhöht.", "Das lässt sich ohne den Anfangspreis nicht sagen."], "o": {"index": 0}, "h": "Rechne mit einem einfachen Preis, zum Beispiel 100 €.", "w": "100 € minus 20 % sind 80 €. Die 20 % beim Erhöhen werden vom kleineren Preis 80 € genommen und sind 16 €. Der Endpreis ist 96 €, also kleiner als der Anfangspreis.", "form": "bruecke", "zaehlt": "ja", "r": 563}, {"l": "faktor", "t": "faktor", "p": "uebung", "s": 3, "g": "rueckwaerts", "y": "zahl", "f": {"text": "Nach einer Preiserhöhung um 50 % kostet ein Gerät 150 €. Was kostete es vor der Erhöhung?"}, "o": {"wert": 100, "einheit": "€"}, "h": "Der neue Preis ist ein Vielfaches des alten. Welcher Faktor gehört zu +50 %?", "w": "+50 % bedeutet Faktor 1,5. Neuer Preis = alter Preis · 1,5. Also ist der alte Preis 150 : 1,5 = 100 €.", "form": "umkehren", "zaehlt": "ja", "r": 564}, {"l": "zurueck", "t": "zurueck", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Ein Mantel kostet nach 25 % Rabatt noch 48 €. Weg A: 48 : 75 · 100. Weg B: 48 : 3 · 4. Wie viel kostete der Mantel vorher?"}, "o": {"wert": 64, "einheit": "€"}, "h": "Der reduzierte Preis ist 75 % des alten Preises.", "w": "Der Rabatt ist 25 %, also sind 48 € genau 75 % des alten Preises. Weg A: 48 : 75 = 0,64 für 1 %, mal 100 sind 64 €. Weg B: 48 : 3 = 16 sind 25 %, mal 4 sind 64 €. Der Mantel kostete 64 €.", "form": "zwei_wege", "zaehlt": "ja", "r": 565}]$auf$::jsonb),
    (57, 'geometrie.konstruktion', 618, 15, $auf$[{"l": "gleichschenklig", "t": "gleichschenklig", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Ein gleichschenkliges Dreieck hat an der Spitze 50°. Ein Basiswinkel hat (180° − 50°) : 2 = ①°. Ein anderes hat die Basiswinkel 35°. Beide zusammen haben 2 · 35° = ②°. Dann hat die Spitze 180° − ②° = ③°.", "schablone": "① = □; ② = □; ③ = □", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ)."}, "o": {"werte": [65, 70, 110]}, "h": "Es gibt zwei gleich große Basiswinkel.", "w": "(180 − 50) : 2 = 65. 2 · 35 = 70. 180 − 70 = 110.", "form": "lueckenweg", "zaehlt": "nein", "r": 626}, {"l": "kongruenzsatz", "t": "kongruenzsatz", "p": "uebung", "s": 1, "g": "erkennen", "y": "auswahl", "f": {"text": "Zwei Dreiecke stimmen in einer Seite von 6 cm und in den beiden Winkeln an dieser Seite überein. Welcher Satz zeigt, dass sie kongruent sind?"}, "a": ["SWS", "WSW", "SSS", "WWW"], "o": {"index": 1}, "h": "Zähle, wie viele Seiten und wie viele Winkel gegeben sind.", "w": "Eine Seite und die beiden Winkel an ihr: Winkel, Seite, Winkel (WSW).", "form": "verfahren_waehlen", "zaehlt": "ja", "r": 627}, {"l": "konstruierbar", "t": "konstruierbar", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Zwei Seiten eines Dreiecks sind 6 cm und 10 cm lang. Die dritte Seite muss kürzer sein als 6 + 10 = ① cm. Sie muss länger sein als 10 − 6 = ② cm. Die kleinste ganze Zahl in cm, die passt, ist ② + 1 = ③. Die größte ist ① − 1 = ④.", "schablone": "① = □; ② = □; ③ = □; ④ = □", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ)."}, "o": {"werte": [16, 4, 5, 15]}, "h": "Zwei Seiten zusammen müssen länger sein als die dritte.", "w": "6 + 10 = 16, 10 − 6 = 4. Passend sind die Zahlen von 5 bis 15 cm.", "form": "lueckenweg", "zaehlt": "nein", "r": 628}, {"l": "konstruierbar", "t": "konstruierbar", "p": "uebung", "s": 1, "g": "erkennen", "y": "auswahl", "f": {"text": "Aus welchen drei Längen lässt sich ein Dreieck konstruieren?"}, "a": ["2 cm, 3 cm, 6 cm", "4 cm, 4 cm, 8 cm", "1 cm, 5 cm, 7 cm", "5 cm, 6 cm, 10 cm"], "o": {"index": 3}, "h": "Prüfe bei jeder Auswahl, ob die zwei kürzeren Seiten zusammen länger sind als die längste.", "w": "5 + 6 = 11 ist größer als 10. Bei den anderen reicht die Summe der zwei kürzeren Seiten nicht.", "form": "verfahren_waehlen", "zaehlt": "ja", "r": 629}, {"l": "gleichschenklig", "t": "gleichschenklig", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "auswahl", "f": {"text": "Ein gleichschenkliges Dreieck hat an der Spitze 30°. Welche Rechnung gibt einen Basiswinkel?"}, "a": ["180° − 30° = 150°", "(180° − 30°) : 2 = 75°", "180° : 2 − 30° = 60°", "(180° − 30°) · 2 = 300°"], "o": {"index": 1}, "h": "Die beiden Basiswinkel zusammen sind die Winkelsumme ohne die Spitze.", "w": "Die Basiswinkel haben zusammen 150°. Jeder hat 75°.", "form": "verfahren_waehlen", "zaehlt": "ja", "r": 630}, {"l": "planfigur", "t": "planfigur", "p": "uebung", "s": 2, "g": "darstellung", "y": "auswahl", "f": {"text": "Du konstruierst ein Dreieck mit c = 7 cm, b = 6 cm und a = 5 cm. Du zeichnest AB = 7 cm. Wie findest du C?"}, "a": ["Kreisbogen um A mit 6 cm und um B mit 5 cm; sie schneiden sich in C", "Kreisbogen um A und um B mit je 5 cm", "Kreisbogen um A und um B mit je 6 cm", "Kreisbogen um A mit 7 cm und um B mit 5 cm"], "o": {"index": 0}, "h": "Die Seite b liegt an der Ecke A, die Seite a an der Ecke B.", "w": "AC = b = 6 cm, also ein Kreisbogen um A mit 6 cm. BC = a = 5 cm, also ein Kreisbogen um B mit 5 cm.", "form": "verfahren_waehlen", "zaehlt": "ja", "r": 631}, {"l": "gleichschenklig", "t": "gleichschenklig", "p": "uebung", "s": 3, "g": "fehler", "y": "auswahl", "f": {"text": "Ein gleichschenkliges Dreieck hat die Basiswinkel 55°. Kim berechnet den Winkel an der Spitze. Zeile 1: Die beiden Basiswinkel sind gleich groß. Zeile 2: Die Winkelsumme ist 180°. Davon ein Basiswinkel abgezogen: 180° − 55° = 125°. Das ist der Winkel an der Spitze. Zeile 3: Der Winkel an der Spitze hat also 125°. In welcher Zeile passiert der erste Fehler?"}, "a": ["In Zeile 1", "In Zeile 2", "In Zeile 3"], "o": {"index": 1}, "h": "Wie viele Winkel müssen von der Winkelsumme abgehen, damit nur der Winkel an der Spitze übrig bleibt?", "w": "Beide Basiswinkel gehören zur Summe: 180° − 55° − 55° = 70°. Schon in Zeile 2 fehlt ein Basiswinkel; Zeile 3 übernimmt nur das falsche Ergebnis.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 632}, {"l": "kongruenzsatz", "t": "kongruenzsatz", "p": "uebung", "s": 3, "g": "fehler", "y": "auswahl", "f": {"text": "Dreieck 1 hat die Seiten a = 4 cm, b = 5 cm und den Winkel γ = 40° zwischen ihnen. Dreieck 2 hat auch a = 4 cm, b = 5 cm und 40°, aber dieser Winkel liegt der Seite a gegenüber. Kim prüft, ob sie kongruent sind. Zeile 1: Beide Dreiecke stimmen in zwei Seiten und einem Winkel überein. Zeile 2: Bei Dreieck 1 liegt der Winkel zwischen den Seiten, bei Dreieck 2 nicht. Zeile 3: Also gilt SWS, und die Dreiecke sind kongruent. In welcher Zeile steckt der Fehler?"}, "a": ["In Zeile 1", "In Zeile 2", "In Zeile 3"], "o": {"index": 2}, "h": "Bei SWS muss der Winkel zwischen den beiden gegebenen Seiten liegen.", "w": "Bei Dreieck 2 liegt der Winkel nicht zwischen den Seiten. SWS gilt nicht, und man kann nicht auf Kongruenz schließen.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 633}, {"l": "konstruierbar", "t": "konstruierbar", "p": "uebung", "s": 3, "g": "fehler", "y": "auswahl", "f": {"text": "Kim prüft, ob es ein Dreieck mit den Seiten 3 cm, 4 cm und 8 cm gibt. Zeile 1: Die Summe zweier Seiten muss größer sein als die dritte Seite. Zeile 2: 3 + 4 = 7, und 7 ist kleiner als 8. Zeile 3: Das Dreieck lässt sich konstruieren, weil 8 die längste Seite ist. In welcher Zeile steckt der Fehler?"}, "a": ["In Zeile 1", "In Zeile 2", "In Zeile 3"], "o": {"index": 2}, "h": "Prüfe, ob die beiden kürzeren Seiten zusammen die längste überbrücken.", "w": "Die beiden kurzen Seiten sind zusammen nur 7 cm lang. Sie erreichen sich nicht. Das Dreieck gibt es nicht.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 634}, {"l": "planfigur", "t": "planfigur", "p": "uebung", "s": 3, "g": "fehler", "y": "auswahl", "f": {"text": "Kim konstruiert ein Dreieck aus c = 6 cm, α = 50° und b = 4 cm. Er beschreibt seine Schritte. Zeile 1: Zeichne zuerst die Strecke AB = 6 cm. Zeile 2: Trage bei A den Winkel 50° an. Zeile 3: Markiere C auf dem freien Schenkel im Abstand 4 cm von B. In welcher Zeile steckt der Fehler?"}, "a": ["In Zeile 1", "In Zeile 2", "In Zeile 3"], "o": {"index": 2}, "h": "Welche Ecke liegt am Anfang der Seite b?", "w": "Die Seite b liegt zwischen A und C. C hat also den Abstand 4 cm von A.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 635}, {"l": "satz_kehrsatz", "t": "satz_kehrsatz", "p": "uebung", "s": 3, "g": "fehler", "y": "auswahl", "f": {"text": "Satz: „Wenn ein Dreieck gleichseitig ist, dann hat es drei gleich große Winkel.“ Kim bildet den Kehrsatz. Zeile 1: Der Satz hat die Form: Wenn A, dann B. Zeile 2: Den Kehrsatz bildet man, indem man A und B vertauscht. Zeile 3: Er lautet: Wenn ein Dreieck gleichseitig ist, dann hat es drei gleich große Winkel. In welcher Zeile steckt der Fehler?"}, "a": ["In Zeile 1", "In Zeile 2", "In Zeile 3"], "o": {"index": 2}, "h": "Vergleiche den Kehrsatz mit dem Satz. Was hat sich geändert?", "w": "Das ist der Satz selbst. Der Kehrsatz lautet: Wenn ein Dreieck drei gleich große Winkel hat, dann ist es gleichseitig.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 636}, {"l": "satz_kehrsatz", "t": "satz_kehrsatz", "p": "uebung", "s": 3, "g": "begruenden", "y": "auswahl", "f": {"text": "Satz: „Wenn eine Zahl durch 6 teilbar ist, dann ist sie durch 3 teilbar.“ Was gilt für den Kehrsatz?"}, "a": ["Der Kehrsatz ist wahr, denn der Satz ist wahr", "Der Kehrsatz ist falsch. Gegenbeispiel: 12", "Der Kehrsatz ist falsch. Gegenbeispiel: 9 ist durch 3 teilbar, aber nicht durch 6", "Der Kehrsatz ist wahr, weil 3 ein Teiler von 6 ist"], "o": {"index": 2}, "h": "Der Kehrsatz lautet: Wenn eine Zahl durch 3 teilbar ist, dann ist sie durch 6 teilbar. Suche eine Zahl, die nicht passt.", "w": "9 : 3 = 3, aber 9 ist nicht durch 6 teilbar. Ein Gegenbeispiel genügt.", "form": "verfahren_waehlen", "zaehlt": "ja", "r": 637}, {"l": "kongruenzsatz", "t": "kongruenzsatz", "p": "uebung", "s": 2, "g": "darstellung", "y": "auswahl", "f": {"text": "Von zwei Dreiecken weißt du: Zwei Seiten sind gleich lang, und der Winkel zwischen genau diesen beiden Seiten ist gleich groß. Welcher Kongruenzsatz zeigt, dass die Dreiecke deckungsgleich sind?"}, "a": ["SSS", "SWS", "WSW", "Es gibt keinen passenden Satz."], "o": {"index": 1}, "h": "Achte darauf, wo der gleiche Winkel liegt: zwischen den Seiten oder woanders.", "w": "Es sind zwei Seiten und der eingeschlossene Winkel gleich. Das ist der Satz SWS (Seite – Winkel – Seite). SSS bräuchte drei Seiten, WSW zwei Winkel.", "form": "bruecke", "zaehlt": "ja", "r": 638}, {"l": "planfigur", "t": "planfigur", "p": "uebung", "s": 2, "g": "umkehr", "y": "zahl", "f": {"text": "In der Planfigur eines gleichschenkligen Dreiecks ABC mit der Basis AB ist der Basiswinkel α = 70° eingetragen. Wie groß ist der Winkel γ an der Spitze C?"}, "o": {"wert": 40, "einheit": "°"}, "h": "Beide Basiswinkel sind gleich. Die Winkelsumme im Dreieck ist 180°.", "w": "Beide Basiswinkel sind 70°, zusammen 140°. Der Winkel an der Spitze ist 180° − 140° = 40°.", "form": "umkehren", "zaehlt": "ja", "r": 639}, {"l": "satz_kehrsatz", "t": "satz_kehrsatz", "p": "uebung", "s": 3, "g": "transfer", "y": "auswahl", "f": {"text": "Satz: „Wenn zwei Dreiecke deckungsgleich sind, haben sie gleiche Winkel.“ Welche Aussage über den Kehrsatz stimmt?"}, "a": ["Wenn zwei Dreiecke gleiche Winkel haben, sind sie deckungsgleich. Der Kehrsatz gilt nicht, denn ein Dreieck und seine Vergrößerung haben gleiche Winkel.", "Wenn zwei Dreiecke gleiche Winkel haben, sind sie deckungsgleich. Der Kehrsatz gilt, weil gleiche Winkel gleiche Größe ergeben.", "Wenn zwei Dreiecke nicht deckungsgleich sind, haben sie verschiedene Winkel. Der Kehrsatz gilt immer.", "Der Kehrsatz ist derselbe Satz mit vertauschten Dreiecken. Er gilt, weil der Satz gilt."], "o": {"index": 0}, "h": "Suche ein Dreieck und eine Vergrößerung davon.", "w": "Der Kehrsatz lautet: Wenn zwei Dreiecke gleiche Winkel haben, sind sie deckungsgleich. Er gilt nicht: Ein Dreieck und seine Vergrößerung haben gleiche Winkel, sind aber verschieden groß. Ein einziges solches Gegenbeispiel genügt.", "form": "bruecke", "zaehlt": "ja", "r": 640}]$auf$::jsonb),
    (67, 'groessen.proportional', 633, 6, $auf$[{"l": "geschickt", "t": "dreisatz", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Jedes Heft kostet gleich viel. 4 Hefte kosten 6 €. Von 4 Heften zu 12 Heften: 12 : 4 = ①. Der Preis wird auch ①-mal so groß: 6 € · ① = ② €.", "schablone": "① = □; ② = □", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ)."}, "o": {"werte": [3, 18]}, "h": "Wie oft passen 4 Hefte in 12 Hefte?", "w": "12 : 4 = 3. 6 € · 3 = 18 €.", "form": "lueckenweg", "zaehlt": "nein", "r": 654}, {"l": "sach", "t": "anwenden", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Ein Auto verbraucht auf jedem Kilometer gleich viel. Auf 100 km braucht es 6 l Benzin. Für 300 km braucht es 300 : 100 = ① mal so viel. Das sind 6 l · ① = ② l.", "schablone": "① = □; ② = □", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ)."}, "o": {"werte": [3, 18]}, "h": "300 km sind mehrere Stücke von je 100 km.", "w": "300 : 100 = 3. 3 · 6 l = 18 l.", "form": "lueckenweg", "zaehlt": "nein", "r": 655}, {"l": "aenderung", "t": "aenderung", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Ein Becken wird leer gepumpt. Nach 2 Minuten sind es noch 90 l Wasser, nach 5 Minuten noch 60 l. Wir berechnen die mittlere Änderung zwischen Minute 2 und Minute 5. Änderung des Wassers: 60 − 90 = ① l. Zeitspanne: 5 − 2 = ② min. Mittlere Rate: ① : ② = ③ l je Minute.", "schablone": "① = □; ② = □; ③ = □", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ)."}, "o": {"werte": [-30, 3, -10]}, "h": "Das Wasser wird weniger. Die Rate hat ein Minus.", "w": "−30 l in 3 min: −30 : 3 = −10 l je Minute (im Mittel).", "form": "lueckenweg", "zaehlt": "nein", "r": 656}, {"l": "aenderung", "t": "aenderung", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "auswahl", "f": {"text": "Eine Pflanze war nach 2 Wochen 14 cm hoch und nach 6 Wochen 30 cm. Wie berechnest du, wie viel sie zwischen Woche 2 und Woche 6 im Mittel pro Woche wächst?"}, "a": ["30 : 6 = 5 cm pro Woche", "30 − 14 = 16 cm pro Woche", "(30 + 14) : (6 + 2) = 5,5 cm pro Woche", "(30 − 14) : (6 − 2) = 4 cm pro Woche"], "o": {"index": 3}, "h": "Änderungsrate = Änderung : Zeitspanne.", "w": "Die Höhe ändert sich um 16 cm in 4 Wochen: 16 : 4 = 4 cm je Woche im Mittel.", "form": "verfahren_waehlen", "zaehlt": "ja", "r": 657}, {"l": "einheit", "t": "dreisatz", "p": "uebung", "s": 3, "g": "fehler", "y": "auswahl", "f": {"text": "6 Brötchen kosten 3,60 €. Kim berechnet den Preis für 1 Brötchen in Cent. Zeile 1: Preis durch Anzahl: 360 ct : 6. Zeile 2: 360 ct : 6 = 6 ct. Zeile 3: Ein Brötchen kostet also 6 ct. In welcher Zeile passiert der erste Fehler?"}, "a": ["In Zeile 1", "In Zeile 2", "In Zeile 3"], "o": {"index": 1}, "h": "Rechne 6 mal den Preis für ein Brötchen. Kommt 360 ct heraus?", "w": "360 : 6 = 60. Ein Brötchen kostet 60 ct. Probe: 6 · 60 ct = 360 ct.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 658}, {"l": "sach", "t": "anwenden", "p": "uebung", "s": 1, "g": "direkt", "y": "zahl", "f": {"text": "3 kg Äpfel kosten 9 €. Der Preis je Kilogramm ist immer gleich. Weg A: erst den Preis für 1 kg bestimmen, dann mit 5 multiplizieren. Weg B: 9 · 5 : 3 rechnen. Wie viel kosten 5 kg?"}, "o": {"wert": 15, "einheit": "€"}, "h": "Beide Wege bestimmen den Preis für 5 kg aus dem für 3 kg.", "w": "Weg A: 9 : 3 = 3 € für 1 kg, 3 · 5 = 15 €. Weg B: 9 · 5 = 45, 45 : 3 = 15. 5 kg kosten 15 €.", "form": "zwei_wege", "zaehlt": "ja", "r": 659}]$auf$::jsonb),
    (92, 'geometrie.winkelsaetze', 658, 23, $auf$[{"l": "parallel_pruefen", "t": "parallel_pruefen", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "g ∥ h. Eine Gerade schneidet beide. Bei S gibt es einen Winkel von 72°. Sein Stufenwinkel bei T ist genauso groß. Beide zusammen haben ①°. Der Nebenwinkel bei T hat 180° − 72° = ②°. Er ist ② − 72° = ③° größer als der Stufenwinkel.", "schablone": "① = □; ② = □; ③ = □", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ)."}, "o": {"werte": [144, 108, 36]}, "h": "Der Nebenwinkel ergänzt den Stufenwinkel zu einer geraden Linie.", "w": "72 + 72 = 144. 180 − 72 = 108. 108 − 72 = 36.", "form": "lueckenweg", "zaehlt": "nein", "r": 673}, {"l": "innenwinkelsumme", "t": "innenwinkelsumme", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Im Dreieck ist α = 48° und β = 77°. Dann ist γ = 180° − 48° − 77° = ①°. Das sind ① − 48° = ②° mehr als α. Ein Viereck hat die Winkel 95°, 100° und 85°. Der vierte Winkel ist 360° − 95° − 100° − 85° = ③°. Er ist um ③° − ①° = ④° größer als γ.", "schablone": "① = □; ② = □; ③ = □; ④ = □", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ)."}, "o": {"werte": [55, 7, 80, 25]}, "h": "Im Dreieck sind es 180°, im Viereck 360°.", "w": "180 − 48 − 77 = 55. 55 − 48 = 7. 360 − 95 − 100 − 85 = 80. 80 − 55 = 25.", "form": "lueckenweg", "zaehlt": "nein", "r": 674}, {"l": "vieleck", "t": "vieleck", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Ein konvexes Fünfeck zerlegt man von einer Ecke aus in 3 Dreiecke. Die Winkelsumme ist 3 · 180° = ①°. Ein konvexes Sechseck zerlegt man in 6 − 2 = ② Dreiecke. Seine Winkelsumme ist ② · 180° = ③°.", "schablone": "① = □; ② = □; ③ = □", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ)."}, "o": {"werte": [540, 4, 720]}, "h": "Ein n-Eck zerlegt man in n − 2 Dreiecke.", "w": "3 · 180 = 540. Ein Sechseck: 6 − 2 = 4 Dreiecke, 4 · 180 = 720.", "form": "lueckenweg", "zaehlt": "nein", "r": 675}, {"l": "figuren", "t": "figuren", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Im gleichschenkligen Dreieck hat der Winkel an der Spitze 40°. Ein Basiswinkel hat (180° − 40°) : 2 = ①°. Der Nebenwinkel eines Basiswinkels hat 180° − ①° = ②°.", "schablone": "① = □; ② = □", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ)."}, "o": {"werte": [70, 110]}, "h": "Beide Basiswinkel sind gleich groß.", "w": "140° : 2 = 70°. 180° − 70° = 110°.", "form": "lueckenweg", "zaehlt": "nein", "r": 676}, {"l": "scheitel_neben", "t": "scheitel_neben", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "auswahl", "f": {"text": "Zwei Geraden schneiden sich. Ein Winkel hat 65°. Welche Rechnung gibt den Nebenwinkel?"}, "a": ["Der Nebenwinkel hat auch 65°", "180° − 65° = 115°", "90° − 65° = 25°", "360° − 65° = 295°"], "o": {"index": 1}, "h": "Ein Winkel und sein Nebenwinkel bilden zusammen eine gerade Linie.", "w": "Eine gerade Linie hat 180°. 180° − 65° = 115°.", "form": "verfahren_waehlen", "zaehlt": "ja", "r": 677}, {"l": "stufen_wechsel", "t": "stufen_wechsel", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "auswahl", "f": {"text": "g ∥ h. Eine Gerade schneidet g in S und h in T. Der Winkel bei S oberhalb von g und rechts von der Geraden hat 75°. Wie groß ist sein Wechselwinkel bei T (unterhalb von h und links von der Geraden)?"}, "a": ["105°, denn Wechselwinkel ergeben zusammen 180°", "75°, denn Wechselwinkel an Parallelen sind gleich groß", "15°, denn 90° − 75°", "285°, denn 360° − 75°"], "o": {"index": 1}, "h": "Wechselwinkel liegen auf verschiedenen Seiten der Geraden und an verschiedenen Parallelen.", "w": "Wechselwinkel an Parallelen sind gleich: 75°.", "form": "verfahren_waehlen", "zaehlt": "ja", "r": 678}, {"l": "innenwinkelsumme", "t": "innenwinkelsumme", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "auswahl", "f": {"text": "Ein Dreieck hat α = 35° und β = 70°. Welche Rechnung gibt γ?"}, "a": ["360° − 35° − 70° = 255°", "35° + 70° = 105°", "180° − 70° = 110°", "180° − 35° − 70° = 75°"], "o": {"index": 3}, "h": "Alle drei Winkel eines Dreiecks ergeben zusammen eine feste Summe.", "w": "180° − 35° = 145°. 145° − 70° = 75°.", "form": "verfahren_waehlen", "zaehlt": "ja", "r": 679}, {"l": "aussenwinkel", "t": "aussenwinkel", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "auswahl", "f": {"text": "Ein Dreieck hat α = 62° und β = 48°. Wie groß ist der Außenwinkel bei C?"}, "a": ["62° + 48° = 110°", "180° − 62° − 48° = 70°", "180° − 62° = 118°", "360° − 62° − 48° = 250°"], "o": {"index": 0}, "h": "Der Außenwinkel und γ ergeben zusammen eine gerade Linie.", "w": "γ = 70°. Außenwinkel = 180° − 70° = 110°. Das ist auch α + β.", "form": "verfahren_waehlen", "zaehlt": "ja", "r": 680}, {"l": "vieleck", "t": "vieleck", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "auswahl", "f": {"text": "Wie groß ist jeder Innenwinkel eines regelmäßigen Sechsecks?"}, "a": ["180° : 6 = 30°", "360° : 6 = 60°", "(6 − 2) · 180° : 6 = 120°", "(6 − 2) · 180° = 720°"], "o": {"index": 2}, "h": "Rechne erst die Winkelsumme aus, dann teile durch die Zahl der Ecken.", "w": "Winkelsumme: 4 · 180° = 720°. 720° : 6 = 120°.", "form": "verfahren_waehlen", "zaehlt": "ja", "r": 681}, {"l": "parkett", "t": "parkett", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "auswahl", "f": {"text": "Ein Boden wird mit regelmäßigen Sechsecken ausgelegt. Wie viele Sechsecke stoßen an einer Ecke zusammen?"}, "a": ["4, denn 4 · 90° = 360°", "2, denn 2 · 180° = 360°", "3, denn 3 · 120° = 360°", "6, denn ein Sechseck hat 6 Ecken"], "o": {"index": 2}, "h": "Alle Winkel an einem Punkt ergeben 360°. Wie groß ist ein Innenwinkel des Sechsecks?", "w": "Ein Innenwinkel hat 120°. 360° : 120° = 3.", "form": "verfahren_waehlen", "zaehlt": "ja", "r": 682}, {"l": "figuren", "t": "figuren", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "auswahl", "f": {"text": "Ein gestreckter Winkel wird durch eine Linie in zwei Teile geteilt. Ein Teil ist fünfmal so groß wie der andere. Welche Rechnung gibt den kleineren Teil?"}, "a": ["180° : (1 + 5) = 30°", "180° : 5 = 36°", "180° : 2 = 90°", "180° − 5° = 175°"], "o": {"index": 0}, "h": "Zähle die Teile: Der kleine Teil ist ein Teil, der große sind fünf Teile.", "w": "Es sind 1 + 5 = 6 gleiche Teile. 180° : 6 = 30°. Der große Teil hat 150°.", "form": "verfahren_waehlen", "zaehlt": "ja", "r": 683}, {"l": "scheitel_neben", "t": "scheitel_neben", "p": "uebung", "s": 3, "g": "fehler", "y": "auswahl", "f": {"text": "Zwei Geraden schneiden sich. Ein Winkel α hat 52°. Kim berechnet die anderen drei Winkel. Zeile 1: Der Scheitelwinkel von α ist genauso groß: 52°. Zeile 2: Ein Nebenwinkel von α hat 180° − 52° = 128°. Zeile 3: Der andere Nebenwinkel von α hat 52°. In welcher Zeile steckt der Fehler?"}, "a": ["In Zeile 1", "In Zeile 2", "In Zeile 3"], "o": {"index": 2}, "h": "Die vier Winkel bilden zwei Paare gleich großer Winkel. Welche Paare sind es?", "w": "Der andere Nebenwinkel ist der Scheitelwinkel des ersten Nebenwinkels. Er hat auch 128°.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 684}, {"l": "stufen_wechsel", "t": "stufen_wechsel", "p": "uebung", "s": 3, "g": "fehler", "y": "auswahl", "f": {"text": "Die Geraden g und h sind parallel. Eine dritte Gerade schneidet beide. Bei S ist ein Winkel 110° groß. Kim sucht Winkel bei T. Zeile 1: Der Stufenwinkel bei T ist gleich groß: 110°. Zeile 2: Der Nebenwinkel dieses Stufenwinkels hat 180° − 110° = 70°. Zeile 3: Der Nebenwinkel dieses Stufenwinkels hat auch 110°. In welcher Zeile steckt der Fehler?"}, "a": ["In Zeile 1", "In Zeile 2", "In Zeile 3"], "o": {"index": 2}, "h": "Stufenwinkel sind gleich. Nebenwinkel sind es nur, wenn beide 90° haben.", "w": "Der Nebenwinkel hat 180° − 110° = 70°.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 685}, {"l": "parallel_pruefen", "t": "parallel_pruefen", "p": "uebung", "s": 3, "g": "fehler", "y": "auswahl", "f": {"text": "Eine Gerade schneidet g und h. Die zugehörigen Stufenwinkel sind 80° und 100° groß. Kim prüft, ob g ∥ h gilt. Zeile 1: Die Stufenwinkel sind 80° und 100°. Zeile 2: Bei Parallelen müssten die Stufenwinkel gleich groß sein. Zeile 3: 80° + 100° = 180°, also sind g und h parallel. In welcher Zeile steckt der Fehler?"}, "a": ["In Zeile 1", "In Zeile 2", "In Zeile 3"], "o": {"index": 2}, "h": "Welche Winkel sind bei Parallelen gleich groß, und welche ergeben zusammen 180°?", "w": "Die Summe 180° gilt für Nebenwinkel. Stufenwinkel müssen gleich sein. 80° ist nicht 100°, also sind g und h nicht parallel.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 686}, {"l": "innenwinkelsumme", "t": "innenwinkelsumme", "p": "uebung", "s": 3, "g": "fehler", "y": "auswahl", "f": {"text": "Im Dreieck ist α = 40° und β = 75°. Kim berechnet γ. Zeile 1: Die Winkelsumme im Dreieck beträgt 360°. Zeile 2: α + β = 40° + 75° = 115°. Zeile 3: γ = 360° − 115° = 245°. In welcher Zeile passiert der erste Fehler?"}, "a": ["In Zeile 1", "In Zeile 2", "In Zeile 3"], "o": {"index": 0}, "h": "Welche Zahl gehört zur Winkelsumme im Dreieck?", "w": "Die Winkelsumme im Dreieck beträgt 180°. Also γ = 180° − 115° = 65°.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 687}, {"l": "vieleck", "t": "vieleck", "p": "uebung", "s": 3, "g": "fehler", "y": "auswahl", "f": {"text": "Kim berechnet die Winkelsumme eines konvexen Achtecks. Zeile 1: Von einer Ecke aus zerlegt man ein konvexes n-Eck in n Dreiecke. Zeile 2: Beim Achteck sind das 8 Dreiecke. Zeile 3: Die Winkelsumme ist 8 · 180° = 1 440°. In welcher Zeile passiert der erste Fehler?"}, "a": ["In Zeile 1", "In Zeile 2", "In Zeile 3"], "o": {"index": 0}, "h": "Zähle bei einem Viereck nach: Wie viele Dreiecke entstehen von einer Ecke aus?", "w": "Es sind n − 2 Dreiecke: 8 − 2 = 6, und 6 · 180° = 1 080°.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 688}, {"l": "parkett", "t": "parkett", "p": "uebung", "s": 3, "g": "fehler", "y": "auswahl", "f": {"text": "Kim prüft, ob regelmäßige Fünfecke einen Boden lückenlos bedecken können. Zeile 1: Die Winkelsumme im Fünfeck ist 4 · 180° = 720°. Zeile 2: Jeder Innenwinkel hat 720° : 5 = 144°. Zeile 3: An einem Punkt treffen sich 360° : 144° = 2,5 Fünfecke. Das geht nicht ohne Lücke auf. In welcher Zeile passiert der erste Fehler?"}, "a": ["In Zeile 1", "In Zeile 2", "In Zeile 3"], "o": {"index": 0}, "h": "Von einer Ecke aus zerlegt man ein Fünfeck in wie viele Dreiecke?", "w": "Ein Fünfeck zerlegt man in 3 Dreiecke: 3 · 180° = 540°, jeder Winkel hat 540° : 5 = 108°. 360° : 108° ist ungefähr 3,3, es bleibt eine Lücke. Zeile 2 und 3 folgen richtig aus Zeile 1.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 689}, {"l": "figuren", "t": "figuren", "p": "uebung", "s": 3, "g": "fehler", "y": "auswahl", "f": {"text": "Im Parallelogramm ABCD ist α = 70°. Kim berechnet die anderen Winkel. Zeile 1: Gegenüberliegende Winkel sind gleich groß: γ = 70°. Zeile 2: Nachbarwinkel ergeben 180°: β = 180° − 70° = 110°. Zeile 3: δ = 360° − 70° − 70° − 110° = 100°. In welcher Zeile steckt der Fehler?"}, "a": ["In Zeile 1", "In Zeile 2", "In Zeile 3"], "o": {"index": 2}, "h": "δ liegt gegenüber von β.", "w": "δ = 360° − 250° = 110°. Es ist gleich β, denn die Winkel gegenüber sind gleich.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 690}, {"l": "beweisen", "t": "beweisen", "p": "uebung", "s": 3, "g": "fehler", "y": "auswahl", "f": {"text": "Kim beweist: „Ein Außenwinkel eines Dreiecks ist so groß wie die beiden nicht anliegenden Innenwinkel zusammen.“ Es geht um den Außenwinkel bei C. Zeile 1: Außenwinkel bei C und γ sind Nebenwinkel: Außenwinkel + γ = 180°. Zeile 2: Die Winkelsumme im Dreieck ist α + β + γ = 180°. Zeile 3: Aus beiden Gleichungen folgt: Außenwinkel = α + γ. In welcher Zeile steckt der Fehler?"}, "a": ["In Zeile 1", "In Zeile 2", "In Zeile 3"], "o": {"index": 2}, "h": "Vergleiche beide Gleichungen: Was steht auf beiden Seiten gleich da?", "w": "In beiden Gleichungen kommt γ vor. Zieht man γ ab, folgt: Außenwinkel = α + β.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 691}, {"l": "beweisen", "t": "beweisen", "p": "uebung", "s": 3, "g": "begruenden", "y": "auswahl", "f": {"text": "Du willst beweisen, dass die Winkel in jedem Dreieck zusammen 180° ergeben. Welcher Ansatz ermöglicht einen Beweis für jedes Dreieck?"}, "a": ["Mit dem Messen der Winkel in einem gezeichneten Dreieck", "Mit der Annahme, dass alle drei Winkel gleich sind", "Mit einem Dreieck mit den Winkeln 60°, 60° und 60°", "Mit der Parallelen zu AB durch C, damit du Wechselwinkel nutzen kannst"], "o": {"index": 3}, "h": "Ein Beweis muss für jedes Dreieck gelten, nicht nur für ein gezeichnetes.", "w": "Die Parallele zu AB durch C liefert zwei Wechselwinkel. Mit γ bilden sie eine gerade Linie von 180°.", "form": "verfahren_waehlen", "zaehlt": "ja", "r": 692}, {"l": "beweisen", "t": "beweisen", "p": "uebung", "s": 3, "g": "transfer", "y": "auswahl", "f": {"text": "Beim Beweis der Winkelsumme im Dreieck ABC zeichnet man durch C die Parallele zu AB. Welcher Satz sorgt dafür, dass die Winkel bei C gleich α und β sind?"}, "a": ["Wechselwinkel an Parallelen sind gleich groß.", "Scheitelwinkel sind gleich groß.", "Nebenwinkel ergeben zusammen 180°.", "Im Dreieck liegt der größte Winkel der längsten Seite gegenüber."], "o": {"index": 0}, "h": "Die beiden Parallelen werden von AC und BC geschnitten.", "w": "Die Parallele durch C und die Gerade AB sind parallel, die Dreiecksseiten AC und BC schneiden beide. Wechselwinkel an Parallelen sind gleich groß, deshalb liegen α und β bei C noch einmal. Mit dem Winkel γ ergibt sich ein gestreckter Winkel von 180°.", "form": "bruecke", "zaehlt": "ja", "r": 693}, {"l": "parkett", "t": "parkett", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Um einen Punkt sollen regelmäßige Sechsecke mit dem Innenwinkel 120° ohne Lücke zusammenstoßen. Weg A: 360° : 120°. Weg B: 120°, 240°, 360° aufzählen und die Schritte zählen. Wie viele Sechsecke treffen sich?"}, "o": {"wert": 3}, "h": "Alle Winkel zusammen müssen einen Vollwinkel von 360° füllen.", "w": "Weg A: 360° : 120° = 3. Weg B: 120°, 240°, 360° sind drei Schritte. Es treffen sich 3 Sechsecke.", "form": "zwei_wege", "zaehlt": "ja", "r": 694}, {"l": "scheitel_neben", "t": "scheitel_neben", "p": "uebung", "s": 2, "g": "umkehr", "y": "zahl", "f": {"text": "Zwei Geraden schneiden sich. Der Nebenwinkel von α misst 112°. Wie groß ist der Scheitelwinkel von α?"}, "o": {"wert": 68, "einheit": "°"}, "h": "Bestimme erst α aus dem Nebenwinkel. Der Scheitelwinkel von α ist so groß wie α.", "w": "Winkel und Nebenwinkel ergeben 180°. Also ist α = 180° − 112° = 68°. Der Scheitelwinkel ist genauso groß, 68°.", "form": "umkehren", "zaehlt": "ja", "r": 695}]$auf$::jsonb),
    (304, 'groessen.proportional_teil2', 573, 1, $auf$[{"l": "erkennen", "t": "begriff", "p": "uebung", "s": 1, "g": "erkennen", "y": "auswahl", "f": {"text": "Welche dieser Zuordnungen ist proportional?"}, "a": ["Anzahl der Hefte → Gesamtpreis bei 2 € je Heft", "Alter eines Kindes → Körpergröße", "Anzahl der Arbeiter → Zeit für den Bau", "Seitenlänge eines Quadrats → Fläche"], "o": {"index": 0}, "h": "Bei einer proportionalen Zuordnung ergibt das Doppelte links das Doppelte rechts.", "w": "Bei 2 € pro Heft kosten doppelt so viele Hefte doppelt so viel, die Zuordnung Anzahl → Preis ist proportional. Größe wächst nicht gleichmäßig mit dem Alter. Mehr Arbeiter brauchen weniger Zeit; wenn jeder gleich schnell arbeitet und sich die Arbeit beliebig teilen lässt, ist das antiproportional, nicht proportional. Die Fläche eines Quadrats wächst mit dem Quadrat der Seite.", "form": "bruecke", "zaehlt": "ja", "r": 592}]$auf$::jsonb),
    (306, 'geometrie.konstruktion_teil2', 632, 5, $auf$[{"l": "vierecke", "t": "vierecke", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Im Parallelogramm ABCD ist α = 65°. Alle vier Winkel zusammen haben ①°. Der Nachbarwinkel β hat 180° − 65° = ②°. Probe: 2 · 65° + 2 · ②° = ③°. Das passt zu ①°.", "schablone": "① = □; ② = □; ③ = □", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ)."}, "o": {"werte": [360, 115, 360]}, "h": "Nachbarwinkel im Parallelogramm ergeben zusammen eine gerade Linie.", "w": "Im Viereck sind es 360°. β = 115°. 130° + 230° = 360°.", "form": "lueckenweg", "zaehlt": "nein", "r": 635}, {"l": "vierecke_konstruieren", "t": "vierecke_konstruieren", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Du konstruierst ein Parallelogramm ABCD mit a = 6 cm, b = 4 cm und α = 70°. Der Winkel β bei B hat 180° − 70° = ①°. Alle vier Winkel zusammen: 70° + ①° + 70° + ①° = ②°.", "schablone": "① = □; ② = □", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ)."}, "o": {"werte": [110, 360]}, "h": "Nachbarwinkel im Parallelogramm ergänzen sich zu 180°.", "w": "β = 110°. 70 + 110 + 70 + 110 = 360°.", "form": "lueckenweg", "zaehlt": "nein", "r": 636}, {"l": "vierecke", "t": "vierecke", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "auswahl", "f": {"text": "Ein Viereck hat die Winkel 85°, 95° und 100°. Welche Rechnung gibt den vierten Winkel?"}, "a": ["180° − 85° − 95° − 100° = −100°", "85° + 95° + 100° = 280°", "360° − 85° − 95° − 100° = 80°", "360° − 85° − 95° = 180°"], "o": {"index": 2}, "h": "Ein Viereck hat eine feste Winkelsumme.", "w": "Die drei Winkel haben zusammen 280°. 360° − 280° = 80°.", "form": "verfahren_waehlen", "zaehlt": "ja", "r": 637}, {"l": "vierecke", "t": "vierecke", "p": "uebung", "s": 3, "g": "fehler", "y": "auswahl", "f": {"text": "Eine Raute hat einen Winkel von 40°. Kim berechnet den Nachbarwinkel. Zeile 1: Eine Raute ist ein Parallelogramm. Zeile 2: Nachbarwinkel im Parallelogramm sind gleich groß. Zeile 3: Der Nachbarwinkel hat also 40°. In welcher Zeile passiert der erste Fehler?"}, "a": ["In Zeile 1", "In Zeile 2", "In Zeile 3"], "o": {"index": 1}, "h": "Welche Winkel im Parallelogramm sind gleich groß, welche ergeben zusammen 180°?", "w": "Gegenüberliegende Winkel sind gleich groß, Nachbarwinkel ergeben zusammen 180°: 180° − 40° = 140°. Zeile 3 folgt richtig aus der falschen Zeile 2.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 638}, {"l": "vierecke_konstruieren", "t": "vierecke_konstruieren", "p": "uebung", "s": 3, "g": "fehler", "y": "auswahl", "f": {"text": "Kim konstruiert ein Parallelogramm ABCD aus a = 6 cm, b = 4 cm und α = 70°. Zeile 1: Zeichne AB = 6 cm und trage bei A den Winkel 70° an. Zeile 2: Auf dem freien Schenkel liegt D mit AD = 4 cm. Zeile 3: C erhältst du mit BC = 6 cm und CD = 4 cm. In welcher Zeile steckt der Fehler?"}, "a": ["In Zeile 1", "In Zeile 2", "In Zeile 3"], "o": {"index": 2}, "h": "Gegenüberliegende Seiten im Parallelogramm sind gleich lang. Welche Seite liegt gegenüber von AB?", "w": "BC liegt gegenüber von AD, also BC = 4 cm. CD liegt gegenüber von AB, also CD = 6 cm.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 639}]$auf$::jsonb),
    (307, 'abbildungen.kongruenz_teil2', 729, 10, $auf$[{"l": "gegenvektor", "t": "gegenvektor", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Der Punkt P(1 | 3) wird durch eine Verschiebung auf P′(6 | −2) abgebildet. Der Verschiebungsvektor ist v = (6 − 1 | −2 − 3) = (① | ②). Der Gegenvektor −v hat die Koordinaten (③ | ④). Wendet man −v auf Q(9 | 2) an, erhält man (9 + ③ | 2 + ④) = (⑤ | ⑥).", "schablone": "① = □; ② = □; ③ = □; ④ = □; ⑤ = □; ⑥ = □", "hinweis": "Je Lücke eine ganze Zahl, wenn nötig mit Minus."}, "o": {"werte": [5, -5, -5, 5, 4, 7]}, "h": "Rechne Zahl für Zahl: erst x, dann y. Der Gegenvektor macht die Verschiebung rückgängig.", "w": "v = (5 | −5). Der Gegenvektor hat die entgegengesetzten Vorzeichen: −v = (−5 | 5). Q wird zu (9 − 5 | 2 + 5) = (4 | 7).", "form": "lueckenweg", "zaehlt": "nein", "r": 733}, {"l": "vektor_koordinaten", "t": "vektor_koordinaten", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Der Vektor v zeigt von A(1 | 6) nach B(8 | 2): v = (8 − 1 | 2 − 6) = (① | ②). Addiert man v zu C(3 | 9), erhält man C'(③ | ④).", "schablone": "① = □; ② = □; ③ = □; ④ = □", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ)."}, "o": {"werte": [7, -4, 10, 5]}, "h": "Ende minus Anfang. Dann C plus v.", "w": "v = (7 | −4). C' = (3 + 7 | 9 − 4) = (10 | 5).", "form": "lueckenweg", "zaehlt": "nein", "r": 734}, {"l": "verschiebung", "t": "verschiebung", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "auswahl", "f": {"text": "Eine Verschiebung bringt A(2 | 5) nach A'(−1 | 9). Wohin kommt B(4 | 0) bei derselben Verschiebung, und wie berechnest du das?"}, "a": ["v = (−1 − 2 | 9 − 5) = (−3 | 4), also B'(4 − 3 | 0 + 4) = (1 | 4)", "v = (2 − (−1) | 5 − 9) = (3 | −4), also B'(4 + 3 | 0 − 4) = (7 | −4)", "v = (−1 | 9), also B'(4 − 1 | 0 + 9) = (3 | 9)", "v = (−3 | 4), also B'(4 | 0) bleibt, weil B nicht auf A liegt"], "o": {"index": 0}, "h": "Der Vektor zeigt von A nach A'. Ende minus Anfang.", "w": "v = A' − A = (−3 | 4). Dann B' = B + v = (1 | 4).", "form": "verfahren_waehlen", "zaehlt": "ja", "r": 735}, {"l": "gegenvektor", "t": "gegenvektor", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "auswahl", "f": {"text": "Ein Punkt wurde mit v = (4 | −3) verschoben und liegt jetzt bei Q'(2 | 7). Wie findest du den Urpunkt Q?"}, "a": ["Q' + v rechnen: (2 + 4 | 7 + (−3)) = (6 | 4)", "v − Q' rechnen: (4 − 2 | −3 − 7) = (2 | −10)", "Q' − v rechnen: (2 − 4 | 7 − (−3)) = (−2 | 10)", "x und y tauschen: (7 − 4 | 2 − (−3)) = (3 | 5)"], "o": {"index": 2}, "h": "Der Weg zurück ist der Gegenvektor.", "w": "Q' − v = (2 − 4 | 7 + 3) = (−2 | 10). Probe: (−2 + 4 | 10 − 3) = (2 | 7).", "form": "verfahren_waehlen", "zaehlt": "ja", "r": 736}, {"l": "vektor_koordinaten", "t": "vektor_koordinaten", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "auswahl", "f": {"text": "Der Vektor v zeigt von A(1 | 2) nach B(6 | 5). Vom Punkt B aus gehst du noch einmal um v weiter und kommst zu C. Welche Rechnung ist richtig?"}, "a": ["v = (6 − 1 | 5 − 2) = (5 | 3), also C(6 + 5 | 5 + 3) = (11 | 8)", "C(6 + 1 | 5 + 2) = (7 | 7)", "v = (1 − 6 | 2 − 5) = (−5 | −3), also C(6 − 5 | 5 − 3) = (1 | 2)", "C(6 · 2 | 5 · 2) = (12 | 10)"], "o": {"index": 0}, "h": "Erst v ausrechnen, dann zu B addieren.", "w": "v = (5 | 3). C = B + v = (11 | 8).", "form": "verfahren_waehlen", "zaehlt": "ja", "r": 737}, {"l": "verschiebung", "t": "verschiebung", "p": "uebung", "s": 3, "g": "fehler", "y": "auswahl", "f": {"text": "Kim verschiebt P(3 | −2) mit dem Vektor v = (−5 | 4). Zeile 1: Die erste Zahl −5 gehört zu y: y = −2 + (−5) = −7. Zeile 2: Die zweite Zahl 4 gehört zu x: x = 3 + 4 = 7. Zeile 3: Das Bild ist P'(7 | −7). In welcher Zeile passiert der erste Fehler?"}, "a": ["In Zeile 1", "In Zeile 2", "In Zeile 3"], "o": {"index": 0}, "h": "Welche Zahl des Vektors gehört zu x?", "w": "Die erste Zahl gehört zu x: x = 3 + (−5) = −2. Die zweite zu y: y = −2 + 4 = 2. Richtig: P'(−2 | 2).", "form": "fehler_detektiv", "zaehlt": "ja", "r": 738}, {"l": "gegenvektor", "t": "gegenvektor", "p": "uebung", "s": 3, "g": "fehler", "y": "auswahl", "f": {"text": "Der Punkt P'(1 | −4) entstand durch die Verschiebung mit v = (6 | −2). Kim sucht den Urpunkt P. Zeile 1: Der Gegenvektor ist −v = (−6 | −2). Zeile 2: Neue x-Zahl: 1 + (−6) = −5. Zeile 3: Neue y-Zahl: −4 + (−2) = −6. In welcher Zeile passiert der erste Fehler?"}, "a": ["In Zeile 1", "In Zeile 2", "In Zeile 3"], "o": {"index": 0}, "h": "Beim Gegenvektor ändern sich beide Vorzeichen.", "w": "Aus (6 | −2) wird (−6 | 2). Dann y: −4 + 2 = −2. Richtig: P(−5 | −2).", "form": "fehler_detektiv", "zaehlt": "ja", "r": 739}, {"l": "vektor_koordinaten", "t": "vektor_koordinaten", "p": "uebung", "s": 3, "g": "fehler", "y": "auswahl", "f": {"text": "Kim berechnet den Vektor von A(5 | −2) nach B(1 | 4). Zeile 1: Regel: Anfang minus Ende. Zeile 2: Erste Zahl: 5 − 1 = 4. Zeile 3: Zweite Zahl: −2 − 4 = −6. In welcher Zeile passiert der erste Fehler?"}, "a": ["In Zeile 1", "In Zeile 2", "In Zeile 3"], "o": {"index": 0}, "h": "Beim Vektor von A nach B: Welcher Punkt steht in der Rechnung vorn?", "w": "Ende minus Anfang: 1 − 5 = −4 und 4 − (−2) = 6. Der Vektor ist (−4 | 6).", "form": "fehler_detektiv", "zaehlt": "ja", "r": 740}, {"l": "vektor_koordinaten", "t": "vektor_koordinaten", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Ein Vektor führt vom Punkt A(−2|3) zum Punkt B(5|−1). Weg A: die x-Werte voneinander abziehen (Endpunkt minus Anfangspunkt). Weg B: erst von −2 bis zur y-Achse gehen, dann von dort bis 5. Wie viele Einheiten geht der Vektor in x-Richtung?"}, "o": {"wert": 7}, "h": "Beide Wege messen den Weg auf der x-Achse von −2 bis 5.", "w": "Weg A: 5 − (−2) = 7. Weg B: von −2 bis 0 sind es 2 Einheiten, von 0 bis 5 sind es 5 Einheiten, zusammen 7. Der Vektor geht 7 Einheiten nach rechts.", "form": "zwei_wege", "zaehlt": "ja", "r": 741}, {"l": "verschiebung", "t": "verschiebung", "p": "uebung", "s": 2, "g": "umkehr", "y": "zahl", "f": {"text": "Eine Verschiebung um den Vektor (4|−3) bildet den Punkt P auf den Bildpunkt P′(9|2) ab. Wie groß ist die Summe der beiden Koordinaten von P?"}, "o": {"wert": 10}, "h": "Gehe vom Bildpunkt den Vektor rückwärts.", "w": "Rückwärts gehen heißt abziehen: x = 9 − 4 = 5 und y = 2 − (−3) = 5. Also ist P(5|5), und die Summe ist 10.", "form": "umkehren", "zaehlt": "ja", "r": 742}]$auf$::jsonb),
    (308, 'abbildungen.kongruenz_teil3', 751, 9, $auf$[{"l": "vektor_drehen", "t": "vektor_drehen", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Der Vektor v zeigt von A(1 | 2) nach B(5 | 9): v = (5 − 1 | 9 − 2) = (① | ②). Eine Drehung um +90° macht aus (x | y) den Vektor (−y | x). Gedreht ist v also (③ | ④).", "schablone": "① = □; ② = □; ③ = □; ④ = □", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ)."}, "o": {"werte": [4, 7, -7, 4]}, "h": "Die zweite Zahl wird zur ersten, mit anderem Vorzeichen.", "w": "v = (4 | 7). Gedreht um +90°: (−7 | 4).", "form": "lueckenweg", "zaehlt": "nein", "r": 757}, {"l": "punktspiegelung", "t": "punktspiegelung", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "auswahl", "f": {"text": "Der Punkt P(7 | −2) wird am Punkt Z(3 | 4) gespiegelt. Welche Rechnung liefert den Bildpunkt P'?"}, "a": ["x: 7 − 3 = 4 und y: −2 − 4 = −6, also P'(4 | −6)", "x: 2 · 3 − 7 = −1 und y: 2 · 4 − (−2) = 10, also P'(−1 | 10)", "x: −7 und y: 2, also P'(−7 | 2)", "x: 3 − 7 = −4 und y: 4 − (−2) = 6, also P'(−4 | 6)"], "o": {"index": 1}, "h": "Z ist die Mitte von P und P'. Zum Doppelten von Z gehört noch etwas dazu.", "w": "Z ist die Mitte: P' = 2 · Z − P. x: 6 − 7 = −1. y: 8 + 2 = 10.", "form": "verfahren_waehlen", "zaehlt": "ja", "r": 758}, {"l": "drehung", "t": "drehung", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "auswahl", "f": {"text": "Der Punkt P(3 | 5) wird um O(0 | 0) um 90° im Uhrzeigersinn gedreht. Welche Rechnung ist richtig?"}, "a": ["(x | y) wird (−y | x), also P'(−5 | 3)", "(x | y) wird (−x | −y), also P'(−3 | −5)", "(x | y) wird (y | −x), also P'(5 | −3)", "(x | y) wird (y | x), also P'(5 | 3)"], "o": {"index": 2}, "h": "Im Uhrzeigersinn ist die Gegenrichtung zu „gegen den Uhrzeigersinn“.", "w": "Im Uhrzeigersinn um 90°: (x | y) wird (y | −x). Aus (3 | 5) wird (5 | −3).", "form": "verfahren_waehlen", "zaehlt": "ja", "r": 759}, {"l": "vektor_drehen", "t": "vektor_drehen", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "auswahl", "f": {"text": "Der Vektor v = (2 | 5) wird zweimal hintereinander um +90° gedreht. Welcher Vektor entsteht?"}, "a": ["(−5 | 2)", "(5 | −2)", "(2 | −5)", "(−2 | −5), denn zweimal 90° sind zusammen 180°"], "o": {"index": 3}, "h": "Zweimal 90° ergibt eine Drehung um wie viel Grad?", "w": "Erst (2 | 5) → (−5 | 2), dann (−5 | 2) → (−2 | −5). Das ist eine Drehung um 180°.", "form": "verfahren_waehlen", "zaehlt": "ja", "r": 760}, {"l": "punktspiegelung", "t": "punktspiegelung", "p": "uebung", "s": 3, "g": "fehler", "y": "auswahl", "f": {"text": "Kim spiegelt P(6 | 3) am Punkt Z(2 | 1). Zeile 1: Von P nach Z geht man 4 nach links und 2 nach unten. Zeile 2: Von Z aus geht man denselben Weg weiter: x: 2 − 4 = −2 und y: 1 + 2 = 3. Zeile 3: Das Bild ist P'(−2 | 3). In welcher Zeile passiert der erste Fehler?"}, "a": ["In Zeile 1", "In Zeile 2", "In Zeile 3"], "o": {"index": 1}, "h": "„Nach unten“ heißt, dass y kleiner wird. Das gilt auch beim zweiten Teil des Weges.", "w": "Von Z aus geht es 2 nach unten: y = 1 − 2 = −1. Richtig: P'(−2 | −1).", "form": "fehler_detektiv", "zaehlt": "ja", "r": 761}, {"l": "drehung", "t": "drehung", "p": "uebung", "s": 3, "g": "fehler", "y": "auswahl", "f": {"text": "Kim dreht P(4 | 1) um O(0 | 0) um 180°. Zeile 1: Bei 180° wird aus (x | y) der Punkt (−x | −y). Zeile 2: Aus x = 4 wird 4. Zeile 3: Aus y = 1 wird −1. Das Bild ist P'(4 | −1). In welcher Zeile passiert der erste Fehler?"}, "a": ["In Zeile 1", "In Zeile 2", "In Zeile 3"], "o": {"index": 1}, "h": "Bei 180° wechseln beide Zahlen das Vorzeichen.", "w": "Aus x = 4 wird −4 und aus y = 1 wird −1. Richtig: P'(−4 | −1).", "form": "fehler_detektiv", "zaehlt": "ja", "r": 762}, {"l": "vektor_drehen", "t": "vektor_drehen", "p": "uebung", "s": 3, "g": "fehler", "y": "auswahl", "f": {"text": "Kim dreht den Vektor v = (6 | −2) um −90°. Die Regel lautet: Aus (x | y) wird (y | −x). Zeile 1: x = 6 und y = −2. Zeile 2: Die neue erste Zahl ist y = −2. Zeile 3: Die neue zweite Zahl ist x = 6. In welcher Zeile steckt der Fehler?"}, "a": ["In Zeile 1", "In Zeile 2", "In Zeile 3"], "o": {"index": 2}, "h": "In der Regel steht bei der zweiten Zahl ein Minus.", "w": "Die zweite Zahl ist −x = −6. Richtig: (−2 | −6).", "form": "fehler_detektiv", "zaehlt": "ja", "r": 763}, {"l": "drehung", "t": "drehung", "p": "uebung", "s": 2, "g": "darstellung", "y": "auswahl", "f": {"text": "Eine Drehung um den Ursprung wird durch die Regel (x|y) → (−y|x) beschrieben. Um welchen Winkel dreht sie?"}, "a": ["90° gegen den Uhrzeigersinn", "90° im Uhrzeigersinn", "180°", "Spiegelung an der Geraden y = x"], "o": {"index": 0}, "h": "Probiere die Regel mit dem Punkt (1|0) aus und schau, wohin er wandert.", "w": "Der Punkt (1|0) wird zu (0|1). Er wandert von der x-Achse zur y-Achse, also um 90° gegen den Uhrzeigersinn. Ein Punkt (3|1) würde zu (−1|3), das passt zur Drehung gegen den Uhrzeigersinn.", "form": "bruecke", "zaehlt": "ja", "r": 764}, {"l": "vektor_drehen", "t": "vektor_drehen", "p": "uebung", "s": 2, "g": "umkehr", "y": "zahl", "f": {"text": "Ein Vektor wird um 90° gegen den Uhrzeigersinn gedreht. Dabei wird aus (x|y) der Vektor (−y|x). Der gedrehte Vektor ist (−9|5). Wie groß ist die Summe der beiden Koordinaten des ursprünglichen Vektors?"}, "o": {"wert": 14}, "h": "Vergleiche (−y|x) mit (−9|5): Welche Zahl ist x, welche y?", "w": "Aus (−y|x) = (−9|5) folgt −y = −9, also y = 9, und x = 5. Der ursprüngliche Vektor ist (5|9). Die Summe ist 5 + 9 = 14.", "form": "umkehren", "zaehlt": "ja", "r": 765}]$auf$::jsonb)
  ) x(id, schluessel, max_r, soll, aufgaben) loop
    if not exists (select 1 from schule.einheit ei join schule.thema th on th.id = ei.thema_id where ei.id = e.id and th.schluessel = e.schluessel) then
      fehler := fehler || ('Einheit ' || e.id || ' ist nicht ' || e.schluessel)::text; continue; end if;
    if (select coalesce(max(reihenfolge), 0) from schule.aufgabe where einheit_id = e.id and pool = 'uebung' and reihenfolge <= e.max_r) <> e.max_r then
      fehler := fehler || ('Einheit ' || e.id || ': Bestand hat sich seit dem Lesen geändert')::text; continue; end if;
    if exists (select 1 from schule.aufgabe a where a.einheit_id = e.id and a.pool = 'uebung' and a.reihenfolge in (select (x->>'r')::int from jsonb_array_elements(e.aufgaben) x)) then
      fehler := fehler || ('Einheit ' || e.id || ': Reihenfolge-Nummern des Pakets sind schon belegt (Paket schon eingespielt?)')::text; continue; end if;
    if exists (select 1 from jsonb_array_elements(e.aufgaben) x where not exists (select 1 from schule.einheit ei, jsonb_array_elements(ei.inhalt->'etappen') et where ei.id = e.id and et->>'lernziel' = x->>'l')) then
      fehler := fehler || ('Einheit ' || e.id || ': Lernziel unbekannt')::text; continue; end if;
    select count(*) into vorher from schule.aufgabe where einheit_id = e.id;
    n := schule.aufgaben_einfuegen(e.id, e.aufgaben);
    if n <> e.soll or (select count(*) from schule.aufgabe where einheit_id = e.id) <> vorher + e.soll then
      fehler := fehler || ('Einheit ' || e.id || ': ' || n || ' statt ' || e.soll || ' eingefügt')::text; end if;
    if (select count(*) from schule.aufgabe a where a.einheit_id = e.id and a.reihenfolge in (select (x->>'r')::int from jsonb_array_elements(e.aufgaben) x) and a.pool = 'uebung' and a.form is not null and a.zaehlt is not null) <> e.soll then
      fehler := fehler || ('Einheit ' || e.id || ': form/zaehlt nicht übernommen')::text; end if;
    if exists (select 1 from schule.aufgabe a where a.einheit_id = e.id and a.reihenfolge in (select (x->>'r')::int from jsonb_array_elements(e.aufgaben) x) and a.pool = 'uebung'
               and not coalesce((schule.antwort_bewerten(a, case a.antworttyp when 'zahl' then jsonb_build_object('wert', '0') else '{}'::jsonb end)->>'format_ok') is not null, false)) then
      fehler := fehler || ('Einheit ' || e.id || ': eine neue Aufgabe lässt sich nicht bewerten')::text; end if;
    gesamt := gesamt + n;
  end loop;
  if gesamt <> 307 then fehler := fehler || ('zusammen ' || gesamt || ' statt 307')::text; end if;
  if array_length(fehler, 1) > 0 then raise exception 'Vorrats-Aufgaben ABBRUCH, alles zurückgerollt: %', array_to_string(fehler, ' | '); end if;
end $einspielen$;
select einheit_id, count(*) filter (where pool = 'uebung') as uebungen, count(*) filter (where form is not null) as mit_form from schule.aufgabe where einheit_id in (4, 6, 13, 16, 17, 22, 27, 40, 47, 48, 49, 50, 51, 54, 55, 57, 67, 92, 304, 306, 307, 308) group by 1 order by 1;
